/* Bestiarium – Horror Companion (Kreaturen, Werte übersetzt). Quelle HOR */
(window.SW_KR = window.SW_KR || []).push.apply(window.SW_KR, [{"n":"Ama-no-jaku","k":"Monster","w":0,"s":["HOR"],"p":102,"bk":"sw_hor","d":["Frei übersetzt „Himmelsimp“: Ama-no-jaku sind kleine Wesen aus Japan, die Sterbliche versuchen und zu Unfug anstiften. Oft tun sie das, indem sie vorgeben, etwas zu sein, was sie nicht sind – etwa ein menschliches Kind oder ein wohlwollender Geist.","Ama-no-jaku (manchmal Amanojaku) besitzen keine magische Fähigkeit, ihr Aussehen zu verbergen, und müssen deshalb natürliche Verkleidungen tragen, etwa Leichentücher oder die Haut ihrer Opfer."],"a":[["Geschicklichkeit","W10"],["Konstitution","W6"],["Stärke","W4"],["Verstand","W10"],["Willenskraft","W6"]],"f":"Allgemeinwissen W8, Athletik W8, Darbietung W10, Diebeskunst W10, Heimlichkeit W10, Kämpfen W6, Provozieren W12, Wahrnehmung W8, Überreden W12","b":"10","pa":"5","ro":"5","x":[["Talente","Entwaffnen (Verb.), Flink"],["Ausrüstung","Die Dämonen locken ihre Opfer am liebsten in Todesfallen (siehe unten), schlitzen aber auch mit Wonne mit fiesen (oft infizierten) Messern (Stä+W4) und ziehen sich dann in die Schatten zurück"]],"sf":[["Verschwimmen","Ama-no-jaku bewegen sich mit übernatürlicher Geschwindigkeit. Angriffe gegen sie erfolgen mit –4."],["Verteidiger","Manche Ama-no-jaku halten ihre verblendetsten Opfer als Wächter in der Nähe, wenn sie mit aufmerksameren Gruppen zu tun haben. Eine solche Person ist meist ein gewöhnlicher Mann oder eine gewöhnliche Frau, der oder dem eingeredet wurde, der Dämon sei der Geist eines Kindes, ein freundlicher Geist usw. und neue Eindringlinge wollten ihm Böses."],["Fallen","Ama-no-jaku haben große Freude daran, ihre Opfer in zahlreiche Fallen zu locken, die sie rund um ihre Verstecke angelegt haben. Immer wenn die Aktionskarte eines Charakters im Kampf ein Kreuz ist und der Kampf im Versteck der Kreatur oder an einem Ort stattfindet, den sie vorbereiten konnte, tappt das Opfer in eine Falle. Die SL kann die Auswirkungen selbst festlegen oder die Tabelle Ama-no-jaku-Fallen verwenden."],["#","Ama-no-jaku-Fallen"],["Zwei","Der Charakter stolpert in eine tödliche Falle wie eine herabstürzende Decke oder eine Stachelgrube und erleidet 3W10 Schaden."],["Drei bis Zehn","Der Held tappt in eine gefährliche Falle und erleidet 3W6 Schaden. Das können vergiftete Pungi-Stäbe, herabfallende Ziegel oder eine tödliche Schlange sein, die in einem verborgenen Bereich lauert."],["Bube bis König","Der Held erleidet Beulen und Blessuren durch eine harmlose Falle."],["Ass","Der Held bemerkt die Falle gerade noch rechtzeitig. Er verliert seinen Zug, bleibt aber unverletzt."]]},{"n":"Alligator-Löwen-Hybrid","k":"Monster","w":0,"s":["HOR"],"p":102,"bk":"sw_hor","g":"Tierhybriden","d":["Diese Abscheulichkeit hat den Körper eines Löwen sowie Haut, Schwanz und Kiefer eines Alligators. Zusätzliche Veränderungen erlauben ihr, unter Wasser zu funktionieren. Sie sind besonders mürrisch und leicht zu erzürnen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12"],["Verstand","W6 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8","b":"5","pa":"6","ro":"11 (2)","x":[["Talente","Raserei (Verb.)"]],"sf":[["Wasserwesen","Bewegungsweite 5."],["Panzerung +2","Dicke Haut."],["Biss/Klauen","Stä+W6."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Anspringen","Addiere +4 statt +2 auf den Schaden bei einem Rücksichtslosen Angriff."],["Überrollen","Trifft die Bestie bei einem Bissangriff mit einer Steigerung, verursacht sie +1W10 Bonusschaden statt der üblichen +1W6."],["Größe 2","Diese Bestie wiegt über 225 kg."]]},{"n":"Mensch-Hund-Hybrid","k":"Tiere","w":0,"s":["HOR"],"p":103,"bk":"sw_hor","g":"Tierhybriden","d":["Ein Mensch-Hund-Hybrid ist humanoid, mit Fell bedeckt und hat Kopf und Schwanz eines Hundes. Er geht gebückt, kann zwar aufrecht rennen, bewegt sich aber lieber auf allen vieren. Seine Finger enden in kleinen Klauen und sind geschickt genug, um Waffen und Werkzeuge zu benutzen. Diese üblen Bestien können sprechen, wenn auch mit rauer, knurrender Stimme."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W6 (A)"],["Willenskraft","W6"]],"f":"Allgemeinwissen W4, Athletik W6, Heimlichkeit W6, Kämpfen W6, Schießen W6, Wahrnehmung W10, Überreden W4","b":"8","pa":"5","ro":"5","x":[["Talente","Aufmerksamkeit, Flink"],["Ausrüstung","Was auch immer sein Herr ihm gibt"]],"sf":[["Biss/Klauen","Stä+W4."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."]]},{"n":"Mensch-Insekt-Hybrid","k":"Monster","w":0,"s":["HOR"],"p":103,"bk":"sw_hor","g":"Tierhybriden","d":["Ein Mensch-Insekt-Hybrid ist humanoid, hat aber den abscheulichen Kopf und die Arme eines Insekts wie einer Gottesanbeterin oder Wespe. Ob durch Magie oder einen tragischen wissenschaftlichen Unfall entstanden, diese Kreaturen leben nicht lange und folgen in der Zeit, die ihnen bleibt, ihrem Instinkt zu jagen und zu töten. Diese scheußlichen Kreaturen können mit hoher, summender Stimme sprechen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Athletik W6, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W8, Überleben W4","b":"6","pa":"7","ro":"7","x":[["Talente","Aufmerksamkeit, Block, Ausweichen"]],"sf":[["Biss","Stä+W6."],["Furcht (–2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Widerstandsfähig","Kann eine zusätzliche Wunde einstecken."],["Wandkrabbler","Kann mit voller Bewegungsweite an senkrechten oder überhängenden Flächen laufen und darf rennen."]]},{"n":"Mensch-Reptil-Hybrid","k":"Monster","w":0,"s":["HOR"],"p":103,"bk":"sw_hor","g":"Tierhybriden","d":["Ein Mensch-Reptil-Hybrid ist ein mit Schuppen bedecktes Humanoider. Er hat Kiemen, Klauen und scharfe Reptilienzähne. Er besitzt zwar Finger, doch sie sind entweder mit Schwimmhäuten versehen oder zu dick, um Waffen und Werkzeuge zu benutzen.","Manche Hybriden sind zu zischelnder Sprache fähig."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W10"],["Verstand","W4"],["Willenskraft","W6"]],"f":"Allgemeinwissen W4, Athletik W8, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6, Überleben W6, Überreden W4","b":"6","pa":"6","ro":"8 (2)","x":[["Talente","Raserei"]],"sf":[["Wasserwesen","Bewegungsweite 6."],["Panzerung +2","Schuppenhaut."],["Biss/Klauen","Stä+W6."],["Kaltblütig","Ziehe nach mehr als 10 Minuten bei unter 15 °C 1 von Geschicklichkeits-, Stärke- und Konstitutionsproben ab."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Überrollen","Trifft die Kreatur bei einem Bissangriff mit einer Steigerung, verursacht sie +1W10 Bonusschaden statt der üblichen +1W6."]]},{"n":"Kolossameise","k":"Tiere","w":0,"s":["HOR"],"p":104,"bk":"sw_hor","d":["Gewöhnliche Ameisen können Krieg führen, Vieh verschlingen und bei einem Amoklauf ganze Landstriche verwüsten. Viel größere Riesenameisen (und andere Riesen-Insekten) finden sich im Fantasy Companion.","Kolossameisen sind titanische Monster, die Schaden in gewaltigem Ausmaß anrichten können. Das folgende Profil gilt für die Krieger, die die Königin beschützen und die Tunnel des Stocks verlassen, um Nahrung zu suchen. Sie haben sechs Beine, Facettenaugen und gefährliche Mandibeln, die ein Auto zerquetschen können. Spähtrupps bestehen aus einem bis fünf Kriegern. Der Stock selbst enthält Hunderte, manchmal Tausende dieser Monster.","Der Stock muss überleben!: Wie die meisten Ameisen graben diese kolossalen Vettern ausgeklügelte Tunnelsysteme mit Vorratskammern voll verrottendem Fleisch (Kühe, Leichen oder was vor Ort eben verfügbar ist). Ganz unten sitzt eine unbewegliche Königin, die alle Eier der Kolonie legt. Wenn sich eine Kolonie ausbreiten will – oder bedroht wird –, gebiert sie neue Königinnen, die mit Flügeln schlüpfen und davonfliegen, um einen neuen Tunnel zu graben und von vorn zu beginnen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12+6"],["Verstand","W4 (A)"],["Willenskraft","W10"]],"f":"Athletik W8, Heimlichkeit W8, Kämpfen W10, Wahrnehmung W6, Überleben W6","b":"8","pa":"7","ro":"13 (2)","x":[["Handicaps","Schlechte Augen (Schwer)"],["Talente","Erstschlag, Schnell"]],"sf":[["Panzerung +2","Panzerplatten."],["Biss","Stä+W8, 2."],["Furcht","Der Wurf erhält –2, wenn mehr als ein Dutzend Ameisen anwesend sind."],["Größe 4 (Groß)","Kolossameisen sind 4,5 m lang und wiegen über eine Tonne."],["Wandkrabbler","Kann mit voller Bewegungsweite an senkrechten (aber nicht überhängenden) Flächen laufen und darf rennen."],["#","Variante Spezialfähigkeiten"],["","Es gibt viele verschiedene Ameisenarten, jede mit ihren eigenen Anpassungen zum Überleben."],["Graben (Bewegungsweite 8)","Kann sich durch alles außer massivem Stein graben; kann unter der Erde nur durch besondere Mittel angegriffen werden."],["Intelligenz","Der Stock als Ganzes wird empfindungsfähig. Einzelne Ameisen haben weiterhin tierische Intelligenz, doch gemeinsam kann der Stock Fallen stellen, Pläne schmieden und sogar manche Technologie nutzen. Wissen, das eine Ameise erlangt, besitzen ab der folgenden Runde alle. Das Leben einzelner Ameisen ist für die Intelligenz unwichtig, nur das Überleben der Kolonie als Ganzes zählt."],["Lähmung","Wer durch den Biss der Ameise Erschüttert oder verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er gelähmt und für 2W6 Runden zu keiner Aktion fähig – auch nicht zum Sprechen."],["Gift (Tödlich)","Wer durch den Biss der Ameise Erschüttert oder verwundet wird, muss eine Konstitutionsprobe ablegen. Misslingt sie, ist er Betäubt, erleidet eine Wunde (zwei bei einem Kritischen Fehlschlag) und stirbt in 2W6 Runden."],["Giftsprühen","Als Aktion kann die Ameise einen Giftstrahl in einer Kegelschablone erbrechen. Sie würfelt Athletik, um zu treffen, und die Ziele erleiden die Wirkung der Spezialfähigkeit Gift der Kreatur. Ausweichen vermeidet den Angriff."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Zombies","Ein spezielles Pheromon kapert das Nervensystem von Zielen, die durch Ameisengift getötet wurden. Die Leiche führt weiterhin eine einprogrammierte Aufgabe aus, obwohl sie tot ist. Bei Kriegern erhalten sie die Spezialfähigkeit Untot. Bei einem Menschen wird das Ziel zu einem Zombie (S. 176)."]]},{"n":"Aswang","k":"Monster","w":1,"s":["HOR"],"p":105,"bk":"sw_hor","d":["Ein Aswang ist eine vampirähnliche Kreatur von den Philippinen. Tagsüber nimmt er die Gestalt einer schönen Frau an und führt ein normales menschliches Leben, heiratet sogar und bekommt Kinder. Nachts jedoch wird er zu einem blutsaugenden Unhold. Mit seiner unglaublich langen, hohlen Zunge saugt er Blut ab und lässt sie lieber durch Ritzen im Dach nach unten gleiten, als Gebäude zu betreten. Anders als echte Vampire ist der Aswang jedoch nicht untot.","Die menschliche Gestalt hat ein beliebiges Profil, das die Spielleitung vergeben möchte (etwa Unschuldiges Opfer auf S. 169), ist aber immer Sehr Attraktiv. Das folgende Profil gilt für seine vampirische Gestalt."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W10, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W8, Überreden W8","b":"6","pa":"7","ro":"7","sf":[["Blutentzug","Gepackte Gegner müssen beim Packen und zu Beginn des Zugs des Vampirs eine Konstitutionsprobe ablegen, solange sie Gebunden oder Festgehalten bleiben. Ein Fehlschlag führt zu Erschöpfung, die zum Tod führen kann. Festgehaltene Opfer mit einem Messer oder einem Verbündeten können versuchen, die Zunge zu durchtrennen (Robustheit 3)."],["Schattenlecken","Eine Person, deren Schatten von einem Aswang geleckt wird, ist verflucht. Das ist ein schadensloser Berührungsangriff, wenn das Opfer es bemerkt und Widerstand versucht. Einmal verflucht, zählt für die nächsten 24 Stunden jeder misslungene Konstitutionswurf des Opfers stattdessen als Kritischer Fehlschlag."],["Zungenpeitsche","Stä+W4, Reichweite 2."],["Schwäche (Morgendämmerung)","Ein Aswang kehrt beim ersten Morgenstrahl automatisch in seine menschliche Gestalt zurück."],["Schwäche (Knoblauch)","Ein Aswang ist Abgelenkt, wenn er sich innerhalb von 1“ (2 m) von Knoblauch befindet."]]},{"n":"Banshee","k":"Geister","w":1,"s":["HOR"],"p":105,"bk":"sw_hor","d":["Traditionelle Banshees sind weibliche Geister in einer von drei Gestalten – als junges Mädchen, als matronenhafte Gestalt oder als altes Weib. Alle tragen entweder einen dunklen Kapuzenmantel oder ein Leichentuch. Ihre langen Nägel können Fleisch zerreißen, doch ihre meistgefürchtete Macht ist ihr schrecklicher Schrei, der einen Mann in den Wahnsinn treiben oder gar töten kann.","Eine Variante der Banshee, bekannt als „Waschfrau“, erscheint als Gestalt im Umhang, die blutbefleckte Kleider wäscht. Der Legende nach sind dies die Gewänder derer, die durch ihr Wehklagen sterben werden."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W6, Einschüchtern W10, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W8, Überreden W4","b":"6","pa":"5","ro":"6","sf":[["Biss/Klauen","Stä+W4."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Materialisieren","Kann als begrenzte freie Aktion körperlich werden und erscheint dabei als Geist oder so, wie sie im Leben aussah."],["Schrei","Einmal pro Nacht und erneut, wann immer die Aktionskarte einer Banshee im Kampf ein Bild ist, kann sie als einzige Aktion ihren berüchtigten Schrei ausstoßen. Jeder innerhalb von 12“ (24 m) muss eine Willenskraftprobe ablegen oder stirbt. Wer Erfolg hat, muss auf der Tabelle Furchteffekte (S. 43) würfeln und ist Betäubt."],["Heulen","Die Banshee kann ein unirdisches Wehklagen ausstoßen, das alle erschreckt, die es hören. Als begrenzte Aktion kann die Banshee eine Einschüchtern-Herausforderung in einer Kegelschablone ausführen. Alle Ziele darin sind betroffen und müssen einzeln widerstehen."]]},{"n":"Grabhügelbewohner","k":"Untote","w":1,"s":["HOR"],"p":106,"bk":"sw_hor","d":["Auch als Wights und Hagbui (wörtlich „Grabhügelbewohner“) bekannt, sind diese Untoten die körperlichen Überreste von Königen, Königinnen und Helden, die in längst vergangenen Zeiten bestattet wurden. Sie sind in Nordeuropa verbreitet, besonders in den Gebieten, in denen sich die Wikinger niederließen. Ihre Gestalt ist die einer mumifizierten Leiche, deren straffe, ledrige Haut über verdorrte Muskeln gespannt ist. Ihre Augen brennen mit einem fahlen, kalten Licht. Obwohl Grabhügelbewohner sprechen können, tun sie das nur in Sprachen, die sie zu ihren Lebzeiten kannten. Ihre Gräber quellen oft über vor Schätzen, und sie wollen dafür sorgen, dass das für alle Ewigkeit so bleibt."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6, Zaubern W8","b":"6","pa":"6","ro":"12 (3)","x":[["Talente","Konter, Mächtiger Hieb"],["Mächte","Dunkelheit (Nebel), Furcht (unirdischer Schrei), Eigenschaft senken (Fluch), Tempo (übernatürliche Reflexe) (Machtpunkte: 15)"],["Ausrüstung","antiker Bronzebrustpanzer (+3), Bronze-Langschwert (Stä+W8)"]],"sf":[["Knochenklauen","Stä+W4."],["Gebunden","Ein Grabhügelbewohner darf sich nicht weiter als 50“ (100 m) von seiner Grabstätte entfernen."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Betäubende Berührung","Jede von einem Grabhügelbewohner berührte Kreatur muss eine Konstitutionsprobe ablegen oder ist Betäubt."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Heulen","Ein Grabhügelbewohner kann ein unirdisches Wehklagen ausstoßen, das alle erschreckt, die es hören. Als begrenzte Aktion kann das Wesen eine Einschüchtern-Herausforderung in einer Kegelschablone ausführen. Alle Ziele darin sind betroffen und müssen einzeln widerstehen."],["Schwäche (Sonnenlicht)","Grabhügelbewohner werden von der Sonne geschwächt. Jede Runde im Sonnenlicht müssen sie eine Konstitutionsprobe ablegen oder erleiden eine Stufe Erschöpfung. Das kann sie nicht töten, lässt sie aber ausgetrocknet und hilflos zurück, bis sie aus dem Licht entfernt und mit einem Blutopfer wiederhergestellt werden."]]},{"n":"Riesenfledermaus","k":"Tiere","w":0,"s":["HOR"],"p":106,"bk":"sw_hor","d":["Riesenfledermäuse findet man meist in Gruppen von 2W6 Mitgliedern. Sie sind selten aggressiv, außer wenn sie in ihrem Bau gereizt werden oder unter der Kontrolle eines finsteren Herrn stehen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Athletik W6, Heimlichkeit W10, Kämpfen W6, Wahrnehmung W12","b":"1","pa":"5","ro":"4","sf":[["Biss","Stä."],["Echoortung","Riesenfledermäuse erleiden keine Abzüge durch schlechte Beleuchtung, selbst in Pechschwarzer Dunkelheit nicht."],["Flug","Bewegungsweite 8."],["Größe -1","Riesenfledermäuse sind im Körper etwa so groß wie mittelgroße Hunde und haben 2,7 m Flügelspannweite."]]},{"n":"Der Schwarze Kutscher","k":"Geister","w":1,"s":["HOR"],"p":107,"bk":"sw_hor","d":["Der Schwarze Kutscher existiert in der einen oder anderen Form seit Jahrtausenden. Die Ägypter kannten ihn als „dunklen Wagenlenker“, die Römer als „schwarzen Reiter“ und die Normannen nannten ihn „Todesfuhrmann“. Sein heutiger Name stammt aus viktorianischer Zeit.","Der Kutscher erscheint nur, wenn er durch ein Ritual beschworen wird (verwende die Macht Dämon beschwören mit Kosten von 13 Machtpunkten und einer Dauer von 13 Nächten). Eine zusätzliche Zutat ist eine mit dem Blut des Zaubernden geschriebene Schriftrolle mit bis zu 13 Namen – den Namen derer, die der Schwarze Kutscher jagen wird!","Der Kutscher beginnt seine Fahrt 13 Minuten nach dem nächsten Mitternachtsschlag und befährt die Straßen im Umkreis von 13 Meilen um den Ort seiner Beschwörung. Er bleibt 13 Nächte in der sterblichen Welt und holt seine Beute mit unfehlbarer Treffsicherheit.","Der Kutscher hält sich am liebsten im Schatten auf und wartet geduldig auf seiner Kutsche in einer dunklen Gasse oder auf einem Feldweg, bis er seine Beute spürt. Wird jedoch offensichtlich, dass sich seine Beute versteckt, steigt der Kutscher bereitwillig ab, dringt in Häuser oder Gebäude ein und erschlägt jeden, der ihm im Weg steht.","Hat er eines seiner genannten Opfer geholt, verschwindet der Kutscher für die Nacht, sofern nicht unmittelbar ein weiteres in Sichtweite ist. Kann er ein Opfer vor der Morgendämmerung nicht erreichen, verschwindet er und erscheint jede Nacht erneut, bis alle seine Opfer eingesammelt sind, seine Zeit abläuft oder er erschlagen wird."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W8, Athletik W10, Einschüchtern W12, Fahren W10, Heimlichkeit W6, Kämpfen W8, Reiten W10, Wahrnehmung W8, Überleben W10","b":"6","pa":"6","ro":"9","x":[["Talente","Block, Lieblingswaffe (Erntende Sense)"]],"sf":[["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Unverwundbar","Der Kutscher kann durch magische Angriffe oder Waffen Ausgeschaltet werden, erscheint aber in der folgenden Nacht wie gewohnt wieder. Der einzige Weg, die Kreatur dauerhaft zu erschlagen, ist ein Zauber Bannen. Würde eine Wunde verursacht, verliert die Kreatur stattdessen für die nächsten 13 Minuten ihre Unverwundbarkeit. Der Tod in diesem Zustand öffnet auf dem Boden ein Portal zur Hölle. Einen Augenblick später steigt eine Horde Dämonen empor und schleift den schreienden Kutscher in den Abgrund – bis er erneut beschworen wird!"],["Erntende Sense","Gegen seine genannten Ziele verursacht die Sense keinen Schaden, doch wer von ihr getroffen wird, muss eine Willenskraftprobe mit –4 ablegen oder wird „geholt“. Wer geholt wird, fällt in Starre (Ausgeschaltet), lebendig, aber reaktionslos, bis der Kutscher seine Aufgabe beendet und seine Ziele in der Hölle abliefert. Gegen alle anderen Opfer verursacht die Sense Stä+W10 Schaden. Wird der Kutscher in seinem verwundbaren Zustand besiegt, erwachen geholte Opfer Erschöpft."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Unfehlbarer Spurenleser","Der Kutscher kann jede Person auf seiner Liste spüren, solange sie sich innerhalb der 13 Meilen seines Jagdradius befindet. Seine Sinne führen ihn auf 50 m an jedes Opfer heran, danach muss er sich auf sein Überleben (Spurenlesen) verlassen, um ihren genauen Aufenthaltsort zu finden."]]},{"n":"Pferde des Schwarzen Kutschers","k":"Geister","w":0,"s":["HOR"],"p":108,"bk":"sw_hor","d":["Vier Hengste mit pechschwarzem Fell und Augen wie glühende Kohlen ziehen die schwarze Kutsche des Kutschers. Es gibt keine Zügel, die sie mit der Kutsche verbinden, nur Stränge aus tintiger Schwärze."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+4"],["Verstand","W6 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Kämpfen W8, Wahrnehmung W8","b":"10","pa":"6","ro":"10","x":[["Talente","Raufbold, Flink"]],"sf":[["Geisterhafter Galopp","Schwarze Pferde laufen knapp über dem Boden und erleiden keine Bewegungsabzüge für Schwieriges Gelände."],["Tritt","Stä+W6."],["Größe 2","Schwarze Pferde wiegen zwischen 360 und 450 kg."]]},{"n":"Schwarzäugiges Kind","k":"Geister","w":0,"s":["HOR"],"p":108,"bk":"sw_hor","d":["Schwarzäugige Kinder, kurz BEKs, sind geheimnisvolle Kreaturen aus einem Reich reiner Finsternis. Sie ähneln Vampiren in vielerlei Hinsicht, sind aber weder Vampire noch untot. Sie hungern nach Fleisch und nehmen die Gestalt menschlicher Kinder an, um unschuldig und hilflos zu erscheinen und ihre Beute anzulocken. Wie ihr Name schon sagt, sind ihre Augen tiefschwarz.","Schwarzäugige Kinder verbergen ihre ungewöhnlichen Augen meist hinter dunklen Brillen, Kapuzen oder halten einfach den Kopf gesenkt. Sie können, ähnlich wie manche Vampire, menschliche Behausungen nicht ohne Erlaubnis betreten, und versuchen deshalb, die Bewohner zu überreden, sie hereinzulassen, um das Telefon zu benutzen, und behaupten, verlorene Kinder zu sein.","Schwarzäugige Kinder stammen aus einer Dimension der Schatten und hungern nach Lebensessenz. Sie können diese Welt nur nachts betreten und verschwinden im Morgengrauen, um nach dem nächsten Sonnenuntergang zurückzukehren."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W6, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6, Überreden W6","b":"6","pa":"6","ro":"5","sf":[["Biss/Klauen","Stä+W6. Schwarzäugige Kinder haben scharfe Zähne und einziehbare, rasiermesserscharfe Klauen."],["Verschlingen","Wird lebende Beute erschlagen, versucht das ganze Rudel, den Körper in den nächsten Schattenfleck zu zerren. Dort angekommen, verblassen sie zu Beginn ihres nächsten Zugs im Schattenreich, und die Leiche samt Seele wird für immer verzehrt. Die Kinder kehren nach dem Fressen mindestens einen Monat lang nicht zurück."],["Augen des Grauens","Als begrenzte Aktion kann ein schwarzäugiges Kind einem Opfer innerhalb von 6“ (12 m) in die Augen starren. Das Ziel muss eine Willenskraftprobe mit –2 ablegen oder ist für den Rest der Begegnung Verwundbar!"],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Schattengestalt","Schwarzäugige Kinder können als begrenzte freie Aktion eine schattenhafte Gestalt annehmen und scheinbar aus dem Nichts erscheinen."],["Größe -1","Schwarzäugige Kinder haben die Größe normaler Kinder, 90–150 cm, und wiegen bis zu 54 kg."],["Schwäche (Morgendämmerung)","Ein schwarzäugiges Kind kehrt beim ersten Morgenstrahl automatisch in seine schattige Heimatdimension zurück."],["Schwäche (nur auf Einladung)","Schwarzäugige Kinder können eine private Behausung nicht betreten, ohne eingeladen zu werden. Öffentliche Bereiche dürfen sie nach Belieben betreten."]]},{"n":"Schwarze Kutsche","k":"Fahrzeuge","w":0,"s":["HOR"],"p":108,"bk":"sw_hor","d":["Die Schwarze Kutsche ist ein Gefängnis für Seelen, die auf ihre Auslieferung an das Schicksal warten, das sie erwartet. Schwarze Vorhänge bedecken die Fenster, doch gelegentlich ist das geisterhafte Gesicht eines Opfers des Kutschers zu sehen, das verzweifelt nach Hilfe späht."],"a":[],"f":"","b":"—","pa":"—","ro":"14 (2) / 18 (4)","x":[["Antike Kutsche","Größe 4 (Groß), Handhabung +1, Höchstgeschwindigkeit 24 km/h, Robustheit 14 (2), Besatzung 1+Spezial. Hinweise: Eine Pferdekutsche; Bewegungsweite auf dem Spieltisch 12; Schwere Panzerung dank ihres höllischen Ursprungs; siehe die Spezialfähigkeiten Furcht und Unverwundbar unten."],["Moderne Kutsche","Größe 4 (Groß), Handhabung +1, Höchstgeschwindigkeit 160 km/h, Robustheit 18 (4), Besatzung 1+Spezial. Hinweise: Ein motorisierter Leichenwagen; Schwere Panzerung dank ihres höllischen Ursprungs; siehe die Spezialfähigkeiten Furcht und Unverwundbar unten."]],"sf":[["Furcht (-2)","Wer die Kutschentür öffnet, sieht eine wogende Masse schreiender, gequälter Geister. Er muss eine Furchtprobe mit –2 ablegen."],["Unverwundbar","Wird die Kutsche zerstört, besteigt der Kutscher ein Pferd oder kämpft zu Fuß weiter. Sie kehrt in der folgenden Nacht zusammen mit dem Kutscher zurück, bis er in die Hölle zurückkehrt."]]},{"n":"Der Schwarze Richter","k":"Geister","w":1,"s":["HOR"],"p":109,"bk":"sw_hor","d":["Für diejenigen, die die uralten Rituale zu seiner Beschwörung kennen, kann der Schwarze Richter ein Verbündeter im Kampf gegen das Böse sein. Er erscheint, wenn er durch ein Ritual beschworen wird (verwende die Macht Dämon beschwören mit Kosten von 10 Machtpunkten und einer Dauer von einer Stunde).","Das Wesen nimmt die Gestalt einer verhüllten Figur in Roben aus tiefster Nacht an. Über dem Gesicht trägt er eine vage totenkopfähnliche schwarze Maske mit brennenden gelben Augen und Fangzähnen. Was unter der Maske liegt, wurde nie enthüllt.","Einmal beschworen, greift der Richter den Beschwörer an und ist nur für diese Person verwundbar. Die Entscheidung, ob der Richter beschworen werden soll, sollte sehr schwer fallen.","Wird der Richter besiegt, fällt er auf ein Knie und erwartet seine Frage. Der Beschwörer darf ihn fragen, wie man eine bestimmte übernatürliche Kreatur besiegt – gut oder böse.","Wird der Beschwörer besiegt und überlebt, fällt der Richter sein Urteil – siehe unten."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W10"],["Willenskraft","W12"]],"f":"Athletik W12, Einschüchtern W10, Heimlichkeit W8, Kämpfen W12, Provozieren W10, Wahrnehmung W8, Überreden W10","b":"6","pa":"9","ro":"6","x":[["Talente","Block, Erstschlag"],["Ausrüstung","Langschwert (Stä+W8)"]],"sf":[["Dunkle Einsicht","Besiegt der Beschwörer den Richter im Einzelkampf, darf er ihn fragen, wie man eine einzelne übernatürliche Kreatur besiegt. Der Richter gibt keine weiteren Auskünfte – sein einziger kosmischer Zweck ist es, solche Geheimnisse zu enthüllen. Manche glauben, dies sei eine Art „Sicherheitsnetz“ für Wissen, das sonst verloren ginge, damit keine Kreatur wirklich unbesiegbar ist."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Unverwundbarkeit","Der Richter ist für alle außer der Person, die ihn beschworen hat, unverwundbar."],["Urteil","Wird der Beschwörer vom Schwarzen Richter Ausgeschaltet und überlebt, erhält er das Handicap Dem Tod geweiht."],["Schwäche (Beschwörer)","Der Richter ist nur für den verwundbar, der ihn beschworen hat."]]},{"n":"Schwarzer Baum","k":"Monster","w":0,"s":["HOR"],"p":109,"bk":"sw_hor","d":["Schwarze Bäume sind bösartige Kreaturen, die in Gruppen in uralten, dunklen Wäldern zu finden sind.","Manche entstehen durch die Schändung alter Begräbnisstätten, manche sind von Geistern oder Dämonen besessen, andere entstehen dort, wo Chemikalienmüll das Land verdorben hat.","Sie ähneln gewöhnlichen Bäumen, doch ihre Rinde ist schwarz, und aus Spalten in der Rinde sickert klebriger roter Saft. Die meisten haben groteske „Gesichtszüge“, geformt aus Knoten und Verdrehungen im Holz."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12"],["Stärke","W12+4"],["Verstand","W4 (A)"],["Willenskraft","W10"]],"f":"Athletik W8, Einschüchtern W10, Kämpfen W8, Wahrnehmung W8","b":"2","pa":"6","ro":"19 (3)","sf":[["Panzerung +3","Dicke Rinde."],["Blutentzug","Gepackte Gegner müssen beim Packen und zu Beginn des Zugs des Baumes eine Konstitutionsprobe ablegen, solange sie Gebunden oder Festgehalten bleiben. Ein Fehlschlag führt zu Erschöpfung, die zum Tod führen kann."],["Äste","Stä+W6, Reichweite 3. Ein schwarzer Baum hat zahlreiche Äste (wie Tentakel behandeln, siehe Savage Worlds) mit vier Aktionen."],["Verstricken","Die kleineren Äste und Wurzeln des Baumes versuchen, seine Angreifer zu Fall zu bringen und festzuhalten. Jeder, der sich innerhalb einer Großen Flächenschablone bewegt, die auf dem Baum zentriert ist (oder seinen Zug innerhalb dieses Radius beginnt), muss eine Ausweichen-Probe bestehen oder wird Festgehalten. Ein Festgehaltenes Ziel, das die Probe nicht schafft, wird Gebunden."],["Furcht","Jeder, der sieht, wie sich die Kreatur zu bewegen beginnt, muss eine Furchtprobe ablegen."],["Aufspießen","Eine Steigerung auf den Kämpfen-Wurf des Wesens spießt seinen Gegner auf einem spitzen Ast auf und hält ihn Fest, als wäre er gepackt."],["Resistenz (Stichwaffen)","Ein schwarzer Baum erleidet halben Schaden durch Stichangriffe, einschließlich Schüssen."],["Größe 8 (Riesig)","Schwarze Bäume werden bis zu 15 m hoch. Die Kreatur hat aufgrund ihres massigen Körpers zwei zusätzliche Wunden."],["Klebriger Saft","Ein Angreifer, der einen schwarzen Baum mit einer Nahkampfwaffe trifft, stellt fest, dass seine Waffe im Saft klebt. Bei seiner nächsten Aktion muss er eine Stärkeprobe mit –2 ablegen, um sie zu befreien. Bei Erfolg befreit er die Waffe, braucht dafür aber die ganze Runde. Mit einer Steigerung befreit er die Waffe und kann in dieser Runde noch andere Aktionen ausführen. Ein Charakter, der den Baum berührt, wird stattdessen Gebunden."],["Schwäche (Feuer)","Ein schwarzer Baum erleidet +4 Schaden durch Feuerangriffe."]]},{"n":"Blob","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":110,"bk":"sw_hor","d":["Ein Blob ist eine amorphe Masse aus säurehaltigem Gelee mit unstillbarem Hunger. Er könnte ein außerirdisches Wesen sein, das auf einem abgestürzten Satelliten zur Erde kam, eine Kreatur aus einer anderen Dimension oder das Ergebnis ungezügelter Umweltverschmutzung."],"a":[["Geschicklichkeit","W4"],["Konstitution","W12"],["Stärke","W12+2"],["Verstand","W4 (A)"],["Willenskraft","W12"]],"f":"Athletik W4, Heimlichkeit W6, Kämpfen W4, Wahrnehmung W8","b":"4","pa":"4","ro":"10","sf":[["Blob","+2 auf Erholung von Erschüttert; keine Wundabzüge; immun gegen Gift und Krankheit."],["Verschlingen","Nachdem ein Blob seine Bewegung beendet hat, darf jede Kreatur unter seiner Masse, die nicht Festgehalten oder Gebunden ist, Ausweichen. Wer scheitert, wird Festgehalten, bei einem Kritischen Fehlschlag Gebunden. Gebundene oder Festgehaltene Ziele erleiden beim Zerquetschen Stä+W6 Schaden, der nur durch versiegelte Rüstung gemindert wird. Verschlungene Ziele können versuchen zu entkommen, als würde der Blob sie packen. Tote Opfer werden absorbiert und vergrößern die Masse des Blobs (siehe Variable Größe unten)."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Unverwundbarkeit","Ein Blob ist immun gegen nichtmagische Waffen (außer Feuer, siehe unten)."],["Willenlos","Immun gegen Furcht und Einschüchtern."],["Klebriger Körper","Ein Angreifer, der einen Blob mit einer Nahkampfwaffe trifft, stellt fest, dass seine Waffe daran klebt. Bei seiner nächsten Aktion muss er eine Stärkeprobe mit –2 ablegen, um sie zu befreien. Bei Erfolg befreit er die Waffe, braucht dafür aber die ganze Runde. Mit einer Steigerung befreit er die Waffe und kann in dieser Runde noch andere Aktionen ausführen. Ein Charakter, der den Blob berührt, wird stattdessen Gebunden."],["Variable Größe","Ein neuer Blob beginnt als Kleine Flächenschablone (Größe 2). Für jedes absorbierte Opfer wächst er um 1“ (2 m) im Durchmesser und erhält +1 Größe (und Robustheit). Er erhält zusätzliche Wunden und weitere Vorteile, wenn er Groß, Riesig und Gigantisch wird."],["Schwäche (Feuer)","Ein Blob erleidet +4 Schaden durch Feuerangriffe. Die Schwäche der Kreatur kann je nach Herkunft variieren – Licht, Salz und selbst Wasser kommen als Mittel gegen sie infrage."]]},{"n":"Blutnebel","k":"Geister","w":0,"s":["HOR"],"p":110,"bk":"sw_hor","d":["Die Zerstörung des physischen Körpers eines uralten Vampirs bedeutet nicht unbedingt das Ende seiner Existenz. Durch dunkle Magie kann er von jenen, die die richtigen Rituale kennen, als beinahe hirnlose, ätherische Dampfwolke mit unstillbarer Blutgier ins Dasein zurückgeholt werden.","Blutnebel erscheinen als graue Wolken, bis sie fressen, und färben sich dann von Rosa bis Dunkelrot, je mehr Blut sie aufnehmen. Ihre bevorzugte Taktik ist es, sich unter natürlichen Nebel zu mischen, um ahnungslose Opfer mühelos zu erreichen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W6"],["Verstand","W6 (A)"],["Willenskraft","W10"]],"f":"Heimlichkeit W10, Kämpfen W6, Wahrnehmung W12","b":"6","pa":"7","ro":"7","sf":[["Unverwundbarkeit","Blutnebel erleiden keinen Schaden durch gewöhnliche Angriffe. Magische Waffen und übernatürliche Mächte wirken normal auf sie. Sie lassen sich zeitweise vertreiben, etwa indem man sie in einen Lüftungsschacht saugt, mit intensiver Hitze oder mit einem starken Wasserstrahl. Solche Mittel zerstreuen den Nebel meist für 1W10 Minuten."],["Lebensentzug","Jeder, der sich zu Beginn des Zugs der Kreatur (oder etwa jede Minute außerhalb des Kampfes) im Nebel befindet, muss eine Konstitutionsprobe ablegen oder erleidet eine Stufe Erschöpfung, die zum Tod führen kann. Ein Ziel in einem vollständig versiegelten Anzug ist immun."],["Schwarm","+2 auf Erholung von Erschüttert; Parade +2; Blutnebel bedecken die Fläche einer Großen Flächenschablone; normale Angriffe, selbst Flächenangriffe, verursachen überhaupt keinen Schaden (siehe Immunität)."],["Variable Größe","Ein Blutnebel beginnt als Große Flächenschablone. Eine Wunde verkleinert ihn auf eine Mittlere Flächenschablone, zwei auf eine Kleine, und drei zerstören ihn. Je drei Stufen Erschöpfung, die er entzieht, lassen ihn seine Größe wieder auffüllen, bis maximal zur Großen Flächenschablone."]]},{"n":"Fleischfressende Pflanze","k":"Monster","w":0,"s":["HOR"],"p":111,"bk":"sw_hor","d":["Pflanzen, die sich zum Fleischverzehr entwickelt haben, rufen instinktive Furcht hervor. Sie können überall lauern, als tödliches Gras, unheilvolle Seerosenblätter oder harmlose Ranken. Furchtbar macht sie der langwierige und schmerzhafte Tod, der ihre Opfer erwartet, wenn sie gelähmt und bei lebendigem Leib langsam verdaut werden."],"a":[["Geschicklichkeit","W4"],["Konstitution","W12"],["Stärke","W10"],["Verstand","W4 (A)"],["Willenskraft","W10"]],"f":"Athletik W8, Heimlichkeit W8, Wahrnehmung W6","b":"—","pa":"2","ro":"13 (2)","sf":[["Panzerung +2","Dicke, faserige Hülsen."],["Furcht","Jeder, der den Angriff einer fleischfressenden Pflanze sieht, muss eine Furchtprobe ablegen."],["Willenlos","Immun gegen Furcht und Einschüchtern."],["Lähmung","Wer von einer fleischfressenden Pflanze Erschüttert oder verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er gelähmt und für 2W6 Runden zu keiner Aktion fähig – auch nicht zum Sprechen."],["Widerstandsfähig","Kann eine zusätzliche Wunde einstecken."],["Größe 3","Fleischfressende Pflanzen, die groß genug sind, um Menschen zu bedrohen, breiten sich typischerweise über drei Meter aus."],["Falle","Die Pflanze greift an, indem sie versucht, Beute in Reichweite zu packen, am liebsten mit Überraschungsvorteil. Gebundene oder Festgehaltene Ziele erleiden beim Zerquetschen Stä+W6 Schaden, der nur durch versiegelte Rüstung gemindert wird."],["#","Variante Spezialfähigkeiten"],["Wasserwesen","Bewegungsweite 0. Die Pflanze kann mit Flüssen oder der Strömung treiben, und jeder, den sie fängt, riskiert zu ertrinken."],["Köder","Die Pflanze hat eine Kapsel entwickelt, die einem Baby ähnelt und Laute wie ein kleines Kind in Not erzeugen kann. Neugierige Ermittler haben eine Chance auf eine Wahrnehmung-Probe mit –2, um die Täuschung zu durchschauen; andernfalls sind sie, sobald sie nahe genug sind, um den wahren Charakter des Köders zu erkennen, nahe genug für einen Angriff der Pflanze."],["Giftspucke","Die Pflanze kann ihr Gift bis zu 6“ (12 m) weit spucken und würfelt dafür Athletik. Charaktere in einem versiegelten Umweltanzug sind immun, alle anderen müssen Konstitution würfeln oder erleiden die Lähmung der Kreatur (siehe oben). Spucker haben meist Bewegungsweite 1, damit sie vorwärtskriechen können, um ihre Opfer zu verzehren, während diese erstarrt sind."],["Klebriger Körper","Ein Angreifer, der die Pflanze mit einer Nahkampfwaffe trifft, stellt fest, dass seine Waffe daran klebt. Bei seiner nächsten Aktion muss er eine Stärkeprobe mit –2 ablegen, um sie zu befreien. Bei Erfolg befreit er die Waffe, braucht dafür aber die ganze Runde. Mit einer Steigerung befreit er die Waffe und kann in dieser Runde noch andere Aktionen ausführen. Ein Charakter, der die Pflanze berührt, wird stattdessen Gebunden."]]},{"n":"Katze, klein","k":"Tiere","w":0,"s":["HOR"],"p":112,"bk":"sw_hor","d":["Dies ist eine gewöhnliche Hauskatze, wie sie der Vertraute eines Zaubernden, der Tierfreund eines Tiermeisters oder eine alternative Gestalt für die Macht Gestaltwandel sein könnte."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W4−3"],["Verstand","W6 (A)"],["Willenskraft","W10"]],"f":"Athletik W8, Heimlichkeit W8, Wahrnehmung W6","b":"6","pa":"2","ro":"2","x":[["Talente","Akrobat"]],"sf":[["Biss/Klauen","Stä."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Größe -3 (Sehr klein)","Katzen sind meist weniger als 30 cm hoch."]]},{"n":"Auserwählter Jäger","k":"Humanoide","w":1,"s":["HOR"],"p":112,"bk":"sw_hor","g":"Auserwählte Jäger","d":["Dieser Werteblock gilt für einen Monsterjäger am Beginn ihrer Laufbahn."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W8, Einschüchtern W6, Heimlichkeit W6, Kämpfen W8, Provozieren W4, Schießen W6, Wahrnehmung W8, Überreden W6","b":"6","pa":"6","ro":"6","x":[["Handicaps","Heldenhaft, Loyal"],["Talente","Akrobat, Arkane Resistenz, Champion, Gefahrensinn, Schnell"],["Ausrüstung","Schwert (Stä+W8), angespitzter Pflock (Stä+W4), Armbrust mit hölzernen Bolzen"]],"sf":[]},{"n":"Auserwählter Jäger, erfahren","k":"Humanoide","w":1,"s":["HOR"],"p":112,"bk":"sw_hor","g":"Auserwählte Jäger","d":["Jäger, die ihre ersten Jahre überleben, haben gelernt, sich im Kampf gegen verschiedenste übernatürliche Feinde zu behaupten."],"a":[["Geschicklichkeit","W12"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W8, Heimlichkeit W8, Kämpfen W12, Provozieren W6, Schießen W10, Wahrnehmung W8, Überreden W8","b":"6","pa":"9","ro":"7","x":[["Handicaps","Heldenhaft, Loyal"],["Talente","Akrobat, Arkane Resistenz, Block, Champion, Kampfreflexe, Anführer, Gefahrensinn, Ausweichen, Schwer zu töten, Kühler Kopf, Schnell"],["Ausrüstung","Schwert (Stä+W8), angespitzter Pflock (Stä+W4), Armbrust mit hölzernen Bolzen"]],"sf":[]},{"n":"Chupacabra","k":"Monster","w":0,"s":["HOR"],"p":112,"bk":"sw_hor","d":["Chupacabras sind große, haarlose Hundewesen mit langen Beinen und einem ausgeprägten Kamm aus Räude oder Stacheln auf dem Rücken. Sie fressen, indem sie ihre Beute mit den Kiefern packen, dann mit einer scharfen, hohlen Zunge die Haut des Ziels durchbohren und das Blut aussaugen. Nach dem Fressen reißen sie den Körper meist auseinander, was es schwierig macht, die Einstichwunde zu finden und den Angriff als das Werk eines Chupacabras zu erkennen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6","b":"8","pa":"6","ro":"6","x":[["Talente","Flink, Raserei"]],"sf":[["Biss/Klauen","Stä+W6."],["Blutentzug","Gepackte Gegner müssen beim Packen und zu Beginn des Zugs der Kreatur eine Konstitutionsprobe ablegen, solange sie Gebunden oder Festgehalten bleiben. Ein Fehlschlag führt zu Erschöpfung, die zum Tod führen kann. Festgehaltene Opfer mit einem Messer oder einem Verbündeten können versuchen, die Zunge zu durchtrennen (Robustheit 3)."],["Stacheln","Jeder, der einen Chupacabra packt oder von ihm gepackt wird, erleidet pro Runde 2W4 Schaden durch seine Stacheln."]]},{"n":"Leichenwurmschwarm","k":"Tiere","w":0,"s":["HOR"],"p":112,"bk":"sw_hor","d":["Leichenwürmer sind zweieinhalb Zentimeter lange rote Würmer mit einer Vorliebe für Fleisch und einem lähmenden Biss. Obwohl sie meist Kadaver fressen, bevorzugen sie warmes, lebendes Gewebe. Ein einzelner Wurm stellt für einen gesunden Menschen kaum eine Gefahr dar, ein Schwarm kann einen Mann jedoch sehr schnell verteidigungsunfähig machen."],"a":[["Geschicklichkeit","W4"],["Konstitution","W6"],["Stärke","W4−3"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Heimlichkeit W10, Kämpfen W4, Wahrnehmung W12","b":"1","pa":"6","ro":"5","sf":[["Von innen verschlingen","Wer von einem Leichenwurmschwarm gelähmt wird, wird langsam von innen verzehrt und erleidet pro Stunde eine Wunde, die nur durch Magie oder das Schlucken eines vollen Pfundes Salz gestoppt werden kann. Das trocknet die Würmer wie Schnecken aus, und sie sterben im Körper."],["Lähmung","Leichenwurmschwärme verursachen keinen Schaden, doch lebende Opfer, die nicht in versiegelten Anzügen mit mindestens 1 Panzerung stecken, müssen jede Runde im Schwarm eine Konstitutionsprobe ablegen oder sind für 2W6 Runden gelähmt, oder solange sie beim Schwarm bleiben."],["Schwarm","+2 auf Erholung von Erschüttert; Parade +2; Leichenwurmschwärme bedecken die Fläche einer Mittleren Flächenschablone; Hieb- und Stichangriffe verursachen keinen Schaden, Flächenwaffen wirken normal; verkleinere die Schablone nach einer Wunde auf eine Kleine Flächenschablone. Kleine Schwärme sind zerstört."]]},{"n":"Kriechende Hand","k":"Untote","w":0,"s":["HOR"],"p":113,"bk":"sw_hor","d":["Kriechende Hände sind abgetrennte Hände, die durch einen arkanen Vorgang belebt wurden. Drei verschiedene Arten sind verzeichnet, alle mit denselben Werten.","Die erste Art sind die Hände von Mördern. Hier belebt sich die Hand nach dem Tod irgendwie wieder und beginnt einen Mordzug.","Die zweite Art gehört Zauberern, die gelernt haben, ihre Hände abzutrennen und auf Botengänge zu schicken. Nicht alle davon sind zwangsläufig böse.","Die dritte Art sind rachsüchtige Kreaturen, meist von Unfallopfern, die Vergeltung suchen."],"a":[["Geschicklichkeit","W10"],["Konstitution","W8"],["Stärke","W12+2"],["Verstand","W6 (A)"],["Willenskraft","W10"]],"f":"Athletik W10, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W4","b":"4","pa":"7","ro":"3","sf":[["Ersticken","Erzielt eine Kriechende Hand bei einem Kämpfen-Angriff gegen ein Ziel der Größe 0 oder kleiner eine Steigerung, darf sie sofort als freie Aktion einen Ringkampfversuch (mit +2) unternehmen."],["Huschen","Kriechende Hände haben einen Sprintwürfel W4."],["Größe -3 (Sehr klein)","Kriechende Hände sind von den Fingerspitzen bis zum Handgelenk weniger als 30 cm lang."]]},{"n":"Typischer Kultist","k":"Humanoide","w":0,"s":["HOR"],"p":113,"bk":"sw_hor","g":"Kultisten","d":[],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4"],["Willenskraft","W6"]],"f":"Allgemeinwissen W4, Athletik W4, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6, Überreden W6","b":"6","pa":"5","ro":"5","x":[["Handicaps","Loyal (dem Kult)"],["Talente","Mutig"],["Ausrüstung","Zeremonienroben, Dolch (Stä+W4)"]],"sf":[]},{"n":"Kultführer","k":"Humanoide","w":1,"s":["HOR"],"p":113,"bk":"sw_hor","g":"Kultisten","d":["An der Spitze jedes Kults steht ein Hohepriester, Großmagier oder anderer Irrer. Die meisten haben übernatürliche Kräfte, die ihnen ihre dunklen Götter verliehen haben und die sich als unheilige Wunder oder schwarze Magie äußern. Passe die Ausprägungen ihrer Zauber an das Wesen der Wesen an, die sie anbeten."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W6, Heimlichkeit W6, Kriegskunst W6, Kämpfen W8, Wahrnehmung W8, Zaubern W10, Überreden W8","b":"6","pa":"6","ro":"6","x":[["Handicaps","Arrogant"],["Talente","Arkaner Hintergrund (Magie), Anführer, Inspirieren"],["Mächte","Geschoss (schreiender Schädel), Dunkelheit (Dunkelheitswolke), Furcht (unirdisches Kreischen), Marionette (hypnotische Stimme), Zuschlagen (Unheilsfeuer entlang der Klinge), Zombie (spezielles Pulver) (Machtpunkte: 15)"],["Ausrüstung","Zeremonienroben, verfluchter Dolch (Stä+W6+2 Schaden; Wunden können nur auf natürliche Weise heilen)"]],"sf":[]},{"n":"Totentanz","k":"Untote","w":1,"s":["HOR"],"p":114,"bk":"sw_hor","d":["Ein Totentanz ist zugleich ein einzelnes Wesen und ein Ereignis. Die Kreatur selbst, oft Tanzmeister genannt, um sie vom Ereignis zu unterscheiden, das sie anführt, ist eine skelettierte Gestalt in bunten Roben. Obwohl sie nicht atmen kann, spielt sie auf einer Flöte aus den Knochen der Verdammten. Die Melodie ist nicht nur bannend unheimlich, sondern für Sterbliche tödlich.","Dem Tanzmeister folgen etliche Skelette, frühere Opfer, die ihren Meister vor Angriffen verteidigen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W8"],["Willenskraft","W12"]],"f":"Athletik W8, Darbietung W12, Einschüchtern W8, Wahrnehmung W6, Überreden W8","b":"8","pa":"2","ro":"8","sf":[["Totentanz","Jede Runde, in der der Tanzmeister auf seiner Flöte spielt, würfelt er eine vergleichende Probe seiner Darbietung gegen die Willenskraft jeder Kreatur in Hörweite (20 m). Wer ihn nicht übertrifft, wird Mitglied der Tanztruppe und beginnt, zur Melodie zu tanzen. Opfer dürfen jede Stunde eine Willenskraftprobe mit –2 ablegen, um sich zu befreien. Jede Stunde im Tanz erleiden sie eine Wunde, während ihr Fleisch verrottet. Wer so Ausgeschaltet wird, stirbt und wird zu einem Skelett, das für immer im Totentanz gefangen ist."],["Furcht (-2)","Jeder, der den Totentanz sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Der Tanzmeister ist immun gegen Furcht und Einschüchtern."],["Skeletttänzer","Den Tanzmeister umgeben 4W6 Skelette (siehe Savage Worlds)."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Arachnos, der vielbeinige Spinnengott","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":114,"bk":"sw_hor","g":"Dunkle Götter","d":["Viele Menschen fürchten Spinnen. Wüssten sie um deren wahren Ursprung, würden alle sie fürchten. Arachnos, die Mutter der Spinnen, nimmt die Gestalt einer monströsen Tarantel an. Über ihren Rücken krabbeln Tausende kleinerer Spinnen – ihre Brut."],"a":[["Geschicklichkeit","W10"],["Konstitution","W12+2"],["Stärke","W12+7"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W10, Heimlichkeit W8, Kämpfen W8, Schießen W10, Wahrnehmung W8","b":"6","pa":"6","ro":"22 (3)","x":[["Talente","Arkane Resistenz (Verb.)"]],"sf":[["Panzerung +3","Chitinpanzer. Schwere Panzerung."],["Biss","Stä+W6."],["Furcht (-6)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –6 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Gift (-4)","Wer durch den Biss von Arachnos Erschüttert oder verwundet wird, muss eine Konstitutionsprobe mit –4 ablegen oder stirbt."],["Regeneration (Schnell)","Wurf auf Natürliche Heilung jede Runde, außer bei Wunden durch Feuer, Magie oder ihr eigenes Gift."],["Größe 10 (Riesig)","Über 18 m Durchmesser."],["Spinnenschwarm","Arachnos kann pro Runde einen Schwarm (siehe Savage Worlds) freisetzen, bis zu 10 pro Tag."],["Unaufhaltsam","Ein dunkler Gott kann durch einen einzelnen Angriff nie mehr als eine Wunde erleiden (nachdem Wegstecken-Würfe gemacht wurden)."],["Wandkrabbler","Kann mit voller Bewegungsweite an senkrechten oder überhängenden Flächen laufen (oder rennen)."],["Netze","Arachnos kann mit Athletik ein Netz in einer Kegelschablone oder Mittleren Flächenschablone schleudern (Reichweite 24“ bzw. 48 m). Ziele müssen Ausweichen oder werden Festgehalten (Gebunden, wenn Arachnos mit einer Steigerung trifft). Die Netze haben Härte 10, wenn man sie durchschneiden will."]]},{"n":"Crazalphasalius, der Feuersturm","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":115,"bk":"sw_hor","g":"Dunkle Götter","d":["Crazalphasalius trägt seinen Titel zu Recht. Seine Gestalt ist ein riesiger Feuerball ohne feste Ausmaße. Er schwillt nach seiner eigenen Flut an und ab und verschlingt alles, was er berührt, in sengenden Flammen. Nur wenige Materialien halten seinem feurigen Zorn lange stand. Zu seinen weiteren Titeln zählen die Lebende Flamme, das Heulende Inferno, die Läuternde Flamme und der Brennende Mahlstrom."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12+8"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Athletik W8, Einschüchtern W12, Heimlichkeit W4, Kämpfen W6, Schießen W10","b":"10","pa":"5","ro":"22","x":[["Talente","Arkane Resistenz (Verb.)"]],"sf":[["Verschlingen","Crazalphasalius füllt eine Fläche von 12“ (24 m) Durchmesser. Nachdem er sich bewegt hat, erleiden alle in seiner Schablone 2W10 Schaden."],["Furcht (-6)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –4 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Feuerball","Crazalphasalius kann mit Schießen pro Runde einen Feuerball mit FR 3 auf ein beliebiges Ziel innerhalb von 24“ (48 m) schleudern. Jeder Schuss kann ausgewichen werden, verursacht 2W10 Schaden in einer Großen Flächenschablone und ist eine Schwere Waffe."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Regeneration (Schnell)","Wurf auf Natürliche Heilung jede Runde, außer bei Wunden durch Wasser, Eis oder Magie."],["Größe 10 (Riesig)","Crazalphasalius hat 12 m Durchmesser."],["Unaufhaltsam","Ein dunkler Gott kann durch einen einzelnen Angriff nie mehr als eine Wunde erleiden (nachdem Wegstecken-Würfe gemacht wurden)."],["Schwäche (Wasser)","Crazalphasalius kann nur durch Wasser- oder Eisangriffe verletzt werden. Schon ein Eimer Wasser verursacht 1W6 Schaden, etwas wie ein Feuerwehrschlauch 3W6."]]},{"n":"Jjrikillimsg, der Heuler der Wahrheit","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":115,"bk":"sw_hor","g":"Dunkle Götter","d":["Jjrikillimsg ist wahnsinnig – vollkommen und gänzlich wahnsinnig auf eine Weise, die kein Sterblicher je verstehen oder nachahmen kann. Zu seinen Titeln zählen Beinamen wie der Irre, Der ohne wahre Form, der Enthüller der Geheimnisse und der Erleuchter verschlossener Geister.","Falls Jjrikillimsg eine wahre Gestalt hat, hat sie nie jemand aufgezeichnet. Er huscht zwischen vielen Formen hin und her und wechselt so schnell, dass das menschliche Auge nicht folgen kann. Hin und wieder verharrt er jedoch gerade lange genug in einer Form, dass das Gehirn das Gesehene analysieren kann. Wahnsinn folgt meist kurz darauf."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12+4"],["Stärke","W12+8"],["Verstand","W4 (A)"],["Willenskraft","W12"]],"f":"Athletik W8, Einschüchtern W12, Heimlichkeit W4, Kämpfen W8, Wahrnehmung W6","b":"8","pa":"6","ro":"18","x":[["Talente","Arkane Resistenz (Verb.)"]],"sf":[["Furcht (-6)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –6 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Heulen","Einmal pro Runde stößt Jjrikillimsg als freie Aktion ein unirdisches, heulendes Gebrabbel aus. Jedes lebende Wesen, das es hören kann und innerhalb von 10“ (20 m) ist, muss eine Willenskraftprobe ablegen. Bei einem Fehlschlag verliert das Opfer den Verstand und senkt seinen Verstand dauerhaft um eine Stufe. Fällt Verstand unter W4, erleidet das Opfer einen Psychotischen Zusammenbruch (siehe Tabelle Furchteffekte auf S. 43)."],["Wahnsinnig","Ein Charakter, der den Geist von Jjrikillimsg durch arkane Mächte wie Marionette beeinflussen will, scheitert automatisch und senkt dauerhaft den Verstand des Zaubernden um eine Stufe. Fällt Verstand unter W4, erleidet das Opfer einen Psychotischen Zusammenbruch (siehe Tabelle Furchteffekte auf S. 43)."],["Natürliche Waffen","Stä+W8. Der dunkle Gott hat stets irgendeine Waffe, seien es Klauen, Zähne, ein mehrfach bewehrter Schwanz oder eine Art Klinge."],["Regeneration (Schnell)","Wurf auf Natürliche Heilung jede Runde, außer bei Wunden durch Feuer oder Magie."],["Größe 8 (Riesig)","Die Gestalt von Jjrikillimsg variiert, ist aber im Schnitt etwa 9 m hoch und 3 m im Durchmesser (oder umgekehrt)."],["Unaufhaltsam","Ein dunkler Gott kann durch einen einzelnen Angriff nie mehr als eine Wunde erleiden (nachdem Wegstecken-Würfe gemacht wurden)."]]},{"n":"Todoto, der Mutator","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":116,"bk":"sw_hor","g":"Dunkle Götter","d":["Todoto erscheint als riesiger Hüne mit dunkelgrüner Haut. Seine Haut blubbert und windet sich, als kämpfe eine unheilige Kraft um Befreiung. Todoto ist ein Chaosgott, der Leben durch die Kraft seines Blutes verzerrt. Nichts ist vor seiner Verderbnis sicher, und einmal verdorben, können seine Opfer nie in ihre normale Gestalt zurückkehren.","Wie die meisten dunklen Götter hat Todoto viele Titel, darunter der Spender, Chaoszüchter, Dunkle Verzerrer und der Unheilige Former."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12+4"],["Stärke","W12+12"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Athletik W6, Heimlichkeit W4, Kämpfen W12, Wahrnehmung W8","b":"8","pa":"8","ro":"20","x":[["Talente","Arkane Resistenz (Verb.)"]],"sf":[["Blutfontäne","Jede Wunde, die Todoto zugefügt wird, lässt eine Blutfontäne in einer Kegelschablone entgegen der Richtung der Verletzung spritzen. Jeder Charakter unter der Schablone muss Ausweichen oder wird vom Blut getroffen (siehe unten)."],["Furcht (-6)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –6 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Mutierendes Blut","Jede Kreatur, die von Todotos Blut getroffen wird, muss eine Konstitutionsprobe mit –2 ablegen oder wird in einen Günstling des Todoto verwandelt (siehe unten). Der Vorgang dauert eine Runde, in der das Opfer nicht handeln kann. Bannen mit –2 stoppt den Vorgang, wenn es vor der Verwandlung gewirkt wird, ansonsten ist er unumkehrbar."],["Regeneration (Schnell)","Wurf auf Natürliche Heilung jede Runde, außer bei Wunden durch Feuer oder Magie."],["Größe 10 (Riesig)","Todoto ist ein 21 m großer Humanoider."],["Unaufhaltsam","Ein dunkler Gott kann durch einen einzelnen Angriff nie mehr als eine Wunde erleiden (nachdem Wegstecken-Würfe gemacht wurden)."]]},{"n":"Günstling des Todoto","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":116,"bk":"sw_hor","g":"Dunkle Götter","d":["Die unglücklichen Seelen, die mit Todotos Blut bespritzt werden, werden verdreht und verzerrt. Keine zwei Formen gleichen sich. Manche bekommen zusätzliche Gliedmaßen oder Tentakel, andere stülpen sich um und verwandeln sich in eine unheilige Mischung aus Mensch, Pflanze und Tier. Wieder andere werden zu verwesenden Klumpen gallertigen Schleims.","Günstlinge sind Todoto treu ergeben, auch wenn er keine besonderen Kräfte hat, ihr Handeln zu steuern."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W4"],["Willenskraft","W6"]],"f":"Athletik W6, Einschüchtern W8, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6","b":"6","pa":"5","ro":"6","sf":[["Furcht","Jeder, der einen Günstling sieht, muss eine Furchtprobe ablegen."],["Natürliche Waffen","Günstlinge haben vielfältige Angriffe, darunter Biss, Klauen, Tentakelhiebe und Schwänze. Alle verursachen Stä+W4 Schaden."]]},{"n":"Vralkresh der Tausend Mäuler","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":116,"bk":"sw_hor","g":"Dunkle Götter","d":["Vralkresh ist ein monströser Sack aus pulsierendem Gelee mit blutroten Segmenten, vermischt mit Eitergrün, fauligem Blau und allerlei anderen widerwärtigen Färbungen. Im Ruhezustand hat Vralkresh keine erkennbaren Züge. Einmal erwacht, sprießt aus seinem gallertartigen Leib jedoch ein Gewimmel schleimiger Tentakel, jeder mit einem greifenden Maul an der Spitze.","Vralkresh ist unter vielen anderen Namen bekannt, darunter Herr der Vielen Mäuler, Er, der ohne Ende frisst, und das Schlängelnde Maul."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12+4"],["Stärke","W12+10"],["Verstand","W6"],["Willenskraft","W12"]],"f":"Kämpfen W12, Wahrnehmung W8","b":"8","pa":"8","ro":"26 (4)","x":[["Talente","Arkane Resistenz (Verb.)"]],"sf":[["Panzerung +4","Gallertartiger Körper. Schwere Panzerung."],["Furcht (-6)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –6 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Regeneration (Schnell)","Wurf auf Natürliche Heilung jede Runde, außer bei Wunden durch Feuer oder Magie."],["Größe 12 (Gigantisch)","Vralkresh ist über 30 m breit."],["Tentakel (variabel)","Stä+W8, Reichweite 2, Schwere Waffe. Vralkresh hat vier Tentakelaktionen. Statt eine Wunde zu regenerieren, kann Vralkresh einen neuen Tentakel als Ersatz für einen abgetrennten sprießen lassen."],["Unaufhaltsam","Ein dunkler Gott kann durch einen einzelnen Angriff nie mehr als eine Wunde erleiden (nachdem Wegstecken-Würfe gemacht wurden)."]]},{"n":"Dunkler Mann","k":"Geister","w":1,"s":["HOR"],"p":117,"bk":"sw_hor","d":["Obwohl oft als „der“ Dunkle Mann bezeichnet, deutet manches darauf hin, dass diese Kreatur kein Einzelwesen ist. Er ist eine menschenähnliche Gestalt aus tintiger Finsternis ohne erkennbare Gesichtszüge. Er ist eine Quelle reiner nekromantischer Energie mit der Macht, Untote zu stärken. Daher wird ein Dunkler Mann nur beschworen, um eine Schar solcher Unholde anzuführen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Athletik W6, Einschüchtern W10, Fokus W10, Heimlichkeit W12+2, Kämpfen W6, Wahrnehmung W6","b":"6","pa":"5","ro":"9","x":[["Talente","Arkane Resistenz (Verb.)"]],"sf":[["Untote verstärken","Jeder Untote innerhalb von 10“ (20 m) erhält +2 auf Erholung von Erschüttert, auf Kämpfen-Angriffs- und Schadenswürfe und auf Robustheit."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Nekromantischer Schub","Als freie Aktion kann ein Dunkler Mann eine Fokus-Probe ablegen, um eine Welle nekromantischer Energie auszusenden. Bei Erfolg entfernt sie alle Zustände Abgelenkt und Verwundbar bei allen Untoten innerhalb von 12“ (24 m). Mit einer Steigerung entfernt sie auch Erschüttert- oder Betäubt-Zustände."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Todeswurm","k":"Tiere","w":0,"s":["HOR"],"p":117,"bk":"sw_hor","d":["Todeswürmer sind blutrot und sehen eher wie ein Stück frisches menschliches Gedärm aus als wie ein lebendes Wesen. Sie sind unglaublich giftig: bei Berührung toxisch und in der Lage, aus beiden Enden tödliches Gift zu spucken. Todeswürmer graben sich mühelos durch Wüstensand und das Fleisch von Aas."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Athletik W6, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6","b":"4","pa":"5","ro":"3","sf":[["Biss","Stä+W4."],["Blindsinn","Todeswürmer ignorieren Unsichtbarkeit, Illusionen und Abzüge für Beleuchtung."],["Graben (Bewegungsweite 4)","Kann sich durch alles außer massivem Stein graben; kann unter der Erde nur durch besondere Mittel angegriffen werden."],["Gift (Tödlich)","Wer durch den Biss des Wurms Erschüttert oder verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt, erleidet eine Wunde (zwei bei einem Kritischen Fehlschlag) und stirbt in 2W6 Runden."],["Giftspucke","Ein Todeswurm kann sein Gift spucken und würfelt Athletik, um ein Ziel innerhalb von 6“ (12 m) zu treffen. Charaktere in einem versiegelten Umweltanzug sind immun, alle anderen müssen Konstitution würfeln, als wären sie vom Gift der Kreatur berührt worden."],["Größe -3 (Sehr klein)","Todeswürmer sind etwa 60 cm lang und sehr dünn."]]},{"n":"Eintreiberdämon","k":"Dämonen","w":1,"s":["HOR"],"p":118,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Eintreiberdämonen werden ausgesandt, um die Seelen derer einzusammeln, die ihre Versprechen an die Hölle brechen. Das kann jemand sein, der seine Seele verkauft hat, ein Kultist, der einem dunklen Meister sein Leben geschworen hat, oder vielleicht sogar ein Narr, der eine Wette gegen eine dämonische Macht verloren hat."],"a":[["Geschicklichkeit","W10"],["Konstitution","W12"],["Stärke","W12"],["Verstand","W8"],["Willenskraft","W12"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W12, Heimlichkeit W12, Kämpfen W10, Wahrnehmung W8, Überleben W12+2","b":"8","pa":"7","ro":"9","x":[["Talente","Arkane Resistenz (Verb.), Starker Wille"]],"sf":[["Klauen","Stä+W6 6."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht (-2)","Jeder, der einen Stacheldämon sieht, muss eine Furchtprobe mit –2 ablegen."],["Größe 1","Diese verhüllten Dämonen sind über 2,10 m groß."],["Seelenentzug","Der entblößte Blick eines Eintreibers reißt Leben und Seele aus seinem Opfer. Um diese Fähigkeit einzusetzen, muss der Eintreiber seinen Gegner packen, woraufhin er seine Kapuze abnimmt und seine Beute zwingt, in seine dämonischen Augen zu starren. Das Opfer muss eine vergleichende Willenskraftprobe gegen das Einschüchtern des Dämons ablegen oder stirbt sofort. Die Seele des Opfers wird in die Hölle geschickt, wodurch Wiederbelebung unmöglich ist, ohne sie irgendwie zu befreien."],["Übernatürliche Sinne","Ein Eintreiber kann sein Ziel überall auf der Erde aufspüren und findet es mit unfehlbarer Treffsicherheit (auch wenn die Anreise dauern kann). Er ignoriert zudem alle Abzüge für schlechte Beleuchtung, einschließlich vollständiger Dunkelheit."]]},{"n":"Dämonischer Legionär","k":"Dämonen","w":0,"s":["HOR"],"p":118,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Die Legionen der Hölle bestehen aus diesen stummen Seelen. Sie sind unerbittliche Schrecken, von einem Wildcard-Anführer mit erhöhten Eigenschaften und einigen Kampf- oder Anführer-Talenten zum Handeln angetrieben."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W6, Kämpfen W8, Schießen W8, Wahrnehmung W6","b":"6","pa":"6 oder 8 (shield)","ro":"8 (2)","x":[["Handicaps","Fies"],["Talente","Mutig"],["Ausrüstung","Panzerrüstung (+2), stachelige Langschwerter (Stä+W8, +2 Schaden, wenn der Gegner höchstens 2 Punkte Panzerung hat), Mittlerer Schild. Manche sind mit stacheligen Leichten Armbrüsten ausgerüstet (Reichweite 10/20/40, Schaden 2W6, +2, wenn der Gegner weniger als 2 Punkte Panzerung hat, PB 2)"]],"sf":[["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."]]},{"n":"Dämonisches Streitross","k":"Dämonen","w":0,"s":["HOR"],"p":118,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Dämonische Streitrösser werden von Dämonen vor allem zur Fortbewegung in der Hölle genutzt, gelegentlich aber auch treuen Sterblichen geschenkt. Sie sind tiefschwarz mit roten Augen und dampfenden Nüstern. Ihre Gebisse und Zügel bestehen aus verdrehtem Stacheldraht, und ihre Hufeisen sind mit Nägeln aus den Rippen von Sündern festgeschlagen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W6 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Kämpfen W8, Wahrnehmung W6","b":"10","pa":"6","ro":"12 (3)","x":[["Talente","Flink"],["Ausrüstung","Manche Schurken geben ihren Nachtmähren Pferderüstung (+3)"]],"sf":[["Tritt","Stä+W6."],["Reiter-Empathie","Ist der Reiter eines dämonischen Streitrosses böse, ob sterblich oder übernatürlich, erhält er +2 auf seine Reiten-Würfe. Gute Charaktere ziehen 4 ab, und das Streitross versucht, sie in einem passenden und vielleicht unausweichlichen Moment zu töten."],["Größe 2","Dämonische Streitrösser wiegen zwischen 360 und 450 kg."]]},{"n":"Dämonenwurm","k":"Dämonen","w":1,"s":["HOR"],"p":119,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Aus den Tiefen der Hölle beschworen, ähneln Dämonenwürmer eher gewaltigen Nacktschnecken. Ihre gesprenkelte grüne Haut trieft vor übelriechendem Eiter und hinterlässt überall, wohin sie gehen, eine schleimige Spur. Sie haben riesige, runde Mäuler voller nadelartiger Zähne, umgeben von einem Gewirr sich windender Tentakel.","Manche Kultisten beten sie als Götter an, obwohl sie weit von Allmacht entfernt sind und ihren irregeleiteten Anhängern keinerlei Kräfte verleihen können."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+7"],["Verstand","W4 (A)"],["Willenskraft","W10"]],"f":"Athletik W6, Einschüchtern W10, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W10","b":"6","pa":"5","ro":"19 (4)","sf":[["Panzerung +4","Dicke Fettschichten."],["Biss","Stä+W8."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht (-4)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –4 ablegen."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Größe 8 (Riesig)","Dämonenwürmer sind über 9 m lang und haben 3 m Durchmesser."],["Niederwalzen","Dämonenwürmer können Beute unter ihren massigen Körpern zerquetschen. Lege drei Kleine Flächenschablonen nebeneinander in einer geraden Linie. Alles unter den Schablonen muss Ausweichen oder wird zerquetscht und erleidet die Stä des Wurms als Schaden. Ignoriere Größenmodifikatoren bei einem Zertrümmern-Angriff."],["Ganz verschlucken","Opfer, die von einem Dämonenwurm gebissen werden, müssen eine Ausweichen-Probe ablegen oder werden Ganz Verschluckt."],["Tentakel (4)","Dämonenwürmer haben vier Tentakelaktionen. Jede verursacht Stä+W4 Schaden, Reichweite 1."]]},{"n":"Gladiatordämon","k":"Dämonen","w":0,"s":["HOR"],"p":119,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Gladiatoren sind die Eliterkrieger der Hölle, die im Dienst – oder zur Belustigung – von Dämonenprinzen kämpfen. Sie sind turmhohe Ungetüme aus Muskeln, Metall und Hass.","Irgendwo in den Eingeweiden des Abgrunds, in einer grauenhaften Werkstatt kreischender Schmiede, wurden grob Metallplatten auf sein Fleisch genietet. Seine Arme enden unterhalb des Ellbogens in großen, gezackten Klingen, deren Spitzen über den Boden kratzen, wenn sich die Bestie bewegt. Selbst in Ruhe schäumt ein Gladiator vor dem Maul und hat einen irren Blick."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W12+3"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W12, Einschüchtern W8, Heimlichkeit W6, Kämpfen W12, Wahrnehmung W6","b":"7","pa":"10","ro":"14 (2)","x":[["Talente","Beidhändig, Berserker, Block (Verb.), Beidhändiger Kampf"]],"sf":[["Panzerung +2","Metallstücke."],["Berserker","Gladiatordämonen erleiden keine Erschöpfung durch Berserker und beenden ihren wütenden Amoklauf erst, wenn alle Feinde in Sichtweite tot sind."],["Klingen","Stä+W10, Reichweite 1."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht (-2)","Jeder, der einen Stacheldämon sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Größe 5 (Groß)","Gladiatoren sind über 4,5 m groß und haben eine zusätzliche Wunde."],["Sehr widerstandsfähig","Gladiatordämonen, die keine Wildcards sind, können zwei zusätzliche Wunden einstecken, bevor sie Ausgeschaltet werden."]]},{"n":"Völlereidämon","k":"Dämonen","w":1,"s":["HOR"],"p":120,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Völlereidämonen haben die Körper großer, aufgedunsener Kröten und die Gliedmaßen eines Schweins. Sie sind so fett, dass ihre Körper wie eine Masse zitternden Gelees von einer Seite zur anderen wabbeln.","Ihre Kiefer können sich weit genug öffnen, um ein menschengroßes Objekt in einem Happen zu verschlingen. Ihr Appetit ist endlos, und sie können in einem einzigen Kampf unbegrenzt viele Gegner verschlucken."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+4"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6","b":"5","pa":"6","ro":"12","sf":[["Biss","Stä+W6."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Fettleibig","Völlereidämonen würfeln einen Sprintwürfel W4 statt W6; Robustheit +1."],["Größe 4 (Groß)","Völlereidämonen sind so groß wie kleine Elefanten und haben eine zusätzliche Wunde."],["Ganz verschlucken","Wer von einem Bissangriff getroffen wird, muss eine Ausweichen-Probe ablegen oder wird Ganz Verschluckt."]]},{"n":"Höllenhund","k":"Dämonen","w":0,"s":["HOR"],"p":120,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Höllenhunde sind monströse Dämonenhunde mit schwarzer Haut, die vor Hitze ihres dämonischen Blutes dampft. Ihre Augen brennen vor Unheilsfeuer, und ihre Zähne ragen in schrecklichen Winkeln aus dem Kiefer. Bestimmte Dämonen halten Höllenhunde oft als Haustiere, sie finden sich aber auch in Gesellschaft von Nekromanten und anderen bösen Magiern."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W6 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W10, Überleben (tracking) W12+2","b":"8","pa":"6","ro":"7","x":[["Talente","Aufmerksamkeit, Flink"]],"sf":[["Biss","Stä+W6."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht","Jeder, der einen Höllenhund sieht, muss eine Furchtprobe ablegen."],["Immunität (Feuer)","Höllenhunde erleiden keinen Schaden durch Feuer."],["Schreckliche Wunden","Die gezackten Zähne eines Höllenhundes verursachen schreckliche Wunden, die nicht schnell heilen. Heilungswürfe, einschließlich magischer und natürlicher Heilung, erhalten –2 zusätzlich zu allen Wundabzügen."],["#","Variante Spezialfähigkeiten"],["Unsichtbar","Manche Höllenhunde sind für alle außer ihren Verfolgten unsichtbar! Angriffe gegen sie erfolgen mit –6, und solange ein Verbündeter keinen Beweis für ihre Existenz sieht, glaubt er den wahnsinnigen Hilferufen der Beute vielleicht nicht!"],["Unfehlbare Spurenleser","Höllenhunde können von rachsüchtigen Besitzern ausgesandt werden, um Beute aufzuspüren und sie eine finstere Schuld bezahlen zu lassen. Höllenhunde sind bereits unerbittliche Spurenleser, doch wenn der Wirt etwas unternimmt, das die meisten Spurenleser abschütteln würde – seinen Geruch ändern, ein Flugzeug auf einen anderen Kontinent besteigen usw. –, finden die Hunde schließlich einen Weg zu folgen. Die SL darf dem natürlich Grenzen setzen. Vielleicht können die Hunde nicht in andere Existenzebenen folgen, in die Hölle, wenn die Beute irgendwie den Körper wechselt usw."]]},{"n":"Imp","k":"Dämonen","w":0,"s":["HOR"],"p":121,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Imps sind boshafte Kreaturen, die an gewalttätigem Unfug Freude haben. Die meisten werden von einer Hexe oder einem Nekromanten beschworen oder dienen einem mächtigen Dämon.","Die Einzelheiten ihrer Gestalt variieren stark, doch die meisten sind kleine humanoide Wesen mit großen Köpfen und spitzen Ohren. Sie bevorzugen dunkle Bereiche und weichen hellem Licht fauchend oder fluchend aus. Sollten ihre bezahnten Mäuler und Klauenfinger noch Zweifel lassen, macht der boshafte Glanz in ihren Augen ihre böse Natur deutlich."],"a":[["Geschicklichkeit","W10"],["Konstitution","W6"],["Stärke","W4"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W10, Heimlichkeit W10, Kämpfen W8, Provozieren W8, Schießen W8, Wahrnehmung W8, Zaubern W10, Überreden W6","b":"6","pa":"6","ro":"4","x":[["Mächte","Unsichtbarkeit, Schlummer (Machtpunkte: 20)"]],"sf":[["Klauen","Stä+W4."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Schattenmagie","Imps sind magische Kreaturen, eng mit der Dunkelheit verbunden. Sie können ihre Kräfte nur in Bereichen mit Beleuchtungsabzug einsetzen."],["Größe -1","Imps sind 90 bis 120 cm groß."],["Schwäche (Imp-Kodex)","Imps müssen besondere Verhaltensregeln einhalten. Sie können nicht lügen (müssen aber auch nicht die Wahrheit sagen!); sie müssen auf Verlangen stets verhandeln; stimmen sie einem Handel zu, müssen sie ihn dem Buchstaben nach einhalten (aber nicht dem Geist nach!); sie müssen stets etwas Angebotenes annehmen."],["Schwäche (Sonnenlicht)","Imps sind Abgelenkt, solange sie direktem Sonnenlicht ausgesetzt sind."]]},{"n":"Bibliothekar","k":"Dämonen","w":1,"s":["HOR"],"p":121,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Es ist zweifelhaft, dass viele Dämonenfürsten Bibliotheken haben, doch diese ungewöhnlichen Dämonen sind die Gelehrten der Unterwelt. Der vielleicht im Scherz verliehene Beiname ist zum geläufigen Ausdruck geworden.","Bibliothekare sind große, blauhäutige Humanoide mit roten Augen. Ihre Köpfe sind völlig kahl, und Runen der Macht und des Wissens sind in ihren Schädel eingebrannt. Auf Reisen durch sterbliche Reiche tragen sie schwere Kapuzenumhänge, um ihr Aussehen zu verbergen.","Für Bewohner der Hölle ungewöhnlich, sind Bibliothekare durchaus bereit, Sterblichen gegen eine kleine Belohnung zu helfen, etwa eine Reliquie oder einen Wälzer voller Wissen. Wozu sie diese Dinge in der Hölle brauchen, weiß niemand."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W12"],["Willenskraft","W10"]],"f":"Akademisches Wissen W12+2, Allgemeinwissen W12, Athletik W4, Elektronik W10, Heimlichkeit W10, Kriegskunst W10, Kämpfen W4, Naturwissenschaften W12, Okkultismus W12, Provozieren W8, Recherche W12, Reparieren W10, Wahrnehmung W8, Überreden W8","b":"6","pa":"4","ro":"7","x":[["Talente","Arkane Resistenz (Verb.), Ermittler, Gelehrter (Allgemeinwissen)"]],"sf":[["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Gelehrt","Bibliothekardämonen haben ein Leben voller Bildung und erhalten bei allen Verstand-basierten Fertigkeiten einen kostenlosen Wiederholungswurf."],["Größe 1","Bibliothekare sind größer als Menschen."]]},{"n":"Pazuzu","k":"Dämonen","w":1,"s":["HOR"],"p":121,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Pazuzu haben den Kopf eines Mannes mit Löwenmähne, löwenartige Klauen an Händen und Füßen, die Flügel eines Adlers und einen Skorpionschwanz.","Auf der Erde bevorzugen sie heiße, trockene Klimazonen. Sie sollen Meister der Illusion sein, und Wüstennomaden glauben, Fata Morganas seien ihr Werk.","Pazuzu lieben grausame und oft tödliche Streiche. Ein üblicher Trick ist es, sich Wüstennomaden zu nähern und sie zu fragen, wie viel Wasser sie haben. Ist es knapp, bietet der Dämon an, sie gegen Geld zu einer Oase zu führen. In Wirklichkeit führt er sie tiefer in die Wüste und lässt sie dort zurück, damit sie einem langsamen Tod entgegensehen. Sind seine Opfer gestorben, kehrt er zurück, um sich an ihrem Fleisch zu laben."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W10"],["Willenskraft","W8"]],"f":"Allgemeinwissen W8, Athletik W8, Heimlichkeit W8, Kämpfen W8, Provozieren W12, Wahrnehmung W8, Überleben W8, Überreden W10","b":"6","pa":"6","ro":"9","x":[["Talente","Raserei (Verb.), Aufwiegler, Zurechtweisung"]],"sf":[["Klauen","Stä+W6."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht (-2)","Jeder, der einen Stacheldämon sieht, muss eine Furchtprobe mit –2 ablegen."],["Flug","Bewegungsweite 12."],["Illusionäres Aussehen","Pazuzu können als freie Aktion die Gestalt eines Menschen annehmen (oder eines Nichtmenschen, wenn dein Setting solche Völker erlaubt)."],["Vergeltung","Wenn der Dämon dem Versuch widersteht, ihn zu bannen (einschließlich jeder Runde eines Exorzismus), erleidet der Zaubernde Erschöpfung, die zum Tod führen kann!"],["Größe 2","Pazuzu sind in ihrer natürlichen Gestalt über 2,7 m groß."],["Nicht zu täuschen","Pazuzu sind Meister der Täuschung und immun gegen Herausforderungen auf Basis von Verstand."]]},{"n":"Seuchendämon","k":"Dämonen","w":1,"s":["HOR"],"p":122,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Seuchendämonen suchen die Menschheit seit Jahrtausenden heim und verbreiten überall, wo sie hingehen, Krankheit und Siechtum. Sie ähneln Menschen (oder einer anderen Spezies in einem Fantasy- oder SF-Horror-Spiel), sind aber mit nässenden Geschwüren und eitergefüllten Pusteln bedeckt und stets von einem dunklen Heiligenschein aus Fliegen umgeben."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Athletik W6, Einschüchtern W8, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6","b":"6","pa":"5","ro":"6","sf":[["Klauen","Stä+W4."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Krankheit (-4)","Jeder, der von einem Seuchendämon berührt wird, muss eine Konstitutionsprobe ablegen oder zieht sich eine Chronische Krankheit zu (siehe Savage Worlds). Die Krankheit ist ansteckend, sodass jeder, mit dem das Opfer körperlichen Kontakt hat, ebenfalls eine Konstitutionsprobe ablegen muss oder sich ansteckt. Heilen-Proben zur Behandlung der Krankheit erhalten –4."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Fliegenkranz","Der Fliegenschwarm um einen Seuchendämon macht ihn schwer zu treffen. Angreifer erhalten –2 auf alle Angriffswürfe."]]},{"n":"Besitzergreifer","k":"Dämonen","w":1,"s":["HOR"],"p":123,"bk":"sw_hor","g":"Dämonen (Horror)","d":["In ihrer natürlichen Gestalt sind Besitzergreifer dunkle Schatten unbestimmbarer Form. Sie treiben wie Wolken dahin und wechseln ihre Gestalt als Reaktion auf einen eingebildeten Wind.","Besitzergreifer existieren nur, um sterbliche Wirte zu bewohnen und sie als Marionetten zu benutzen, um Chaos und Elend zu stiften. Obwohl sie auch wache und aufmerksame Opfer in Besitz nehmen können, befallen sie lieber Schlafende, und sei es nur, um ihre Anwesenheit geheim zu halten."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Heimlichkeit W10, Provozieren W12, Wahrnehmung W6","b":"6","pa":"2","ro":"5","sf":[["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Besessenheit","Diese heimtückischen Unholde können die Macht Marionette nach Belieben wirken und nutzen Willenskraft als arkane Fertigkeit, dürfen aber nicht mehr als ein Opfer gleichzeitig besitzen. Das Opfer widersteht mit –2, die Grunddauer beträgt 24 Stunden. Den Zauber zu beenden ist eine freie Aktion."],["Vergeltung","Wenn der Dämon dem Versuch widersteht, ihn zu bannen (einschließlich jeder Runde eines Exorzismus), erleidet der Zaubernde Erschöpfung, die zum Tod führen kann!"]]},{"n":"Verführer","k":"Dämonen","w":0,"s":["HOR"],"p":123,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Während Inkubi und Sukkubi Sterbliche verführen, um sich von deren Lebensenergie zu nähren, verderben Verführerdämonen deren Seelen. Sie bevorzugen die Unschuldigen – auch wenn diese schwerer zu verderben sind, schmeckt ihren teuflischen Gelüsten das Ergebnis weit süßer.","Verführer nähern sich Sterblichen und bieten ihnen Stärke, Macht, Liebe, Reichtum oder andere Vorteile an. Diese „dunklen Gaben“ werden unauffällig innerhalb weniger Tage oder Wochen geliefert. Eine Eigenschaft zu steigern kann einige Tage dauern, um keinen Verdacht zu erregen. Reichtum kann in Form eines lukrativen Vertrags kommen oder als etwas so Simples wie der Fund einer Schatztruhe oder eines Geldbeutels. Eine Führungsposition folgt auf den Tod oder die Blamage des bisherigen Anführers."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W12"],["Willenskraft","W12"]],"f":"Athletik W6, Einschüchtern W8, Kämpfen W6, Provozieren W10, Wahrnehmung W8, Überreden W12+2","b":"6","pa":"5","ro":"6","x":[["Talente","Charismatisch, Sehr Attraktiv"]],"sf":[["Dunkle Gaben","Die dunkle Gabe eines Verführers anzunehmen, verleiht dem Empfänger einen der folgenden Vorteile, hat aber den genannten Preis. Gering: Erhöhe eine Eigenschaft um eine Würfelstufe (das darf das Maximum des Charakters übersteigen), Geld in Höhe des Fünffachen des Startkapitals des Settings, bringe jemanden dazu, dem Helden Freundlich gegenüberzustehen (siehe Überreden in Savage Worlds), verursache einem Feind Blamage oder Pech, übertrage dem Helden die Führung einer mittelgroßen Organisation oder mittlere Autorität. Schwer: Erhöhe eine Eigenschaft um zwei Würfelstufen (das darf das Maximum des Charakters übersteigen), Geld in Höhe des 20-Fachen des Startkapitals des Settings, bringe jemanden dazu, sich zu verlieben oder dem Helden Hilfsbereit zu sein (siehe Überreden in Savage Worlds), verursache einem Feind schweres Unglück oder den Tod, übertrage dem Helden die Führung einer großen Organisation oder mächtige Autorität. Jede dunkle Gabe hat natürlich ihren Preis. Eine Geringe Gabe gibt dem Helden eine Leichte Psychose, eine Schwere eine Schwere Psychose. Würde ein Held durch den Erwerb einer vierten Psychose je einen Psychotischen Zusammenbruch erleiden (siehe S. 44), wird er stattdessen zum Sklaven des Verführers und tut ohne Widerrede dessen Willen."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht","Jeder, der die Kreatur in ihrer natürlichen Gestalt sieht, muss eine Furchtprobe ablegen."],["Illusionäres Aussehen","Verführer können jede humanoide Gestalt annehmen."],["Vergeltung","Wenn der Dämon dem Versuch widersteht, ihn zu bannen (einschließlich jeder Runde eines Exorzismus), erleidet der Zaubernde Erschöpfung, die zum Tod führen kann!"]]},{"n":"Stacheldämon","k":"Dämonen","w":0,"s":["HOR"],"p":124,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Stacheldämonen sind gebückte Humanoide mit schuppiger Haut, die von kurzen, scharfen Stacheln bedeckt ist. Sie haben keine erkennbaren Gesichtszüge, haben aber keine Mühe, ihre Feinde aufzuspüren. Sie dienen meist als Gefolgsleute anderer Dämonen und Teufel."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W12"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W10, Einschüchtern W10, Heimlichkeit W8, Kämpfen W10, Schießen W10, Wahrnehmung W6","b":"6","pa":"7","ro":"6","sf":[["Klauen","Stä+W6."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht (-2)","Jeder, der einen Stacheldämon sieht, muss eine Furchtprobe mit –2 ablegen."],["Stacheln","Jeder, der einen Stacheldämon packt oder von ihm gepackt wird, erleidet zu Beginn des Zugs des Wesens 2W4 Schaden durch dessen Stacheln."],["Stachelsalve","Als Aktion kann ein Stacheldämon eine Salve scharfer Stacheln in einer Kegelschablone abfeuern. Er würfelt Schießen, um zu treffen, und Ziele, die nicht Ausweichen, erleiden 2W6 Schaden."]]},{"n":"Qualdämon","k":"Dämonen","w":1,"s":["HOR"],"p":124,"bk":"sw_hor","g":"Dämonen (Horror)","d":["Diese bizarren Wesen sind die Verkörperung des Leidens. Sie werden aus der Hölle beschworen, indem man eine ihrer Rätselschachteln löst. Manche versuchen es, weil sie die versprochenen dunklen Begierden erleben wollen, die meisten aber rein zufällig.","Sobald das Rätsel gelöst ist, erscheinen jedenfalls drei Dämonen und zeigen dem Löser die „Freuden“, die ihn erwarten. Das Ziel darf nun, wenn sie will, eine Willenskraftprobe mit –4 ablegen. Tut sie es nicht oder scheitert sie, wird sie in die Hölle entführt und wird schließlich selbst zu einem Qualdämon.","Gelingt sie, können die Dämonen versuchen, sie zu töten, oder sich bedanken und die sterbliche Welt erkunden, bis irgendein Gutmensch sie in die Hölle zurückschickt. Hat der Rätsellöser mit einer Steigerung Erfolg, setzt sich das Rätsel zurück und die Qualdämonen kehren mit einem Groll in die Hölle zurück.","Qualdämonen haben einzigartige Verstümmelungen und Narben, die die Grenze zwischen Lust und Schmerz überschreiten. Die meisten sehen noch einigermaßen menschlich aus, doch alle ergötzen sich am Elend, das sie teilen wollen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12+2"],["Stärke","W8"],["Verstand","W8"],["Willenskraft","W12+1"]],"f":"Allgemeinwissen W4, Athletik W4, Einschüchtern W10, Heilen W10, Heimlichkeit W6, Kämpfen W6, Okkultismus W8, Provozieren W8, Schießen W10, Wahrnehmung W6, Überreden W10","b":"6","pa":"5","ro":"11 (1)","x":[["Talente","Bedrohlich, Starker Wille"],["Ausrüstung","Leichte Lederrüstung (+1)"]],"sf":[["Biss/Klauen","Stä+W4."],["Ketten","Stä+W6, Reichweite 2, Zerreißen. Qualdämonen beschwören hakenbewehrte, stachelige oder groteske Ketten, die ihre Opfer aufspießen oder umschlingen. Eine Steigerung auf den Angriffswurf hält das Opfer Fest."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht (-2)","Jeder, der einen Qualdämon sieht, muss eine Furchtprobe mit –2 ablegen."],["Vergeltung","Wenn der Dämon dem Versuch widersteht, ihn zu bannen (einschließlich jeder Runde eines Exorzismus), erleidet der Zaubernde Erschöpfung, die zum Tod führen kann!"]]},{"n":"Kleinteufel","k":"Dämonen","w":0,"s":["HOR"],"p":125,"bk":"sw_hor","d":["Kleinteufel sind niedere Höllenwesen aus dem Abgrund, die oft vorgeben, weit größere Wesen zu sein, etwa der dunkle Meister selbst. Sie sind humanoid, haben aber Beine und Kopf einer Ziege.","Ein beschworener Kleinteufel spricht nicht, sondern lauscht den Bitten des Beschwörers und wiegt seinen unirdischen Kopf hin und her, als höre er sehr aufmerksam zu. Ist die Bitte vorgetragen, rennt der Betrüger davon und versucht, den Wunsch des Zaubernden auf die schlimmstmögliche Weise zu erfüllen. Er greift den Beschwörer jedoch nicht an – er will ihn stattdessen durch seine Taten quälen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W10 (A)"],["Willenskraft","W8"]],"f":"Athletik W6, Einschüchtern W8, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6, Zaubern W8","b":"6","pa":"5","ro":"6","x":[["Mächte","Barriere (unsichtbare Wand), Geschoss (Feuerblitze aus den Augen), Dunkelheit (Dunkelheitswolke), Arkanes aufspüren/verbergen (Machtwort), Furcht (Flüche), Marionette (hypnotischer Blick), Betäubung (Machtwort) (Machtpunkte: 20)"]],"sf":[["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Tritt","Stä+W4."]]},{"n":"Teufel, sterblich","k":"Dämonen","w":1,"s":["HOR"],"p":125,"bk":"sw_hor","d":["Ein sterblicher Teufel, Halbunhold oder „Cambion“","ist der Nachkomme eines Menschen und eines Dämons oder Teufels oder ein durch dämonischen Einfluss verfluchtes Kind. Typische Merkmale sind gespaltene Hufe, Hörner, fledermausartige Flügel, Klauen, Fangzähne und ein tierähnlicher Kopf. Die meisten sterblichen Teufel sind ihrer Abstammung getreu bösartige Wesen, doch nicht immer; in seltenen Fällen überwiegt die menschliche Seite. Diese moralischen Teufel sind einsame Kreaturen, von der menschlichen Gesellschaft gemieden, aber dennoch deren Vorteile begehrend. Ihre bösartigen Gegenstücke sind mörderische Wesen, die ganz ihrer tierischen, dämonischen Seite nachgeben und in Blutvergießen, Terror und Chaos schwelgen.","Der berühmteste Cambion in den Vereinigten Staaten ist der Jersey Devil. Dieses Wesen soll das 13. Kind von „Mutter“ Jane Leeds sein. Erschöpft und entnervt von der Geburt ihres 13. Kindes rief sie aus, ihr Sohn solle der Teufel sein. So verflucht wurde das Kind tatsächlich als halbmenschliches Monster geboren, bekam Flügel und entkam durch den Kamin. Es spukt nun in den Pine Barrens im Süden von New Jersey."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W6, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W8, Überleben W6","b":"6","pa":"6","ro":"7","sf":[["Biss/Klauen","Stä+W6."],["Dämon","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe, außer durch kaltes Eisen."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Unsterblich","Ein sterblicher Teufel kann nicht an Altersschwäche sterben."]]},{"n":"Dhampir","k":"Untote","w":0,"s":["HOR"],"p":125,"bk":"sw_hor","d":["Dhampire sind die Kinder einer unheiligen (und scheinbar unmöglichen) Paarung eines Vampirs mit einem Sterblichen. Sie besitzen einen Teil der Stärke und Fähigkeiten ihrer Erzeuger, können aber im Sonnenlicht wandeln und die Anwesenheit anderer Vampire erkennen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W6, Einschüchtern W8, Heimlichkeit W8, Kämpfen W8, Schießen W8, Wahrnehmung W6, Überleben W6, Überreden W4","b":"6","pa":"6","ro":"7","x":[["Handicaps","—"],["Talente","Assassine, Kampfreflexe"],["Ausrüstung","Holzpflock (Stä+W4), Pistole oder Armbrust (je nach Epoche), Kruzifix"]],"sf":[["Vampire spüren","Dhampire können Vampire (und andere Dhampire) bis zu 10“ (20 m) Entfernung erkennen. Wird dies durch Arkanes verbergen maskiert, würfelt der Dhampir mit seiner Wahrnehmung dagegen."],["Schwäche (Sonnenlicht)","Dhampire sind Abgelenkt, solange sie direktem Sonnenlicht ausgesetzt sind."]]},{"n":"Zerstückelter Leichnam","k":"Untote","w":0,"s":["HOR"],"p":126,"bk":"sw_hor","d":["Bei der ersten Begegnung sehen zerstückelte Leichname genau wie Zombies aus. Nachdem sie ihre erste Wunde erlitten haben, fliegen sie jedoch in vier Gliedmaßen, einen Rumpf, Gedärm und einen Kopf auseinander – jedes davon handelt als eigenständiges Wesen.","Die verschiedenen Teile schweben um den Rumpf, handeln aber völlig unabhängig. Diese Einzelteile schlagen, klatschen, treten und kratzen nach ihren verblüfften Gegnern."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W4"],["Willenskraft","W4"]],"f":"Athletik W6, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W4","b":"6","pa":"5","ro":"8","sf":[["Furcht (-2)","Jeder, der den zerstückelten Leichnam nach dem Zerfall sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Getrennte Gliedmaßen","Die erste(n) Wunde(n), die ein zerstückelter Leichnam erleidet, lassen ihn zerfallen, verursachen aber keinen tatsächlichen Schaden. Jedes Teil wirkt dann als Statist. Nur durch die Zerstörung aller sieben Teile kann der Leichnam besiegt werden. Kopf: Kopfstoß oder Biss für Stä Schaden. Rumpf: Rammen für Stä Schaden. Gedärm: Ringen. Arme (2): Klauenhände für Stä+W6 Schaden. Beine (2): Zehennagelklauen für Stä+W4 Schaden."],["Größe −2 (Klein)","Nach der Teilung ist jedes Teil ein kleineres Ziel und hat Robustheit 6."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Black Shuck","k":"Geister","w":1,"s":["HOR"],"p":126,"bk":"sw_hor","g":"Hunde","d":["Diese Erscheinung ist ein großer schwarzer Hund mit zottigem Fell und leuchtenden roten, untertassengroßen Augen. Black Shuck streift nachts bei Stürmen durch Wälder und Moore. Er greift diejenigen an, die Furcht zeigen, meidet aber jene, die keine zeigen, oder beschützt sie sogar. Ähnliche schwarze Hunde wurden in abgelegenen Gegenden auf der ganzen Welt gesichtet. Manchmal sollen sie den Tod ankündigen (siehe Zeichen und Vorboten auf S. 46)."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W6 (A)"],["Willenskraft","W10"]],"f":"Athletik W8, Heimlichkeit W12, Kämpfen W10, Wahrnehmung W10, Überleben (tracking) W12","b":"8","pa":"7","ro":"7","x":[["Talente","Erstschlag, Flink, Raserei"]],"sf":[["Biss","Stä+W6."],["Furcht","Wer Black Shuck sieht, muss eine Furchtprobe ablegen. Bei Misserfolg wird zusätzlich zu den üblichen Effekten die Fähigkeit Unheilsomen der Kreatur ausgelöst."],["Unheilsomen","Ein Zeuge, der vor Black Shuck Furcht zeigt, fällt unter einen Fluch. Im folgenden Jahr zählt jede misslungene Konstitutionsprobe stattdessen als Kritischer Fehlschlag. Der Fluch kann vorzeitig gebrochen werden, indem man Black Shuck in einer anderen Nacht aufsucht und die Furchtprobe besteht."],["Verschwinden","Black Shuck verschwindet spurlos, wenn das Wetter besser wird, die Sonne aufgeht oder er Ausgeschaltet wird."]]},{"n":"Schrottplatzhund","k":"Tiere","w":0,"s":["HOR"],"p":127,"bk":"sw_hor","g":"Hunde","d":["Diese Werte gelten für große Kampfhunde, die von grausamen Herren auf Bösartigkeit abgerichtet oder von unsichtbaren Kräften zur Gewalt getrieben werden."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Heimlichkeit W8, Kämpfen W6, Wahrnehmung W10, Überleben (tracking) W8","b":"8","pa":"5","ro":"5","x":[["Talente","Aufmerksamkeit, Flink, Raserei"]],"sf":[["Biss","Stä+W4."],["Größe -1","Die Köpfe dieser Hunde reichen einem durchschnittlichen Menschen meist bis zur Hüfte, und sie wiegen etwa 27 kg."]]},{"n":"Fetch","k":"Geister","w":0,"s":["HOR"],"p":127,"bk":"sw_hor","g":"Hunde","d":["Fetches sind geistige Begleiter von Sterblichen, die Geister und andere ätherische Wesen aufspüren können. Traditionell konnten nur an einem Samstag Geborene einen Fetch-Hund haben, was je nach Setting und seiner Überlieferung abweichen kann. Ein Fetch könnte etwa das Geschenk eines mächtigen übernatürlichen Verbündeten sein.","Der „Besitzer“ eines Fetch kann nicht mit ihm kommunizieren – das Wesen bleibt einfach stets bei seinem Gefährten und beschützt seinen Herrn nach besten Kräften vor dem Bösen. Es kann die körperliche Welt in keiner Weise beeinflussen.","Fetches sind unsichtbar, doch Sterbliche erhaschen gelegentlich einen Blick auf das Wesen, wenn es eine entscheidende Handlung ausführt."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W6 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W10, Überleben (tracking) W8","b":"8","pa":"5","ro":"4","x":[["Talente","Aufmerksamkeit, Flink"]],"sf":[["Biss","Stä+W6, nur gegen Ätherische."],["Grimme Warnung","Entdeckt ein Fetch einen unsichtbaren oder ätherischen Feind innerhalb von 10“ (20 m), erhält sein Wirt ebenfalls ein Gespür für den Aufenthaltsort des Feindes und ignoriert bis zu 4 Punkte seiner Angriffsabzüge."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Unsichtbares sehen","Ein Fetch kann unsichtbare Wesen sehen, ob aus Fleisch oder ätherisch."],["Größe -1","Fetches sind Hunde, deren Köpfe einem durchschnittlichen Menschen bis zur Hüfte reichen."]]},{"n":"Doppelgänger","k":"Monster","w":0,"s":["HOR"],"p":127,"bk":"sw_hor","d":["Im Horrorgenre gibt es viele Arten von Doppelgängern: Körperfresser, unter uns wandelnde Außerirdische, mythologische Wesen oder dunkle Feen, um nur einige zu nennen.","Das Profil hier gilt für einen Gestaltwandler, der eine Stunde braucht, um eine Gestalt zu kopieren, aber keine Kleidung oder Gegenstände. Solche magischen Ursprungs können ihre Beute womöglich viel schneller vollständig kopieren und stehen in den folgenden Varianten.","Doppelgänger verfolgen viele Ziele. Manche wollen das Leben eines Menschen übernehmen, aus Sehnsucht nach Gesellschaft, andere sind Späher einer außerirdischen oder monströsen Macht, die die Welt übernehmen will.","Doppelgänger sind körperlich nicht besonders stark, daher verlassen sie sich auf Heimlichkeit und List, um ihre Beute zu isolieren, bevor sie deren Haut „tragen“."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W10"],["Willenskraft","W6"]],"f":"Allgemeinwissen W6, Athletik W6, Einschüchtern W8, Heimlichkeit W10, Kämpfen W6, Wahrnehmung W6, Überleben W8, Überreden W6","b":"6","pa":"5","ro":"5","x":[["Talente","Alleskönner"]],"sf":[["Wandel","Doppelgänger nehmen die Gestalt anderer an. Bei einem bewegungsunfähigen Opfer dauert das eine Stunde und führt zu dessen Tod."],["#","Variante Spezialfähigkeiten"],["Erinnerungen","Der Doppelgänger hat vollen Zugriff auf die Fertigkeiten und Erinnerungen des Wirts (nimm jeweils den höheren Wert der beiden Wesen)."],["Schneller Wandel","Die Fähigkeit des Doppelgängers, einen Wirt nachzuahmen, ist magisch oder übernatürlich. Sie wirkt sofort, nachdem er seine Beute berührt hat, und kopiert auch Ausrüstung und Gegenstände. Besitzt der Wirt magische Gegenstände, sind die Kopien des Doppelgängers stattdessen gewöhnlich."],["Heulen","Die Kreatur kann als begrenzte Aktion ein unmenschliches Heulen ausstoßen. Das ist eine Einschüchtern-Probe in einer Kegelschablone. Alle Ziele darin sind betroffen und widerstehen einzeln. Andere Doppelgänger in Hörweite werden oft vom Heulen angelockt und eilen ihr zu Hilfe."]]},{"n":"Traumübel","k":"Geister","w":1,"s":["HOR"],"p":128,"bk":"sw_hor","d":["Zu bestimmten Zeiten des Jahres hat das Böse großen Einfluss. Halloween ist so ein Anlass, es gibt aber weitere. In dieser Zeit erlangen in den Albträumen Schlafender geborene Kreaturen die Macht, in die körperliche Welt zu treten.","Ihre genaue Gestalt variiert von Schläfer zu Schläfer. Manche erscheinen als dämonische Clowns, andere als Tentakelbestien oder wahnsinnige Versionen missbrauchender Eltern. Gleich welche Gestalt, sie alle wollen sich in der körperlichen Welt manifestieren und möglichst viel Unheil anrichten.","Traumübel materialisieren sich, nachdem ihr Wirt eingeschlafen ist, meist im Umkreis weniger Meilen, und verhalten sich dann wie das, als was sie sich manifestiert haben. Eine Riesenspinne lauert in Bäumen und verstrickt Opfer, ein böser Clown erscheint vielleicht bei einem Zirkus und lockt Besucher in ein dunkles Zelt, um sie zu verschlingen usw."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12"],["Verstand","W10"],["Willenskraft","W12"]],"f":"Athletik W8, Einschüchtern W12, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W8, Zaubern W10, Überreden W8","b":"6","pa":"7","ro":"8","x":[["Mächte","Verwirrung, Verstricken, Furcht, Illusion, Unsichtbarkeit, Gestaltwandel, Schlummer, Schall/Stille (Machtpunkte: 20)"]],"sf":[["Albtraumwesen","Traumübel verschwinden sofort, wenn ihr Wirt erwacht. Werden sie durch den Zauber Bannen vernichtet, erscheinen sie wieder, wenn der Wirt das nächste Mal schläft. Nur der Tod des Wirts, ein Exorzismus oder sieben aufeinanderfolgende Nächte ohne Schlaf des Wirts zerstören sie endgültig (siehe Schlaf unter Gefahren in Savage Worlds)."]]},{"n":"Traumräuber","k":"Geister","w":1,"s":["HOR"],"p":128,"bk":"sw_hor","d":["Traumräuber sind Albtraumgeister, die sterbliche Psychen heimsuchen und in eine schreckliche Traumlandschaft stürzen. Dort muss der Träumende darum kämpfen, eine Aufgabe zu erfüllen, Hindernisse zu überwinden und Feinde zu besiegen, oder er bleibt für immer im Albtraumland verloren.","Traumräuber ziehen oft enge Gefährten ihrer Opfer ebenfalls in das Albtraumreich. So kann eine ganze Gruppe im Albtraum eines Gefährten gefangen sein.","In der Traumlandschaft stolpert das Opfer über eine Aufgabe, die es zu erfüllen drängt. Sie kann einfach die Flucht sein, die Niederlage eines gefürchteten Feindes oder das Erreichen eines fernen Ziels. Die schrecklichen Feinde und jenseitigen Hindernisse wirken echt und sollten auch so behandelt werden, wenn auch mit der seltsamen Physik, die die Traumlandschaft verlangt.","Opfer, die in der Traumwelt sterben, bleiben in der körperlichen Welt im Koma. Sie sind im Grunde hirntot – der Traumräuber hat ihre Essenz verschlungen.","Wer überlebt und „gewinnt“, vertreibt den Traumräuber und wird für den Rest seines Lebens mit erholsamem Schlaf gesegnet. Wer zuvor unter Nachtschreck oder anderen Schlafstörungen litt, ist geheilt. Gelegentliche Albträume sind möglich, doch er weiß stets, dass es nur Träume sind, und ignoriert alle üblen Folgen.","Die Werte unten gelten für die Geistgestalt des Traumräubers. Wer solche Dinge sehen kann, erblickt ein gedrungenes, krötenartiges Humanoides mit schwarzen Augen, heraushängender Zunge und leerem, schlaffem Blick."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W10"],["Willenskraft","W8"]],"f":"Athletik W4, Heimlichkeit W10, Kämpfen W4, Wahrnehmung W6","b":"6","pa":"4","ro":"5","sf":[["Traumverzerrung","Der Traumräuber kann jedes schlafende Opfer wie oben beschrieben in das Albtraumland ziehen."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."]]},{"n":"Ertrinkling","k":"Untote","w":0,"s":["HOR"],"p":129,"bk":"sw_hor","d":["Ertrinklinge sind ertrunkene Opfer, die ins Unleben zurückgekehrt sind. Sie sehen aus wie zu Lebzeiten, tragen aber wassergetränkte Kleidung, die nie trocknet."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Athletik W6, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6","b":"6","pa":"5","ro":"7","sf":[["Wasserwesen","Bewegungsweite 6."],["Ertränken","Ertrinklinge umklammern ihre Opfer und pressen ihnen Wasser in Mund und Lunge. Gepackte Gegner müssen beim Packen und zu Beginn des Zugs des Wesens, solange sie Gebunden oder Verstrickt bleiben, eine Konstitutionsprobe ablegen. Misslingt sie, erleiden sie Erschöpfung. Ist ein Opfer Ausgeschaltet, tritt der Tod nach einer Anzahl Runden gleich seinem Konstitutionswürfel ein."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Gefühlsgeist","k":"Geister","w":0,"s":["HOR"],"p":129,"bk":"sw_hor","d":["Gefühlsgeister sind körperlose Verkörperungen einer dunklen oder negativen Emotion, etwa Hass oder Gier.","Sie heften sich an ein Opfer, das – zumindest für einen Moment – von ihrem jeweiligen Laster befallen war. Ein Gieriger Charakter, oder einer, der auch nur zeitweise gierig war, könnte die Aufmerksamkeit des Geistes erregen.","Danach folgt die Kreatur ihrem Wirt, unsichtbar und ätherisch, und steigert diese negative Eigenschaft bis zum Extrem, in der Hoffnung, mehr Elend und Schmerz zu verursachen.","Für jene, die sie sehen können, hängt die Gestalt von der Art ab. Ein Geist der Gier erscheint vielleicht als feister, von goldenen Ketten niedergedrückter Mensch. Ein Geist der Grausamkeit ist womöglich mit weinenden Peitschenstriemen übersät."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4"],["Willenskraft","W10"]],"f":"Athletik W6, Heimlichkeit W8, Kämpfen W6, Wahrnehmung W6","b":"6","pa":"5","ro":"5","sf":[["Dunkle Emotion","Der Geist heftet sich an ein einzelnes Opfer und bleibt für die Dauer seines „Lebens“ in dessen Nähe. Solange er anwesend ist, verstärkt er die negativen Emotionen des Wirts und macht sie verzweifelter, gewalttätiger oder langlebiger. Ein friedlicher Mann wird vielleicht zornig oder jähzornig, ein von Natur aus zorniger wahrscheinlich gewalttätig."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."]]},{"n":"Böser Clown","k":"Monster","w":0,"s":["HOR"],"p":129,"bk":"sw_hor","d":["Die irrationale Furcht vieler vor Clowns ist nicht immer irrational. Unten steht eine gängige Version des bösen Clowns – der Sorte, die Opfer in die Dunkelheit lockt und verschlingt.","Eine Horde Clowns hat die unten genannten Werte. Ein einzelner Clown – oder manchmal ein „Boss-Clown“ – ist eine Wildcard."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W6, Einschüchtern W8, Fahren W6, Heimlichkeit W8, Kämpfen W8, Provozieren W10, Wahrnehmung W6, Überreden W10","b":"6","pa":"6","ro":"7","x":[["Talente","Kampfakrobat, Raserei (Verb.), Zurechtweisung"]],"sf":[["Biss","Stä+W12, Zerreißen."],["Klauen","Stä+W6."],["Furcht (-2)","Hat ein Clown sein Opfer isoliert und allein, legt er seine Verkleidung ab und zeigt sein wahres Ich, was eine Furchtprobe mit –2 auslöst."]]},{"n":"Furchtpirscher","k":"Geister","w":1,"s":["HOR"],"p":130,"bk":"sw_hor","d":["Furchtpirscher entstehen, wenn ein Mensch überwältigende Angst erlebt. Die elenden, unsichtbaren Wesen heften sich dann an das Opfer und treiben es in Schrecken, Ruin, Wahnsinn oder durch Missgeschick in den Tod."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Athletik W6, Einschüchtern W10, Heimlichkeit W10, Wahrnehmung W6","b":"6","pa":"2","ro":"5","sf":[["Furcht verstärken","Das Opfer wird mit der Zeit nervös und schreckhaft und erhält für jede Woche, die der Geist anhaftet, –1 auf seine Furchtproben, bis maximal –4."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."]]},{"n":"Fleischreißer","k":"Monster","w":0,"s":["HOR"],"p":130,"bk":"sw_hor","d":["Fleischreißer sind fleischlose Humanoide, die die Haut von Opfern zum Überleben brauchen.","Obwohl sie auch Tierhäute nutzen können, bevorzugen die meisten den behaglichen Sitz menschlicher Haut. Besonders schöne oder charismatische Menschen sind ihre bevorzugten Ziele. Einzelne Fleischreißer haben womöglich andere Vorlieben, etwa stark tätowierte Opfer oder solche mit bestimmter Haar- oder Augenfarbe."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Allgemeinwissen W4, Athletik W8, Einschüchtern W8, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W8, Überreden W8","b":"6","pa":"7","ro":"7","sf":[["Klauen","Stä+W4, Zerreißen."],["Tarnung","Ein Fleischreißer, der die Haut eines Opfers trägt, sieht aus, klingt und bewegt sich wie das Opfer. Er hat jedoch keine seiner Erinnerungen, Handicaps oder Talente."],["Furcht (-2)","Wer die Kreatur ohne Haut sieht, muss eine Furchtprobe mit –2 ablegen."],["Regeneration","Jedes Mal, wenn ein Fleischreißer eine neue Haut anlegt, erholt er eine Wunde. Nur so kann er Schaden heilen."],["Widerstandsfähig","Kann eine zusätzliche Wunde einstecken."],["Hautverlust","Jedes Mal, wenn ein Fleischreißer eine Wunde erleidet, muss er eine Konstitutionsprobe ablegen. Bei Misserfolg ist die getragene Haut ruiniert und fällt ab, und die Kreatur zeigt sich in ihrer natürlichen Gestalt. Für jede Stunde ohne Haut muss die Kreatur eine Konstitutionsprobe ablegen oder erleidet eine Wunde."],["Häuten","Fleischreißer können ein Ausgeschaltetes Opfer in drei Runden häuten und ziehen die gesamte Haut in einem Stück ab. Dann braucht er 1W4 Runden, um sie anzulegen und mit ihr zu verschmelzen."]]},{"n":"Fliegender Kopf","k":"Monster","w":0,"s":["HOR"],"p":130,"bk":"sw_hor","d":["Bei manchen Stämmen nordamerikanischer Indianer gibt es Geschichten von fliegenden Köpfen. Jeder Kopf ist so groß wie ein Mann und ruht auf zwei kurzen Beinen. An jedem Bein sitzt eine Reihe kräftiger Klauen. Fliegende Köpfe stoßen einen furchterregenden Schrei aus, der einem Krieger das Blut gefrieren lässt."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Athletik W10, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W8","b":"4","pa":"6","ro":"6","sf":[["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht (außer Blitze) und Einschüchtern."],["Flug","Bewegungsweite 8."],["Tritt","Stä+W6."],["Schrei","Einmal pro Nacht und erneut jedes Mal, wenn die Aktionskarte eines fliegenden Kopfes im Kampf eine Bildkarte ist, kann er als einzige Aktion seinen typischen Schrei ausstoßen. Jeder innerhalb von 12“ (24 m) muss eine Furchtprobe mit –1 pro beteiligtem fliegenden Kopf ablegen (maximal –4)."],["Schwäche (Blitz)","Fliegende Köpfe fürchten Blitze und müssen eine Furchtprobe ablegen, wenn sie einen sehen, oder versuchen, in irgendeine Deckung zu fliehen."]]},{"n":"Geist","k":"Geister","w":0,"s":["HOR"],"p":131,"bk":"sw_hor","d":["Gespenster, Schatten und Phantome kehren manchmal vom Tod zurück, um die Lebenden heimzusuchen oder ein verlorenes Ziel zu erfüllen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W8, Athletik W6, Einschüchtern W12, Heimlichkeit W12, Kämpfen W6, Provozieren W10, Wahrnehmung W12","b":"6","pa":"5","ro":"5","x":[["Ausrüstung","Geworfene Gegenstände (Stä+W4)"]],"sf":[["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht (-2)","Geister verursachen Furchtproben mit –2, wenn sie sich sehen lassen."],["#","Variante Spezialfähigkeiten"],["","Geister in Horrorgeschichten haben viele verschiedene Kräfte und Fähigkeiten. Passe sie mit diesen oder anderen Fähigkeiten nach Belieben an."],["Energieentzug","Bei einer erfolgreichen Berührung oder einem Angriff muss das Opfer eine Konstitutionsprobe ablegen oder verliert einen Würfeltyp in Stärke oder Konstitution (je nachdem, was höher ist, bei Gleichstand nach Wahl des Geistes). Würde der Angriff die Konstitution unter W4 senken, muss das Opfer am Ende seines nächsten Zugs eine Konstitutionsprobe ablegen oder stirbt. Sofern es nicht getötet wird, erholt sich ein Opfer alle 24 Stunden um einen Würfeltyp."],["Illusionen","Der Geist kann nach Belieben kleine Illusionen erzeugen. Mit mehr Aufwand (meist höchstens einmal pro Szene) kann er größere Illusionen erschaffen, etwa seine gesamte Umgebung verwandeln. Illusionen können keinen Schaden anrichten, doch sie können ein unvorsichtiges Opfer zu Schaden führen!"],["Materialisieren","Der Geist kann als begrenzte freie Aktion sichtbar (oder sogar körperlich) werden. Er kann so erscheinen, wie er in der Geisterwelt aussieht, bei seinem Tod oder zu einem beliebigen Zeitpunkt seines Lebens."],["Beinahe allwissend","Der Geist lauert meist im Hintergrund, belauscht die Lebenden und wartet auf eine Gelegenheit zuzuschlagen. Er weiß beinahe alles, was die Helden in seinem Bereich sagen oder tun, sofern er nicht irgendwie abgelenkt ist."],["Vergeltung","Widersteht der Geist einem Versuch, ihn zu bannen (einschließlich jeder Runde eines Exorzismus), erleidet der Zaubernde Erschöpfung, die zum Tod führen kann!"],["Telekinese","Der Geist kann die materielle Welt beeinflussen, ohne sich zu manifestieren – Stühle balancieren, Messer schleudern usw., als wäre er real. Dabei bleibt er meist unsichtbar."]]},{"n":"Weiße Frau","k":"Geister","w":1,"s":["HOR"],"p":132,"bk":"sw_hor","d":["Die Weiße Frau ist ein Beispiel für eine bestimmte Geisterart und bezieht sich auf eine Reihe ähnlicher Geschichten um ein solches Wesen.","Eine Weiße Frau erscheint als blasse, weiß gekleidete Frau. Meist bedeckt sie ihr Gesicht und weint. Wer unglücklich genug ist, in ihre Augen zu blicken, sieht nur dunkle, hohle Leeren. Sie verkörpert eine Tragödie, meist um vermisste oder ermordete Kinder oder einen Ehemann. Sie erscheint Reisenden auf Straßen, bittet um Hilfe oder eine Mitfahrt und folgt ihnen nach Hause, ob man ihr hilft oder nicht. Dort beginnt der eigentliche Ärger. Sie klopft in unregelmäßigen Abständen immer verzweifelter an die Tür. Wird sie hereingebeten, verschwindet sie und beginnt das Haus heimzusuchen und die Bewohner zu ermorden, andernfalls verschwindet sie bei Sonnenaufgang und sucht sich mit dem nächsten Einbruch der Nacht neue Reisende zum Verfolgen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W8"],["Verstand","W10"],["Willenskraft","W10"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W8, Überreden W8","b":"6","pa":"6","ro":"9","x":[["Talente","Arkane Resistenz (Verb.), Killerinstinkt"]],"sf":[["Klauen","Stä+W6. Sie nutzt ihre Klauen nur gegen Opfer, die in ihre Augen geblickt oder sie in ihr Heim eingeladen haben."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht (-2)","Wer die hohlen Augen der Weißen Frau sieht oder ihr Klopfen hört, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Unverwundbarkeit","Wird eine Weiße Frau durch etwas anderes als den Zauber Bannen Ausgeschaltet, verlässt sie das Haus, das sie heimsucht, erscheint aber schließlich wieder auf der Straße, um erneut zu verfolgen. Ihre Einladungen sind dann nicht mehr gültig. Sie mit der Macht Bannen auszuschalten beendet ihre Bedrohung für immer."],["Zum Tode gezeichnet","Wer in ihre Augen blickt, unterliegt bis Sonnenaufgang dem Fluch der Weißen Frau: Alle Konstitutionsproben erhalten –2."],["Schwäche (Tageslicht)","Die Weiße Frau kann tagsüber nicht erscheinen. Sie ist dann gar nicht anwesend und kehrt erst nach Sonnenuntergang des nächsten Tages zurück, entweder dorthin, wo sie zuletzt verschwand, oder an die Straße, die sie üblicherweise heimsucht."],["Schwäche (nur auf Einladung)","Die Weiße Frau kann eine private Behausung nicht ohne Einladung betreten. Öffentliche Bereiche darf sie nach Belieben betreten."]]},{"n":"Ghul","k":"Untote","w":0,"s":["HOR"],"p":132,"bk":"sw_hor","d":["Ghule sind widerwärtige Aasfresser, die sich an Kadavern und unglücklichen Opfern laben, die ihnen beim Fressen in den Weg kommen. Ghule haben blasse, gummiartige Haut mit der Beschaffenheit ungebackenen Teigs. Ihre Augen sind groß und leuchten in einem blassen, wilden Gelb. Sie haben scharfe Klauen und Zähne, an denen oft Fetzen ausgelösten Fleisches hängen.","Ghule treiben sich meist in Rudeln herum und leben in riesigen Bauen mit über 20 Individuen und einem Wildcard-König oder einer Königin."],"a":[["Geschicklichkeit","W10"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W10, Kämpfen W6, Wahrnehmung W8, Überleben W8","b":"6","pa":"5","ro":"6","sf":[["Klauen","Stä+W4."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Feine Nase","Ghule erhalten +2 auf Wahrnehmung gegen lebende Ziele und auf Überleben, um sie zu verfolgen."],["Lähmung","Wer von einem Klauenangriff eines Ghuls Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er für 2W6 Runden gelähmt und zu keiner Aktion fähig – nicht einmal zum Sprechen."],["Schwäche (Sonnenlicht)","Ghule sind Abgelenkt, solange sie direktem Sonnenlicht ausgesetzt sind."]]},{"n":"Goblin","k":"Monster","w":0,"s":["HOR"],"p":133,"bk":"sw_hor","d":["Das sind nicht die Goblins epischer Fantasy, sondern die verdrehten Feen der Märchen. Die Legenden sagen, sie jagen Kinder, vielleicht um sie in ihren Stamm aufzunehmen, doch vielleicht sind das nur Ammenmärchen.","Diese schwachsinnigen Kreaturen sind klein und blind, mit milchig-weißen Augen ohne Pupillen. Sie orientieren sich an dunklen Orten per Echoortung und geben dabei leise gurrende Laute von sich, die oft wie die Babys klingen, die sie angeblich stehlen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W4"],["Willenskraft","W4"]],"f":"Athletik W6, Heimlichkeit W8, Kämpfen W6, Wahrnehmung W8","b":"4","pa":"5","ro":"7 (2)","sf":[["Panzerung +2","Feen-Goblins sind dicht bemuskelt und haben dicke, ledrige Haut."],["Blind","Goblins „sehen“ per Echoortung und sind immun gegen sichtbasierte Effekte (Dunkelheit, Unsichtbarkeit usw.)."],["Graben (Bewegungsweite 4)","Kann sich durch alles außer massivem Stein graben; kann unter der Erde nur durch besondere Mittel angegriffen werden."],["Klauen","Stä+W4, PB 2. Goblinklauen sind dicht und scharf und können massiven Stein ritzen."],["Größe -1","Goblins sind 1,20 m groß."],["Schwäche (Geräusche)","Goblins können durch anhaltenden lauten Lärm oder magische Stille „geblendet“ werden."],["#","Variante Spezialfähigkeiten"],["Rudeltaktik","Für eine weit brutalere, koordinierte Gruppe von Goblins addiere jeden Bonus für Gruppenangriff auf ihre Schadenswürfe im Kampf."]]},{"n":"Bestiengolem","k":"Konstrukte","w":0,"s":["HOR"],"p":133,"bk":"sw_hor","g":"Golems (Horror)","d":["Tiergolems sind aus Teilen vieler Bestien zusammengenäht. Unten steht ein Beispiel mit Rumpf und Beinen eines Bären sowie Vorderläufen und Kopf eines Löwen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W4"],["Willenskraft","W10"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6, Überleben W6","b":"6","pa":"6","ro":"10 (1)","x":[["Talente","Berserker, Raserei (Verb.)"]],"sf":[["Panzerung +1","Harte Muskeln."],["Biss/Klauen","Stä+W6."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht","Wer einen Bestiengolem sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Golems sind immun gegen Furcht (außer vor Feuer) und Einschüchtern."],["Größe 2","Da er auf einem Bären basiert, ist dieser Bestiengolem über 2,4 m groß."],["Schwäche (Feuer)","Bestiengolems fürchten Feuer. Sie sind Abgelenkt in der Nähe einer Person mit brennender Fackel oder einem ähnlichen Gegenstand."]]},{"n":"Blutgolem","k":"Konstrukte","w":0,"s":["HOR"],"p":134,"bk":"sw_hor","g":"Golems (Horror)","d":["Blutgolems entstehen, indem das Blut vieler Kreaturen magisch gebunden wird. Blut gerinnt schnell, daher muss es beim Ritual frisch sein. Bald darauf wird es zu einem dicken Gelee.","Blutgolems sind dunkelrot und humanoid, haben aber außer zwei leuchtend gelben Schlitzen als Augen keine Gesichtszüge."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W4"],["Willenskraft","W8"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6","b":"6","pa":"6","ro":"8","sf":[["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Blutgolems sind immun gegen Furcht und Einschüchtern."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Unverwundbarkeit","Nichtmagische Angriffe jeder Art verursachen halben Schaden."],["Größe 1","Blutgolems sind etwas größer als ein Mensch."],["Niederwalzen","Stä+W4."],["Ersticken","Gepackte Gegner müssen beim Packen und zu Beginn des Zugs des Wesens, solange sie Gebunden oder Verstrickt bleiben, eine Konstitutionsprobe ablegen. Misslingt sie, erleiden sie Erschöpfung. Ist ein Opfer Ausgeschaltet, tritt der Tod nach einer Anzahl Runden gleich seinem Konstitutionswürfel ein."]]},{"n":"Knochengolem","k":"Konstrukte","w":0,"s":["HOR"],"p":134,"bk":"sw_hor","g":"Golems (Horror)","d":["Anders als Skelette sind Knochengolems ein Mischmasch aus Knochen, die durch dunkle Magie verbunden sind. Viele haben Knochenstacheln, die ihr ohnehin groteskes Aussehen verstärken."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12"],["Verstand","W4"],["Willenskraft","W8"]],"f":"Athletik W10, Einschüchtern W8, Heimlichkeit W8, Kämpfen W10, Wahrnehmung W6","b":"8","pa":"7","ro":"12 (2)","x":[["Talente","Raserei"]],"sf":[["Panzerung +2","Knochen."],["Knochenklauen","Stä+W4."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht","Charaktere, die einen Knochengolem sehen, müssen eine Furchtprobe ablegen."],["Furchtlos","Knochengolems sind immun gegen Furcht und Einschüchtern."],["Größe 2","Knochengolems sind meist über 2,7 m groß."]]},{"n":"Leichengolem","k":"Konstrukte","w":0,"s":["HOR"],"p":134,"bk":"sw_hor","g":"Golems (Horror)","d":["Leichengolems sind Flickenmenschen aus Teilen anderer kürzlich Verstorbener."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12"],["Verstand","W4"],["Willenskraft","W10"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6","b":"5","pa":"6","ro":"8 (1)","x":[["Handicaps","Langsam (Leicht)"],["Talente","Arkane Resistenz, Berserker"],["Ausrüstung","Meist ein Langschwert (Stä+W8)"]],"sf":[["Panzerung +1","Harte Haut und Muskeln."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Golems sind immun gegen Furcht und Einschüchtern."]]},{"n":"Marionettengolem","k":"Konstrukte","w":0,"s":["HOR"],"p":135,"bk":"sw_hor","g":"Golems (Horror)","d":["Geschichten von besessenen Marionetten (Fadenpuppen) reichen Jahrhunderte zurück. Modernere Marionettengolems können als Puppen oder Teddybären gefertigt sein."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W8"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Athletik W6, Einschüchtern W6, Heimlichkeit W10, Kämpfen W8, Provozieren W8, Wahrnehmung W6","b":"6","pa":"6","ro":"7 (2)","x":[["Ausrüstung","Messer (Stä+W4)"]],"sf":[["Panzerung +2","Hölzerner Körper. (Bei Teddybären, Stofftieren usw. ignorieren.)"],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furchtlos","Golems sind immun gegen Furcht und Einschüchtern."],["Größe -2 (Klein)","Marionetten sind nicht größer als 60 cm."]]},{"n":"Grabfluch","k":"Untote","w":1,"s":["HOR"],"p":135,"bk":"sw_hor","d":["Wenn ein mächtiger Nekromant stirbt, sein Geist aber nicht weiterziehen will, kann ein Grabfluch entstehen. Grabflüche sind große Wolken fauliger Energie. Sie behalten ein wenig Intelligenz, sind aber vor allem am Fressen interessiert. Dazu lassen sie nahe Untote beleben, die für sie jagen.","Die bevorzugte Taktik des Grabfluchs ist, verborgen zu bleiben und mit seinen Zombies Wesen in der Nähe zu töten. Sind alle Beutetiere tot, bringen die Zombies die Leichen zur Aufnahme zum Grabfluch."],"a":[["Geschicklichkeit","W4"],["Konstitution","W10"],["Stärke","W6"],["Verstand","W8 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Heimlichkeit W10, Kämpfen W6, Schießen W8, Wahrnehmung W8","b":"4","pa":"5","ro":"7","sf":[["Aufblähen","Als begrenzte Aktion kann ein Grabfluch seine Masse stark aufblähen. In der ersten Runde schwillt er auf die Größe einer Kleinen Flächenschablone an. In der nächsten Runde auf eine Mittlere, dann in der dritten auf eine Große. In der vierten Runde schrumpft er auf Normalgröße zurück. Einmal begonnen, muss der Vorgang zu Ende geführt werden. Wer in der Kleinen Schablone gefangen ist, erleidet 3W6 Schaden, da er ihm die Lebensessenz entzieht, in der Mittleren 2W6, in der Großen 1W6. Der Grabfluch hat keinen weiteren direkten Angriff."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Zombie","Grabflüche behalten die Macht, Tote zu beleben, aber nur im Umkreis von etwa 10“ (20 m) um ihr Grab. Die meisten kontrollieren bei der Begegnung 2W6 Zombies, die knapp unter der durchnässten Erde liegen und angriffsbereit sind."]]},{"n":"Grauer","k":"Außerirdische","w":0,"s":["HOR"],"p":135,"bk":"sw_hor","d":["Diese schwer fassbaren, fortgeschrittenen Wesen stammen von anderswo im Universum. Sie erscheinen als schlanke, haarlose Humanoide mit eiförmigen Köpfen, großen schwarzen Augen, winzigen Nasen und Mündern und grauer Haut (daher der Name).","Was sie hierher führt, ist ein Rätsel, doch Graue suchen Wüsten und andere abgelegene Orte heim, wo sie isolierte Opfer zu Experimenten in ihre Raumschiffe bringen. Gefangene erinnern sich kaum an mehr als helle Lichter, bizarre Humanoide und furchterregende Sonden.","Eines der Raumschiffe der Grauen soll in Roswell, New Mexico, abgestürzt sein und wird nun von der US-Regierung in einer streng geheimen Forschungseinrichtung festgehalten – vielleicht steckt ihre fremdartige Technik hinter manchen unserer eigenen wissenschaftlichen Sprünge."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W6"]],"f":"Athletik W6, Elektronik W8, Fliegen W10, Heilen W10, Heimlichkeit W6, Kämpfen W6, Naturwissenschaften W10, Psionik W10, Reparieren W8, Schießen W6, Wahrnehmung W8","b":"6","pa":"5","ro":"10 (4)","x":[["Talente","Arkaner Hintergrund (Psionik), Mentalist"],["Mächte","Eigenschaft steigern/senken, Verwirrung, Gedankenverbindung, Gedankenlesen, Gedächtnis löschen, Marionette, Schlummer, Betäubung, Telekinese (Machtpunkte: 20)"],["Ausrüstung","Betäubungswaffe (Reichweite 1/2/4, Konstitutionsprobe mit –2 oder Betäubt), Skalpell, futuristische Körperpanzerung (+4)"]],"sf":[]},{"n":"Vettel","k":"Monster","w":1,"s":["HOR"],"p":136,"bk":"sw_hor","g":"Vetteln","d":["Vetteln haben sich finsteren Mächten verschrieben im Austausch für Rache, langes Leben oder andere dunkle Begierden. Sie sind die Monster, die Kinder kochen und jene ermorden, die sich in ihr Gebiet verirren. Sie schwelgen in extremem Gemetzel, Grauen und Groteskem. Sie nutzen ihre Magie vielleicht, um sich unter die verhasste Bevölkerung zu mischen und eine Gemeinschaftspastete magisch mit Maden zu füllen, einen schrecklichen Industrieunfall zu verursachen oder einen Fahrer zu einem grausigen Unfall zu erschrecken.","Manche Vetteln sind teils Troll oder Oger, oder einzigartige Kreaturen, verdreht von welchen dunklen Mächten auch immer, die ihnen ihre schreckliche Magie verleihen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Allgemeinwissen W8, Athletik W8, Einschüchtern W10, Heilen W8, Heimlichkeit W10, Kämpfen W10, Okkultismus W10, Provozieren W8, Wahrnehmung W8, Zaubern W10, Überreden W4","b":"6","pa":"7","ro":"7","x":[["Handicaps","Hässlich (Schwer)"],["Talente","Arkaner Hintergrund (Magie), Assassine, Raserei (Verb.), Bedrohlich, Aufwiegler, Rundumschlag (Verb.)"],["Mächte","Eigenschaft steigern/senken, Ablenkung, Verkleidung, Verstricken, Fernsicht, Furcht, Fliegen (Besen), Illusion, Illusionäre Schrecken, Unsichtbarkeit, Licht/Dunkelheit, Schloss öffnen/schließen, Schutz, Marionette, Verbündeten beschwören, Dämon beschwören, Wandläufer (Machtpunkte: 25)"]],"sf":[["Biss/Klauen","Stä+W6, PB 2, Zerreißen."],["Furcht (-2)","Wer ein Vettel in ihrer wahren Gestalt sieht, muss eine Furchtprobe mit –2 ablegen."],["#","Variante Spezialfähigkeiten"],["Fluch des Verderbens","Wird ein Vettel getötet, belegt sie ihre Mörder mit einem boshaften Fluch. Bis der Charakter ein rituelles Magiebannen erhält (oder eine andere von der SL gesetzte Aufgabe erfüllt), zählt jede misslungene Konstitutionsprobe stattdessen als Kritischer Fehlschlag."],["Ogerblut","Das Vettel hat die Stärke eines Ogers (W12+2), Größe 2, und kann nach Ermessen der SL die Talente Rohling, Berserker und Rundumschlag haben."]]},{"n":"Waldvettel","k":"Monster","w":1,"s":["HOR"],"p":136,"bk":"sw_hor","g":"Vetteln","d":["Eine Waldhexe war eine böse und rachsüchtige Hexe, die starb und eine gequälte Seele zurückließ, die den Wald besessen hält, den sie einst durchstreifte. Sie sind unsichtbare, körperlose Wesen mit Hass auf die Lebenden und im Tod noch mächtiger als im Leben.","Waldhexen verfluchen eine ganze Waldregion um ihren Unterschlupf und durchdringen Bäume, Tiere und sogar das Land selbst mit ihrer üblen Gegenwart. Sie zeigen sich selten und greifen lieber mit ihren Kräften an, wobei sie belebte Bäume, wütende Tiere und das Land selbst nutzen, um jene zu quälen, die in ihr Reich eindringen.","Die berühmteste Waldhexe der amerikanischen Geschichte war Kate Batts, auch bekannt als die Bell-Hexe. Sie suchte Anfang des 19. Jahrhunderts die Familie von John Bell in Tennessee heim. Sie quälte sie jahrelang und soll für den Tod von John Bell selbst verantwortlich sein."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W6"],["Verstand","W10"],["Willenskraft","W10"]],"f":"Allgemeinwissen W12, Athletik W6, Einschüchtern W8, Heimlichkeit W10, Kämpfen W4, Okkultismus W10, Provozieren W8, Wahrnehmung W8, Zaubern W10","b":"6","pa":"4","ro":"7","x":[["Handicaps","Skrupellos (Schwer), Rachsüchtig (Schwer)"],["Talente","Arkaner Hintergrund (Magie)"],["Mächte","Barriere (Unterholz und Ranken), Tierfreund, Blenden, Verwirrung, Fluch, Elementarkontrolle, Verstricken (Unterholz und Ranken), Umweltkontrolle (Feuer, Eis, Regen, Erdrutsche), Furcht, Chaos, Illusion, Illusionäre Schrecken, Eigenschaft senken, Albträume, Schlummer, Betäubung, Telekinese (Machtpunkte: 30)"]],"sf":[["Verfluchter Wald","Waldhexen beanspruchen eine Waldregion im Umkreis einiger Meilen um ihren früheren Unterschlupf. Die Grenzen ihres Reichs sind durch seltsame okkulte Symbole in Bäumen und Felsen oder durch an Bäumen hängende Stockpuppen markiert, die offensichtlich oder verborgen sein können. Furchtproben in einem verfluchten Wald erhalten –2, Überleben-Proben zum Spurenlesen, Jagen oder Navigieren –4, und Eindringlinge erholen sich dort nie von Erschöpfung."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht","Wird eine Waldhexe sichtbar, löst ihr Anblick eine Furchtprobe aus."],["Flug","Bewegungsweite 12."],["Unverwundbar","Eine Waldhexe kann durch magische Angriffe Ausgeschaltet, aber nicht getötet werden. Einmal Ausgeschaltet, kehrt ihre Seele zur Ruhe in den Waldboden zurück. Dabei macht sie wie gewohnt natürliche Heilungswürfe und kann sich erst wieder manifestieren, wenn alle ihre Wunden geheilt sind. Der einzige Weg, einen Wald dauerhaft von einer Waldhexe zu befreien, ist, ihr Grab (oder ihre Knochen) zu finden und einen ordentlichen Exorzismus durchzuführen (S. 76). Ist die Waldhexe nicht Ausgeschaltet, tut sie natürlich alles, um das Ritual zu stören."]]},{"n":"Sumpfvettel","k":"Monster","w":1,"s":["HOR"],"p":137,"bk":"sw_hor","g":"Vetteln","d":["Eine Sumpfhexe ist ein weibliches humanoides Wesen, das in Seen und Sümpfen lebt. Die meisten stammen von Trollen oder Ogern ab, mit durchnässtem, verfaulendem Fleisch, scharfen schwarzen Klauen, breiten Mäulern voller kleiner, gezackter Zähne und langem, strähnigem Haar, das von abgestandenem Wasser trieft. Sumpfhexen sind Fleischfresser und lauern darauf, dass Tiere und Menschen dem Wasser zu nahe kommen, in dem sie sich verbergen. Dann brechen sie aus dem Schlamm hervor und greifen an.","Zu den Sumpfhexen der Folklore zählen Fuath, Fideal und das Monster namens Jenny Green-Teeth."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12"],["Stärke","W12"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8, Zaubern W8","b":"6","pa":"6","ro":"10","x":[["Mächte","Verwirrung, Ablenkung, Verkleidung, Elementarkontrolle, Verstricken (Wasserpflanzen), Trägheit, Betäubung (Machtpunkte: 20)"]],"sf":[["Wasserwesen","Bewegungsweite 10."],["Panzerung +2","Dicke oder speckige Haut."],["Biss/Klauen","Stä+W6."],["Umweltresistenz (Feuer)","Die nasse Haut der Sumpfhexe verleiht ihr +4 Widerstand / –4 Schaden durch feuerbasierte Effekte."],["Furcht (–2)","Wer eine Sumpfhexe sieht, muss eine Furchtprobe mit –2 ablegen."],["#","Variante Spezialfähigkeiten"],["Regeneration (Schnell)","Natürlicher Heilungswurf jede Runde, außer bei Wunden durch Feuer oder Hitze."]]},{"n":"Vorbote","k":"Geister","w":0,"s":["HOR"],"p":137,"bk":"sw_hor","d":["Ein Vorbote ist eine geflügelte Kreatur, die während oder kurz vor tödlichen Katastrophen am Himmel erscheint. Ob sie vom nahenden Unheil angezogen werden oder es irgendwie verursachen, ist unbekannt. Vorboten sind stumm, doch schon ihr Erscheinen ist eine Art Warnung für jene, die verstehen, was sie sehen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W10"],["Willenskraft","W12"]],"f":"Allgemeinwissen W8, Athletik W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6","b":"6","pa":"6","ro":"7","x":[["Talente","Arkane Resistenz (Verb.), Kampfreflexe, Gefahrensinn, Ausweichen, Kühler Kopf (Verb.)"]],"sf":[["Biss/Klauen","Stä+W6."],["Verhängnis","Wer die Furchtprobe nicht besteht, erhält das Handicap Dem Untergang geweiht (S. 6), bis der Vorbote Ausgeschaltet wird oder ein schreckliches Ereignis abgeschlossen ist."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Flug","Bewegungsweite 10."]]},{"n":"Hass","k":"Geister","w":1,"s":["HOR"],"p":137,"bk":"sw_hor","d":["Ein Hass entsteht, wenn mehrere Seelen ein gemeinsames Schicksal erleiden. Man findet sie meist auf Schlachtfeldern, an Massakerschauplätzen und in Todeslagern. Wenn die Körper der Opfer sterben, sammeln sich ihre Seelen zu einer Masse wirbelnder, schreiender Geister. Hasse sind nur von Rachegedanken erfüllt. Zwar zielen sie zunächst auf jene, die sie im Leben unterdrückten, doch ihr Rachedurst kann nie gestillt werden, und schnell werden auch Unschuldige zur Beute."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Wahrnehmung W6","b":"6","pa":"4","ro":"7","sf":[["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Raserei","Ein Hass füllt eine Große Flächenschablone. Betritt ein Lebewesen die Schablone oder beginnt seinen Zug darin, muss es eine Willenskraftprobe mit –4 ablegen. Wer scheitert, verfällt in Berserker (wie das Talent) und greift den nächsten Charakter an, ob Freund oder Feind. Außerhalb der Schablone legen die Opfer des Hasses automatisch eine weitere Willenskraftprobe (–4) ab, um sich aus der Kontrolle zu befreien (deshalb folgen Hasse ihren Opfern und halten sie in ihrem Wirkungsbereich). Entkommt ein Höriger, ist er Erschüttert."],["Schwarm","+2 auf Erholung von Erschüttert; Parade +2; Große Flächenschablone; Hieb- und Stichangriffe verursachen keinen Schaden, magische Flächenwaffen wirken normal."]]},{"n":"Spukrüstung","k":"Geister","w":0,"s":["HOR"],"p":138,"bk":"sw_hor","d":["Manchmal geben die Geister derer, die eine Rüstung bewohnten, dieser Leben. Ein andermal wird sie durch zauberische Machenschaften belebt. So oder so ist eine wandelnde leere Plattenrüstung ein herausfordernder Gegner!"],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W10"],["Verstand","W4 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6","b":"6","pa":"7 oder 9 (shield)","ro":"10 (4)","x":[["Talente","Block, Rundumschlag (Verb.)"],["Ausrüstung","Schwert (Stä+W8) oder Streitkolben (Stä+W6). Manche tragen auch einen Mittleren Schild (Parade +2)"]],"sf":[["Panzerung +4","Die meisten Geister bewohnen Plattenrüstungen."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furchtlos","Immun gegen Furcht und Einschüchtern."]]},{"n":"Spukauto","k":"Geister","w":0,"s":["HOR"],"p":138,"bk":"sw_hor","d":["Spukautos (oder andere Fahrzeuge) sind von bösen Maschinengeistern besessen, die sich „nähren“, indem sie Opfer unter oder in ihren Rädern zermalmen. Spukautos sind empfindungsfähig und böswillig. Sie wissen auch, dass sie zerstört werden können, und halten sich daher bedeckt – wenn sie nicht gerade auf mörderischem Amoklauf sind.","Spukautos steuern sich selbst, spielen aber gern eine Weile mit ihren Opfern, bevor sie sich an deren zerschmetterten Körpern laben. Das kann Tage oder gar Wochen dauern, wenn das Auto einen bestimmten Fahrer lieb gewinnt.","Geschieht das, was unweigerlich passiert, „verliebt“ sich der Maschinengeist in den Fahrer und tötet nachts oder wenn der Fahrer nicht da ist, um nicht der Versuchung zu erliegen, stattdessen ihn zu verschlingen. Solche Geister werden oft sehr eifersüchtig auf andere, die um die Aufmerksamkeit ihres Fahrers konkurrieren.","Verfolge die Wunden des Autos wie bei jedem anderen Fahrzeug. Es kann Zerstört werden, repariert sich aber durch Langsame Regeneration (siehe unten)."],"a":[["Geschicklichkeit","W8"],["Konstitution","—"],["Stärke","—"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Fahren W12 (plus Handling), Kämpfen W8","b":"As vehicle","pa":"2 (Inanimate Object)","ro":"As vehicle","x":[["Handicaps","Blutrünstig, Fies"],["Talente","Arkane Resistenz (Verb.), Starker Wille"]],"sf":[["Panzerung","Die Robustheit des Autos gilt für jeden Teil des Fahrzeugs, sogar die Fenster. Das ist schließlich Magie!"],["Kontrolle","Das Auto kann sein gesamtes Zubehör steuern, es mit der Klimaanlage eiskalt machen oder das Radio so laut aufdrehen, dass alle darin taub werden. Es kann auch über das Radio kommunizieren und aus gesprochenen Worten verschiedener Sender eine kryptische Nachricht zusammensetzen oder bestimmte Lieder spielen. Es kann zudem seine Türen (oder andere Öffnungen) mit einer Stärke von W12+2 geschlossen halten."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Nähren","Spukautos müssen mindestens einmal pro Woche von Fleisch und Blut zehren oder erleiden eine Wunde. Das tun sie durch Rammen oder indem sie einen ahnungslosen Menschen einsteigen lassen und bei der ersten Gelegenheit, wenn niemand hinsieht, verunglücken."],["Regeneration (Langsam)","Spukautos würfeln jeden Tag eine Willenskraftprobe, um ihre Wunden zu „heilen“. Dellen beheben sich selbst, Reifen füllen sich, Stoßstangen befestigen sich wieder usw. Selbst Zerquetschen ist für das Fahrzeug nur ein vorübergehender „Tod“. Nur ein Exorzismus kann ein Spukfahrzeug dauerhaft zerstören."]]},{"n":"Spukgemälde","k":"Geister","w":0,"s":["HOR"],"p":139,"bk":"sw_hor","d":["Ein Spukgemälde ist ein Gemälde, das von einem boshaften Geist besessen ist – typischerweise einem Schatten oder Abbild der dargestellten Person."],"a":[["Geschicklichkeit","W4"],["Konstitution","W10"],["Stärke","W4"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Provozieren W10, Wahrnehmung W8, Zaubern W10, Überreden W8","b":"—","pa":"2","ro":"7","x":[["Mächte","Furcht, Schutz, Marionette, Telekinese (Machtpunkte: Unlimited)"]],"sf":[["Beleben","Der Geist kann das Abbild jeder Person im Porträt beleben. Es kann zwar nicht angreifen, aber die Augen bewegen, um Leuten zu folgen, den Mund zum Sprechen öffnen und sogar die Hand für Gesten bewegen."],["Unverwundbarkeit","Der Geist kann nur in dem Gemälde verletzt werden, das er sein Zuhause nennt. Aus naheliegenden Gründen verraten sie ungern, welches das ist."],["Schwäche (Feuer)","Spukgemälde erleiden +4 Schaden durch Feuer."],["#","Variante Spezialfähigkeiten"],["Manifestation","Manche sehr mächtige Gemälde können ihre Motive eine Zeit lang in die körperliche Welt entlassen, meist nicht länger als eine Stunde pro Tag. Jedes Abbild darin kann sich manifestieren – nimm die Werte dessen, was das Gemälde zeigt, die Kreaturen sind aber stets Statisten. Manifestiert verschwinden sie aus dem Gemälde, und wenn sie „getötet“ werden, kehrt ihr Abbild zurück."],["Hineinziehen","Manche Spukgemälde können Betrachter auch hineinziehen! Wenn der Geist es will, muss jedes Wesen, das sich auf etwa 30 cm nähert und die Details des Gemäldes auch nur einen Moment anstarrt, eine Willenskraftprobe mit –4 ablegen oder wird in die dargestellte Welt gerissen. Das dauert, bis die Helden (Betrachter dürfen freiwillig scheitern, um einem Gefährten zu folgen) das Gemälde in seiner eigenen Albtraumwelt besiegen. Sein Profil dort hängt von der angenommenen Gestalt ab, ist aber meist etwas unglaublich Mächtiges wie ein Drache oder ein Dämon."]]},{"n":"Höllendrache","k":"Dämonen","w":1,"s":["HOR"],"p":139,"bk":"sw_hor","d":["Höllendrachen ähneln Drachen, haben aber sieben Köpfe, die jeweils einen blasphemischen Namen eingraviert tragen. Ihre dicken Schuppen sind feuerrot wie die Feuer des Infernos, das sie hervorbrachte, und mit unheiligen Runen und Siegeln graviert.","In manchen Settings können Höllendrachen als Reittiere mächtiger Dämonen der Hölle dienen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12+9"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Athletik W10, Einschüchtern W12, Kämpfen W10, Wahrnehmung W12, Zaubern W12","b":"10","pa":"7","ro":"20 (4)","x":[["Talente","Arkane Resistenz (Verb.), Champion, Kühler Kopf (Verb.)"],["Mächte","Explosion (Höllenfeuer, Opfer können Feuer fangen), Schwall (fault das Fleisch von den Knochen), Furcht (unheilige Flüche), Eigenschaft senken (Fluch), Marionette (verführerische Worte), Betäubung (Brüllen), Zombie (von unheiligem Geist besessener Leichnam) (Machtpunkte: Unlimited)"]],"sf":[["Panzerung +4","Schuppenhaut."],["Biss/Klauen","Stä+W8."],["Furcht (-4)","Wer einen Höllendrachen sieht, muss eine Furchtprobe mit –4 ablegen."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Mehrere Köpfe","Höllendrachen haben sieben Köpfe. Jeder Kopf darf in einer Runde einen Kämpfen- oder Zaubern-Wurf ohne Mehrfachaktionsabzug ablegen (aber höchstens zwei Köpfe pro Zug gegen dasselbe Ziel, unabhängig von dessen Größe). Jeder Kopf hat eine Wunde und wird abgetrennt, wenn er Ausgeschaltet wird. Jeder der sieben Köpfe kennt eine der Kräfte der Kreatur. Wird ein Kopf abgetrennt, verliert der Höllendrache diese Kraft. Schaden an den Köpfen verursacht keine Wundabzüge für den Höllendrachen, doch er stirbt, wenn der letzte Kopf abgetrennt wird (der einzig wahre Weg, ihn zu töten)."],["Regeneration (Schnell)","Höllendrachen erhalten jede Runde als freie Aktion einen natürlichen Heilungswurf, auch wenn sie Ausgeschaltet sind – selbst gegen Feuer und Säure. Das lässt Köpfe aber nicht nachwachsen – diese wachsen binnen einer Woche nach. Die Regeneration lässt sich nur stoppen, indem man alle sieben Köpfe abtrennt, bevor einer nachgewachsen ist."],["Größe 8 (Riesig)","Höllendrachen sind über 12 m lang."]]},{"n":"Raureifkrieger","k":"Geister","w":0,"s":["HOR"],"p":140,"bk":"sw_hor","d":["Diese boshaften Geister waren einst nordische Krieger, die aus den gefrorenen nördlichen Ländern reisten, um nach Reichtum und Fleisch zu plündern. Anders als viele ihrer Wikingerbrüder waren sie im Leben kaum mehr als mörderische Schläger. Ihre Seelen wurden vom Jenseits abgewiesen, und nun sind sie verflucht, als Raureifkrieger über die Meere zu ziehen und immer wieder Küstengemeinden zu überfallen.","Im Leben beschränkten die Wikinger ihre Raubzüge hauptsächlich auf europäische Küsten. Daher sind Raureifkrieger in diesen Regionen am wahrscheinlichsten anzutreffen. Doch die Macht des Fluchs kann sie an jede Küste führen, an der die Temperatur unter den Gefrierpunkt fällt.","Wenn sie erscheinen, nähern sie sich dem Ufer in langen, dunklen Booten, die nur Silhouetten in der Nacht sind. Die Raureifkrieger gleiten lautlos über die Wellen von ihrem schattenhaften Schiff in ahnungslose Städte und verbreiten Chaos und Tod in der Siedlung.","Gelegentlich entführen die Geisterräuber männliche Opfer und nehmen sie auf ihre ätherischen Langboote mit.","Der Legende nach füllen die Gefangenen die Reihen der ätherischen Kriegerscharen wieder auf, wenn deren Zahl schwindet.","Raureifkrieger sind nur im Mondlicht sichtbar.","Dort erscheinen sie als durchscheinende, hünenhafte nordische Krieger mit blasser weißer Haut, hellblauen Adern und Haar. Tief in ihrer Brust schlägt der funkelnde Umriss ihrer gefrorenen Herzen im Takt ihrer Blutgier."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W4"],["Willenskraft","W8"]],"f":"Athletik W8, Boote fahren W8, Einschüchtern W8, Kämpfen W8, Schießen W6, Wahrnehmung W4, Überleben W8","b":"6","pa":"6","ro":"6","x":[["Talente","Beidhändig, Beidhändiger Kampf"],["Ausrüstung","Zwei Streitäxte (Stä+W8), Bogen (Reichweite 12/24/48, Schaden 2W6)"]],"sf":[["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht","Raureifkrieger verursachen Furchtproben, wenn sie sichtbar sind."],["Schwäche (Tageslicht)","Raureifkrieger können nur nachts erscheinen, sobald der Mond aufgegangen ist. Sie verschwinden, wenn der Tag anbricht oder der Mond untergegangen ist."],["Schwäche (Feuer)","Raureifkrieger erleiden normalen Schaden durch Feuer oder brennende Waffen."],["Schwäche (Eisiges Herz)","Ein Raureifkrieger-Geist kann körperlich verletzt werden, wenn jemand wagt, sein eisiges Herz zu packen und aus dem Körper zu reißen. Ein Held muss dazu einen erfolgreichen Ringen-Angriff mit Steigerung ablegen, um das Herz zu greifen und herauszureißen. Gelingt das, verliert der Raureifkrieger bis Sonnenaufgang die Fähigkeit Ätherisch."]]},{"n":"Homunkulus","k":"Konstrukte","w":0,"s":["HOR"],"p":141,"bk":"sw_hor","d":["Der Homunkulus ist ein von einem Zauberwirkenden erschaffenes Lebewesen. Sie sind winzig, menschenförmig und nehmen manchmal das grobe Aussehen oder die Eigenschaften ihrer Schöpfer an. Die Rezepte für Homunculi variieren, doch alle haben eines gemeinsam: Die seltsamen Konstrukte leben, haben aber keine wahre Seele.","Das Fehlen einer Seele und ihre arkane Natur machen Homunculi zu perfekten Gefäßen für dämonische oder geistige Besessenheit. Die meisten Zauberer fallen ihren eigenen Schöpfungen binnen Stunden nach deren Erschaffung (und Besessenheit) zum Opfer.","Im Dienst ihres Schöpfers dienen Homunculi als Diener, Spione oder einfache Gesellschaft. Fallen sie jedoch unter den Einfluss eines boshaften Geistes, richten sie sich auf Unfug und Chaos – oder weit Schlimmeres.","Das Aussehen eines Homunkulus hängt weitgehend von den Zutaten ab, aus denen er geformt wurde. Manche sind pflanzenartig, andere ähneln Echsen oder anderen Reptilien. Mit der Zeit können sie menschlichere Züge annehmen, wenn sie sich an ihren Schöpfer binden – oder dämonischere, wenn sie diabolischem Einfluss erliegen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W4"],["Verstand","W6"],["Willenskraft","W4"]],"f":"Athletik W6, Heimlichkeit W10, Kämpfen W6, Wahrnehmung W6","b":"6","pa":"5","ro":"2","sf":[["Klauen","Stä."],["Formbarer Körper","Ein Homunkulus kann seinen Körper durch jeden Spalt von mindestens 2,5 cm Durchmesser zwängen."],["Giftiger Atem","Ein Homunkulus kann eine kleine Gaswolke ausatmen, die als sehr mildes Beruhigungsmittel wirkt. Gegen ein voll bei Bewusstsein befindliches Ziel hat sie keine Wirkung, doch ein bereits schlafendes Opfer muss eine Konstitutionsprobe (–2) ablegen oder fällt in tieferen Schlummer, der eine Stunde dauert. Ziele mit einer oder mehr Stufen Erschöpfung sind ebenfalls anfällig, würfeln aber eine einfache Konstitutionsprobe (abzüglich der Erschöpfungsmodifikatoren). Der Schlaf ist so tief, dass ein Opfer nur dann eine Konstitutionsprobe zum Erwachen erhält, wenn es tatsächlichen körperlichen Schaden nimmt."],["Gift (Mild)","Ein von einem Homunkulus im Kampf getroffener Charakter muss eine Konstitutionsprobe ablegen, unabhängig davon, ob die Kreatur genug Schaden verursacht, um die Robustheit zu überwinden. Scheitert er, erhält er eine Stufe Erschöpfung. Das Gift ist nicht stark genug, um zum Tod zu führen, und so erlangte Erschöpfung verschwindet nach einer Stunde."],["Größe -4 (Winzig)","Homunculi sind 15 cm groß."]]},{"n":"Icthynit","k":"Humanoide","w":0,"s":["HOR"],"p":141,"bk":"sw_hor","d":["Die Icthyniten sind eine Rasse von Fischmenschen aus einer von der Menschheit längst vergessenen Zeit. Aus der Ferne wirken sie humanoid. Aus der Nähe sieht man den silbernen Glanz ihrer geschuppten Haut und die fischartigen Mäuler voller scharfer, durchscheinender Zähne. Am bemerkenswertesten sind ihre glänzenden, metallischen Augen, die nie blinzeln.","Reisende wollen auf einsamen Meeresabschnitten uralte, von diesen Fischmenschen bewohnte Städte gesichtet haben. Vielleicht wurden diese verlorenen Metropolen sogar von den Icthyniten selbst erbaut.","Falls ja, sind die Geheimnisse ihrer uralten Zivilisation längst verloren, denn die wilden Fischmenschen scheinen keine Erinnerung daran zu haben. Stattdessen klettern sie über die verfallenen Ruinen, kämpfen untereinander und fressen alle Sterblichen, die sich in die Nähe ihrer Behausungen wagen.","Selten verschmelzen Icthyniten durch Wildheit oder Zauberei mit Menschen.","Die Nachkommen überleben selten, doch einige haben sich in die menschliche Gesellschaft integriert, viele ohne Ahnung von ihrer unnatürlichen Abstammung, aber mit verborgenen Ahnenerinnerungen tief in ihrer Seele. Echte Icthyniten singen nachts manchmal vom Meer her und rufen alle Sterblichen, die sich an ihr fremdes Lied erinnern können. Wandert jemand zu den Wellen, wird er vom Ufer geholt und in die wässrige Umarmung des Fischvolks genommen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W4"],["Willenskraft","W6"]],"f":"Athletik W8, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W8","b":"6","pa":"6","ro":"8 (2)","sf":[["Wasserwesen","Bewegungsweite 8."],["Panzerung +2","Icthyniten haben zähe Schuppen."],["Biss/Klauen","Stä+W6"],["Blutrausch","Erleidet ein anderer Charakter oder ein Tier eine Wunde, verfallen alle Icthyniten innerhalb von 6“ (12 m) durch den Blutgeruch in Berserker. Icthyniten können ihre Raserei erst beenden, wenn alle Feinde tot sind."],["Gesang","Ein Icthynit kann ein fremdartiges Lied singen, wenn er keine andere Aktion und keine Bewegung ausführt. Jeder sterbliche Charakter innerhalb von 12“ (24 m) plus 6“ pro weiterem mitsingenden Icthyniten muss entscheiden, ob er Icthynitenblut in den Adern hat. Falls ja, ist er automatisch gebannt (siehe unten), erhält aber fortan die Ahnenfähigkeit Halb-Wasserbewohner. Alle, die das Singen des Fischvolks hören, müssen eine Willenskraftprobe ablegen oder werden gebannt, als wären sie der Macht Marionette unterworfen, für eine Stunde oder bis sie sich befreien (siehe Marionette). Wer Icthynitenblut hat, zieht 4 von seinen anfänglichen Widerstandswürfen und den Würfen zum Befreien ab. Das Ziel der Icthyniten ist, jene mit ihrer Blutlinie in Hybriden zu verwandeln (siehe unten)."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."]]},{"n":"Icthynit-Hybrid","k":"Humanoide","w":0,"s":["HOR"],"p":142,"bk":"sw_hor","d":["Diese abscheulichen Mutationen entstehen, wenn ein Mensch mit Icthynitenabstammung vom Fischvolk in die salzigen Tiefen gebracht wird. Sobald ein Opfer hinabgebracht wird, tritt sein Erbe als dünne Kiemen am Hals hervor. In der folgenden Woche bildet seine Haut eine dünne graue Schuppenschicht, und seine Zähne werden spitzer und knorpelig. Zudem wachsen Schwimmhäute zwischen Fingern und Zehen, und seine Augen quellen hervor und passen sich seiner neuen Restlichtsicht an.","Ob ein Hybrid seine Menschlichkeit wiedererlangen kann, bleibt dem Setting überlassen, doch falls ja, sollte es die Macht Heilung mit dem Modifikator Große Heilung als Ritual erfordern. Zumindest einige der Exotischen Komponenten sollten vom Fischvolk stammen – vielleicht sogar aus ihrem Unterwasserkönigreich oder aus dem Blut des dunklen Gottes, dem sie dienen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Allgemeinwissen W6, Athletik W6, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W6, Überreden W4","b":"6","pa":"5","ro":"5","sf":[["Wasserwesen","Bewegungsweite 6"],["Biss/Klauen","Stä+W4"],["Blutrausch","Erleidet ein anderer Charakter oder ein Tier eine Wunde, werden alle Icthyniten innerhalb von 6“ (12 m) vom Blutgeruch in Raserei getrieben. Das lässt sie in Berserker verfallen (wie das Talent). Anders als ihre reinblütigen Vettern kann ein Hybrid versuchen, seine Wut zu beenden, indem er einen ganzen Zug nichts tut (nicht einmal sich bewegt) und eine Verstandsprobe (–2) ablegt."],["Gesang","Die Stimmbänder eines Hybriden sind nicht genug entwickelt, um das hypnotische Lied der Icthyniten zu beginnen. Als Aktion kann er jedoch seine Stimme dem Chor leihen und zählt als zusätzlicher Icthynit, um die Reichweite des Singens zu erhöhen."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."]]},{"n":"Springteufel","k":"Konstrukte","w":0,"s":["HOR"],"p":143,"bk":"sw_hor","d":["Der „Wilde Jack“ soll von einem wahnsinnigen Spielzeugmacher mit Hass auf Kinder erschaffen worden sein und ist ein Werkzeug von Furcht und Rache. Derselbe Spielzeugmacher könnte auch die ersten Marionettengolems erschaffen haben (siehe S. 134).","Tagsüber sieht er aus wie ein normales Kinderspielzeug, nachts wird er zu einem verdrehten, makabren Narren mit Hass auf Kinder. Seine Lieblingstaktik ist, an seiner Schachtel zu rütteln, bis das Kind neugierig wird und sie öffnet. Jack springt dann heraus, bewaffnet mit einem gemeinen, gezackten Messer, befleckt vom Blut früherer Opfer.","Ein Springteufel kann sprechen, tut es aber meist nur, um seine Opfer einzuschüchtern und zu verspotten."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W6, Einschüchtern W12, Heimlichkeit W8, Kämpfen W8, Provozieren W12+2, Wahrnehmung W8","b":"2","pa":"6","ro":"4","x":[["Talente","Assassine"],["Ausrüstung","Messer (Stä+W4)"]],"sf":[["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Hüpfen","Jack bewegt sich hüpfend und nimmt seine ganze Schachtel mit. Er würfelt einen W4 als Sprintwürfel."],["Größe -2 (Klein)","Jacks Schachtel ist weniger als 60 cm hoch."],["Federnd","Jack sitzt auf einer kräftigen Feder und hat Reichweite 1 (2 m). Anstelle von „Sprinten“ kann er diese auf 2 (4 m) ausdehnen."],["Überraschung!","Jack erhält Der Überraschungsangriff gegen einen ahnungslosen Feind, der seine Schachtel öffnet."]]},{"n":"Kuchisake-onna","k":"Monster","w":1,"s":["HOR"],"p":143,"bk":"sw_hor","d":["Kuchisake-onna ist die Frau mit dem aufgeschlitzten Mund aus der japanischen Legende. Die ursprüngliche Kuchisake-onna war eine schöne Frau, die von einer auf ihre Schönheit eifersüchtigen Frau entstellt wurde. Kuchisake-onna erscheint als bescheiden wirkende Frau, die ihr Untergesicht hinter einem Fächer oder Schleier verbirgt. In moderner Zeit trägt sie vielleicht einen Schal oder eine Atemschutzmaske, jede Art Gesichtsbedeckung, um ihre Entstellung zu verbergen. In der Hand hält sie ein scharfes Schneidwerkzeug wie ein Skalpell, ein Messer oder sogar eine Schere."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W12"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W8, Heimlichkeit W8, Kämpfen W10, Wahrnehmung W6, Überreden W6","b":"8","pa":"7","ro":"8","x":[["Handicaps","Dünnhäutig (Schwer)"],["Talente","Flink, Sehr Attraktiv"],["Ausrüstung","Scharfe Klinge (Stä+W4, PB 2)"]],"sf":[["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Mund aufschlitzen","Kuchisake-onna ignorieren bis zu 2 Punkte Abzüge für einen Gezielten Angriff auf den Kopf."],["Teleportation","Mit einer erfolgreichen Willenskraftprobe kann eine Kuchisake-onna bis zu 24“ (48 m) weit teleportieren."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Sehr schnell","Kuchisake-onna ignorieren 2 Punkte Mehrfachaktionsabzüge."],["Schwäche (Eitelkeit)","Kuchisake-onna sind von ihrer Schönheit besessen. Trifft sie auf einen Lebenden, fragt sie ihn, ob er sie schön findet. Eine positive Antwort lässt sie ihr Gesicht enthüllen und erneut fragen; sie tötet jene, die vor Furcht reagieren oder negativ antworten. Antworten sie mit Ja, greift sie sie an und schlitzt ihnen den Mund auf wie ihren eigenen. Der einzige Weg, beiden Schicksalen zu entgehen, ist, sie nach der Enthüllung durchschnittlich aussehend zu nennen oder ihr eine Gegenfrage zu stellen. Die Kuchisake-onna ist von dieser Reaktion Betäubt, sodass das potenzielle Opfer fliehen oder sie angreifen kann."]]},{"n":"Leanhaum-Shee","k":"Monster","w":0,"s":["HOR"],"p":144,"bk":"sw_hor","d":["Die Leanhaum-shee (sprich: Lie-an-schie) aus der irischen Folklore ist eine Art vampirische Fee. Sie nutzt ihr atemberaubendes Aussehen und ihre verführerische Art, um Männer zu versklaven und saugt ihnen dann die Lebenskraft aus."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W10"],["Willenskraft","W10"]],"f":"Allgemeinwissen W4, Athletik W8, Heimlichkeit W6, Kämpfen W6, Provozieren W10, Wahrnehmung W6, Überreden W12+2","b":"6","pa":"5","ro":"6","sf":[["Versklaven","Eine Leanhaum-shee versklavt Sterbliche mit ihrem verführerischen Charme. Das funktioniert wie Marionette mit Überreden der Leanhaum-shee als arkaner Fertigkeit, doch einmal gebannt ist die Dauer unbegrenzt. Das Opfer kann versuchen, Befehlen (wie bei Marionette) mit einer Willenskraftprobe zu widerstehen, doch die Fee kann sie in ihrem Zug einfach erneut erteilen (aber nicht mehr als einmal pro Zug). Der Zauber wird nur gebrochen, wenn die Leanhaum-shee stirbt oder einen neuen Hörigen wählt, denn sie darf nie mehr als einen gleichzeitig haben."],["Lebensentzug","Jede Woche, die ein Sklave gebannt bleibt, unabhängig von der Entfernung zwischen Herrin und Sklave, muss er eine Willenskraftprobe ablegen oder senkt seine Konstitution um einen Würfeltyp. Sinkt die Konstitution unter W4, stirbt er. Ein Würfel Konstitution wird mit jedem natürlichen Heilungswurf zurückgewonnen, sobald der Griff der Leanhaum-shee über den Sklaven gebrochen ist."],["Überirdische Schönheit","Eine Leanhaum-shee ist unglaublich schön. Als begrenzte freie Aktion kann sie ein Lebewesen innerhalb von 6“ (12 m), das sie ansieht, zu einer Willenskraftprobe zwingen oder es ist Betäubt. Diesen Trick darf sie in derselben Begegnung nicht zweimal bei derselben Person anwenden."]]},{"n":"Riesenblutegel","k":"Tiere","w":0,"s":["HOR"],"p":144,"bk":"sw_hor","d":["Ein Blutegel ist eine zitternde Nacktschnecke, die das Blut ihrer Beute trinkt. Er packt zu und setzt einen Saugnapf an, der das Gefühl betäubt, und nimmt dann durch kräftigen Sog Blut auf. Blutegel greifen bevorzugt Schlafende an oder Kreaturen, die so groß sind, dass sie den Blutverlust vielleicht nicht bemerken. Ein Blutegel dieser Größe, der sich an einem Menschen festsetzt, wird definitiv bemerkt und ist tödlich, wenn er nicht gelöst wird."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W12"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Athletik W6, Heimlichkeit W10, Kämpfen W6, Wahrnehmung W6","b":"4","pa":"5","ro":"6","sf":[["Wasserwesen","Bewegungsweite 4."],["Blutentzug","Gepackte Gegner müssen beim Packen und zu Beginn des Zugs der Kreatur, solange sie Gebunden oder Verstrickt bleiben, eine Konstitutionsprobe ablegen. Misslingt sie, erleiden sie Erschöpfung, die zum Tod führen kann."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Aufplatzen","Wer dem Griff eines Blutegels entkommt oder ihn tötet, während er festsitzt, lässt die Wunde mit 2W6 Schaden aufplatzen. Den Blutegel Erschüttern oder Betäuben löst den Griff ohne Platzen, ebenso wie ihn mit Salz zu vergiften (siehe unten)."],["Wandkrabbler","Ein Blutegel kann mit voller Bewegungsweite auf senkrechten oder überhängenden Flächen kriechen und darf sprinten."],["Schwäche (Salz)","Mehr als ein Pfund Salz, direkt auf die Haut eines Riesenblutegels gebracht, zählt als Tödliches Gift (siehe Savage Worlds) und lässt ihn jede Beute loslassen, an der er festsitzt."]]},{"n":"Schrecklicher Lich","k":"Untote","w":1,"s":["HOR"],"p":145,"bk":"sw_hor","d":["Schrecklichen Lichs sind jene üblen Wesen, die seit Jahrhunderten existieren und ihre Meisterschaft der dunklen Künste verfeinern. Sie haben weit größere Macht als niedere Lichs und können sogar ihre Essenz auf andere Untote unter ihrem üblen Einfluss übertragen.","Sie sind meist von einer Horde Skelette oder Zombies umgeben, wie sie es wählen. Manche Lichs haben ganze Armeen von Untoten zur Verfügung."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W12+2"],["Willenskraft","W12"]],"f":"Allgemeinwissen W8, Athletik W8, Einschüchtern W12, Heimlichkeit W10, Kriegskunst W10, Kämpfen W10, Okkultismus W12+2, Wahrnehmung W10, Zaubern W12, Überreden W8","b":"6","pa":"7","ro":"15 (6)","x":[["Talente","Anführer, Inbrunst, Taktiker"],["Mächte","Alle (Machtpunkte: 65)"],["Ausrüstung","Magische Rüstung (+6), Bannschwert, Zweihänder (Stä+W10+1)"]],"sf":[["Todesberührung","Lichs entziehen den Lebenden um sich mit einer Berührung das Leben. Statt eines normalen Angriffs kann ein Lich einen Berührungsangriff ablegen. Jede Steigerung auf seinen Kämpfen-Wurf verursacht seinem Ziel eine Wunde. Ein Ausgeschaltetes Opfer muss eine Konstitutionsprobe ablegen oder reiht sich 1W4 Runden später als Zombie in die Reihen der Verdammten ein."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Unverwundbarkeit","Schreckliche Lichs können nur durch magische Angriffe verletzt werden."],["Anführer der Verdammten","Kommando, Eifer und Taktiker eines Schrecklichen Lichs gelten nur für untote Statisten."],["Essenz übertragen","Ein Schrecklicher Lich kann seine Essenz mit einem erfolgreichen Zaubern-Wurf und 5 Machtpunkten auf jeden untoten Nicht-Wildcard innerhalb von 6“ (12 m) übertragen. Bei Erfolg zerfällt der alte Körper zu Staub, und der neue Körper wird zum Schrecklichen Lich mit allen Wunden intakt!"],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Zombie","Die von Schrecklichen Lichs erweckten Untoten sind stets dauerhaft und können nach Ermessen der SL ohne Zusatzkosten mit seltsamen Kräften und Fähigkeiten verstärkt werden. Betrachte das als einzigartige Version der Macht Zombie, falls sie im Kampf erweckt werden müssen. Welche Kräfte und Fähigkeiten sie genau haben, liegt bei der SL – denk daran, dass Schurken nicht fair spielen müssen!"]]},{"n":"Lebender Gott","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":145,"bk":"sw_hor","d":["Diese Abscheulichkeiten sind keine echten Götter, sondern übernatürliche Diener solcher Wesen. Man findet sie vor allem bei den alten Ägyptern. Sie haben Menschenkörper, aber Tierköpfe.","So gibt es krokodilköpfige lebende Götter im Gefolge von Sobek, schakalköpfige im Gefolge von Anubis und kuhköpfige im Gefolge von Hathor.","Auf der Erde führen sie meist einen Kult von Anbetern an.","In einem Fantasy-Setting könnten sie ebenso gut Diener anderer Götter sein und die Köpfe heiliger Tiere tragen. In einem SF-Spiel könnten sie eine außerirdische Rasse sein, die sich bei einer primitiven Kultur als göttliche Boten ausgibt."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12+2"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W4, Athletik W8, Einschüchtern W10, Glaube W10, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6, Überreden W8","b":"6","pa":"7","ro":"10","x":[["Talente","Arkaner Hintergrund (Wunder), Block, Kampfreflexe, Raserei (Verb.), Schnell"],["Mächte","Tierfreund (Befehl über Tiere derselben Art), Geschoss (göttliche Energie), Arkanes aufspüren/verbergen (göttliches Sehen), Furcht (Heulen), Sprache sprechen (göttliches Verstehen), Tempo (übernatürliche Reflexe), Betäubung (Machtwort), Teleportation (blendender Blitz) (Machtpunkte: Unlimited)"]],"sf":[["Biss/Klauen","Stä+W6."],["Furcht","Wer die Kreatur sieht, muss eine Furchtprobe ablegen."],["Größe 2","Lebende Götter sind über 3 m groß."]]},{"n":"Lebendes Grimoire","k":"Konstrukte","w":0,"s":["HOR"],"p":146,"bk":"sw_hor","d":["Grimoires sind Bücher mit dunklem Wissen oder Zaubern. Die meisten sind einfach Bücher, wenngleich sie vielleicht in Blut geschrieben sind oder Bilder enthalten, bei denen selbst dem stärksten Magen mulmig wird. Lebende Grimoires jedoch sind magische Schöpfungen, die das Buch vor neugierigen Personen schützen sollen.","Lebende Grimoires sind eigentlich nur die Einbände des Buches, das sie bewahren. Meist haben sie die Form dämonischer Gesichter, klaffender Mäuler oder einfach scharfer Klauen, die das Buch geschlossen halten. Sie machen sich nur bemerkbar, wenn jemand außer dem rechtmäßigen Besitzer versucht, das Buch aufzuheben oder zu öffnen. Das Töten des Grimoires beschädigt die Seiten darin nicht (ein Nebenprodukt der Magie bei seiner Erschaffung).","Lebende Grimoires sprechen viele Sprachen, unterhalten sich aber meist nur, um Leute zu bedrohen oder zu verspotten. Ein lebendes Grimoire, dessen Inhalt Zauber umfasst, kann diese Magie zu seiner Verteidigung einsetzen."],"a":[["Geschicklichkeit","W4"],["Konstitution","W10"],["Stärke","W8"],["Verstand","W4 (A)"],["Willenskraft","W12"]],"f":"Einschüchtern W10, Kämpfen W6, Provozieren W10, Wahrnehmung W6, Zaubern W8","b":"—","pa":"2","ro":"5","x":[["Mächte","Geschoss (dunkle Energie), Arkanes verbergen (verändert sein Aussehen zu einem gewöhnlichen Wälzer), Dunkelheit (Dunkelheitskugel), Ablenkung (Skeletthände), Furcht (dämonisches Lachen), Fliegen (schlägt mit dem Einband wie mit Flügeln), Teleportation (begleitet von irrem Lachen), Zombie (Beschwörungsformel) (Machtpunkte: 15)"]],"sf":[["Biss/Klauen","Stä+W8."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Unbeweglich","Ein Grimoire kann nur Charaktere angreifen, die versuchen, es aufzuheben. Sein Kämpfen-Wurf spiegelt seine Angriffsfähigkeit wider, nicht die Verteidigung."],["Größe -2 (Klein)","Grimoires sind weniger als 60 cm breit."],["#","Varianten"],["Flug","Bewegungsweite 8."]]},{"n":"Lebende Formhecke","k":"Monster","w":0,"s":["HOR"],"p":146,"bk":"sw_hor","d":["Ob durch Magie oder dämonische Besessenheit belebt, lebende Formhecken suchen die Winkel herrschaftlicher Häuser und die Gärten jener mit dunklen Geheimnissen heim. Unabhängig von der Form nutzen die Pflanzen die unten genannten Werte."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W4 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Einschüchtern W6, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6","b":"6","pa":"6","ro":"6","sf":[["Klauen","Stä+W6."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furchtlos","Immun gegen Furcht und Einschüchtern."]]},{"n":"Verrückter Wissenschaftler","k":"Humanoide","w":1,"s":["HOR"],"p":146,"bk":"sw_hor","d":["Verrückte Wissenschaftler sind Genies, die es auf sich genommen haben, Gott zu spielen. Die Doktoren Frankenstein und Moreau sind gute Beispiele für diese wahnsinnigen Genies. Die meisten sind von ihren Schöpfungen umgeben, etwa Golems, Hybriden, Untoten oder anderen Konstrukten."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W12"],["Willenskraft","W10"]],"f":"Akademisches Wissen W10, Allgemeinwissen W8, Athletik W4, Einschüchtern W6, Heimlichkeit W6, Kämpfen W6, Naturwissenschaften W10, Okkultismus W8, Provozieren W6, Recherche W10, Reparieren W10, Verrückte Wissenschaft W12, Wahrnehmung W6, Überreden W4","b":"6","pa":"5","ro":"5","x":[["Handicaps","Wahnvorstellungen (Schwer — kann Leben erschaffen), Tick (Verschiedene), Stur"],["Talente","Arkaner Hintergrund (Verrückte Wissenschaft), Gelehrter (Naturwissenschaften)"],["Mächte","Geschoss (elektrischer Entlader), Elementarkontrolle (Blitz und Elektrizität), Schrumpfen (Verkleinerungsstrahl). Die Kräfte können je nach Interessengebieten des verrückten Wissenschaftlers variieren (Machtpunkte: 20)"],["Ausrüstung","Unterschiedlich, doch die meisten halten irgendeine Waffe griffbereit"]],"sf":[]},{"n":"Metallkoloss","k":"Konstrukte","w":0,"s":["HOR"],"p":147,"bk":"sw_hor","d":["Metallkoloss sind Konstrukte aus Metall und Maschinerie, durch die Kraft eines mächtigen Geistes verbunden. Sie sind am häufigsten auf modernen (und futuristischen) Schlachtfeldern, wo sie aus den Wracks von Kriegsmaschinen entstehen. Sich selbst überlassen, versuchen sie wahrscheinlich, sich in den Eingeweiden alter Fabriken oder Schrottplätze vor der Menschheit zu verstecken."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12"],["Stärke","W12+5"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W10, Einschüchtern W10, Kämpfen W10, Schießen W8, Wahrnehmung W6","b":"6","pa":"7","ro":"18 (4)","sf":[["Panzerung +4","Schwere Panzerung. Metallkörper."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Regeneration","Ein Metallkoloss neben einer großen Metallquelle (Größe eines Sportwagens oder mehr) kann als begrenzte freie Aktion einen natürlichen Heilungswurf ablegen, indem er Metallstücke auf seinen Körper zieht. Die SL entscheidet, ob die Quelle mehr als einmal genutzt werden kann."],["Größe 6 (Groß)","Metallkolosse sind so groß wie Panzer."],["Bewaffnung","Die Waffen eines Metallkolosses hängen von der Epoche seiner Entstehung ab, umfassen aber meist eine Hauptkanone und zwei kleinere, etwa eine 125-mm-Kanone und zwei Maschinengewehre Kaliber .50."]]},{"n":"Große Mumie","k":"Untote","w":1,"s":["HOR"],"p":148,"bk":"sw_hor","g":"Mumien (Horror)","d":["Große Mumien waren einst Hohepriester, Magier und korrupte Herrscher, absichtlich für die Ewigkeit konserviert und durch arkane Rituale mit überirdischem Leben begabt."],"a":[["Geschicklichkeit","W4"],["Konstitution","W12"],["Stärke","W12+4"],["Verstand","W10"],["Willenskraft","W12"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W6, Kämpfen W10, Wahrnehmung W8, Zaubern W10, Überreden W8","b":"4","pa":"7","ro":"13 (3)","x":[["Talente","Arkaner Hintergrund (Magie), Arkane Resistenz (Verb.)"],["Mächte","Barriere (Wand aus Dunkelheit), Geschoss (Schwarm winziger Schädel), Dunkelheit (Schattenbereich), Ablenkung (Schild aus wirbelnden Schädeln), Furcht (überirdischer Schrei), Zombie (rituelle Vorbereitung) (Machtpunkte: 30)"],["Ausrüstung","Antike Bronzerüstung (+3), Langschwert (Stä+W8)"]],"sf":[["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Große Mumien sind immun gegen Furcht und Einschüchtern."],["Festmahl","Große Mumien können zu einem nahezu echten Anschein des Lebens zurückkehren. Jedes Mal, wenn sie eine bestimmte Art Ziel töten (ihre natürlichen Feinde, jene, die sie erweckten, usw.), erlangen sie einen Teil ihres Aussehens im Leben zurück. Haben sie drei solcher Opfer getötet, sind sie keine „Mumien“ mehr und verursachen keine Furcht, erleiden keinen Feuerschaden, verursachen keine Mumienfäule und haben keinen Schlurfenden Gang. Alle anderen Kräfte behalten sie."],["Mumienfäule","Wer von einer Großen Mumie berührt wird und noch keine Mumienfäule hat, muss eine Konstitutionsprobe ablegen oder zieht sie sich zu – eine allgemeine Fäulnis des Fleisches und sofort eine Wunde. Opfer, die an „Mumienfäule“ sterben, können durch die Macht Zombie als Mumien zurückgebracht werden."],["Schlurfender Gang","Mumien würfeln wegen der Einschränkung durch ihre Wickel und ihr ausgetrocknetes Fleisch einen W4 als Sprintwürfel."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Feuer)","Mumien, die in trockene Lumpen gewickelt sind (oft mit brennbaren Chemikalien behandelt), erleiden +4 Schaden durch Feuer und sind sehr leicht entflammbar (siehe Feuer in Savage Worlds)."]]},{"n":"Wächtermumie","k":"Untote","w":0,"s":["HOR"],"p":149,"bk":"sw_hor","g":"Mumien (Horror)","d":["Diese Kreaturen waren einst Priester und Soldaten, die in Gräbern beigesetzt wurden, um ihre Herren für alle Ewigkeit zu bewachen."],"a":[["Geschicklichkeit","W4"],["Konstitution","W12"],["Stärke","W12+2"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Athletik W6, Einschüchtern W8, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6","b":"4","pa":"6","ro":"10","x":[["Talente","Arkane Resistenz"]],"sf":[["Furcht","Jeder, der eine Wächtermumie sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Mumien sind immun gegen Furcht und Einschüchtern, außer wenn Feuer im Spiel ist."],["Mumienfäule","Wer von einer Wächtermumie berührt wird und noch keine Mumienfäule hat, muss eine Konstitutionsprobe ablegen oder zieht sie sich zu – eine allgemeine Fäulnis des Fleisches und sofort eine Wunde. Opfer, die an „Mumienfäule“ sterben, können durch die Macht Zombie als Mumien zurückgebracht werden."],["Schlurfender Gang","Mumien würfeln einen W4 als Sprintwürfel."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Feuer)","Die beim Konservieren verwendeten Chemikalien bewirken, dass Mumien +4 Schaden durch Feuer erleiden und sehr leicht entflammbar sind (siehe Feuer in Savage Worlds)."]]},{"n":"Eis-/Sandmumie","k":"Untote","w":0,"s":["HOR"],"p":149,"bk":"sw_hor","g":"Mumien (Horror)","d":["Manche Mumien entstehen natürlich in sehr trockenen Umgebungen, wo der Leichnam gefriert oder von natürlich schützenden Elementen versiegelt wird.","Eis- und Sandmumien haben steinharte Haut, durchsetzt mit gefrorenem Wasser oder verkalkter Erde und Gewebe. Ihre Gliedmaßen sind verdreht und verformt, da ihr Fleisch schrumpfte und hart wurde."],"a":[["Geschicklichkeit","W4"],["Konstitution","W10"],["Stärke","W12"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W4, Einschüchtern W8, Heimlichkeit W8, Kämpfen W6, Wahrnehmung W6","b":"4","pa":"5","ro":"11 (2)","sf":[["Panzerung +2","Gehärtete Haut."],["Graben (Bewegungsweite 4)","Kann sich durch alles außer massivem Stein graben; kann unter der Erde nur durch besondere Mittel angegriffen werden."],["Furcht","Wer eine Eis- oder Sandmumie sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Mumien sind immun gegen Furcht und Einschüchtern."],["Schlurfender Gang","Mumien würfeln einen W4 als Sprintwürfel."],["Schmerzensberührung","Wer von einer Eis- oder Sandmumie berührt wird, muss eine Konstitutionsprobe ablegen oder erleidet Erschöpfung durch Erfrierungen (Eis) oder schreckliche Abschürfungen (Sand). Das kann nicht zum Tod führen."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Umwelt)","Eismumien brauchen eine eisige Umgebung und Sandmumien eine trockene. Für jede Stunde in warmen oder nassen Bedingungen müssen sie eine Konstitutionsprobe ablegen oder erleiden eine Stufe Erschöpfung. Führt das zum „Tod“, kehrt die Mumie in ihren reglosen Zustand zurück."]]},{"n":"Mutant","k":"Monster","w":0,"s":["HOR"],"p":150,"bk":"sw_hor","d":["Einst war er ein Mensch, doch Strahlung, eine außerirdische Infektion oder ein Industrieunfall veränderte seine Physiologie. Nun muss er töten, um zu leben, meist indem er lebenden Menschen eine entscheidende biologische Komponente raubt. Ein Mutant kann ein widerwilliger Mörder sein oder von seiner Mutation völlig in den Wahnsinn getrieben werden."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+1"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Diebeskunst W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6, Überreden W6","b":"6","pa":"6","ro":"8","x":[["Handicaps","Angewohnheit (Schwer — Mord)"],["Talente","Rohling"]],"sf":[["Biss/Klauen","Stä+W6."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Größe 1","Mutanten sind große, imposante Kreaturen."],["Schwäche (Sonnenlicht)","Mutanten sind Abgelenkt, solange sie direktem Sonnenlicht ausgesetzt sind."],["#","Variante Spezialfähigkeiten"],["","Ein einzigartiger Mutant ist eine Wildcard, doch manche Mutationen können eine ganze Bevölkerung oder die Bewohner eines Gebiets ergreifen. In diesen Fällen sind die Mutanten Statisten, vielleicht von einer mächtigeren Wildcard angeführt. Ein Mutant kann auch ein Serienmörder sein (S. 156) und andere Eigenschaften aus diesem Profil annehmen."],["Panzerung +4","Ein harter Panzer oder Chitin. Ein Gezielter Angriff mit –2 kann diese Panzerung ignorieren."],["Blutentzug","Gepackte Gegner müssen beim Packen und zu Beginn des Zugs der Kreatur, solange sie Gebunden oder Verstrickt bleiben, eine Konstitutionsprobe ablegen. Misslingt sie, erleiden sie Erschöpfung, die zum Tod führen kann."],["Gift (Tödlich)","Ein Ziel, das den Mutanten berührt oder von ihm berührt wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt, erleidet eine Wunde (zwei bei Kritischem Fehlschlag) und stirbt in 2W6 Runden. Ein strahlungssicherer Anzug blockiert diesen Effekt."]]},{"n":"Nagin","k":"Monster","w":0,"s":["HOR"],"p":150,"bk":"sw_hor","d":["Eine Nagin aus der indischen Folklore ist eine furchterregende Mischung aus dem Gesicht und Oberkörper einer menschlichen Frau mit den Augen, Zähnen, der Haut und dem Schwanz einer Giftschlange.","Unter normalen Umständen ist eine Nagin ein neutrales Wesen, das Menschen meidet, doch wenn man sie bedrängt, ist sie ein blutrünstiger Rachegeist.","Der gängigste Weg, den Groll einer Nagin zu wecken, ist, ihren Gefährten zu töten oder zu fangen. Eine gefährliche Schlange zu entfernen hat unvorhergesehene Folgen, wenn die Nagin beginnt, alle Beteiligten – und jeden, der ihr sonst in den Weg kommt – zu ermorden, bis ihre Rache gestillt oder sie anderweitig besänftigt ist."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W8"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Allgemeinwissen W4, Athletik W10, Darbietung W8, Heimlichkeit W10, Kämpfen W8, Provozieren W8, Wahrnehmung W6, Zaubern W10, Überreden W8","b":"6","pa":"6","ro":"7","x":[["Handicaps","Blutrünstig, Rachsüchtig (Schwer)"],["Talente","Arkaner Hintergrund (Magie), Kampfakrobat, Erstschlag (Verb.), Schnell, Sehr Attraktiv"],["Mächte","Tierfreund, Unsichtbarkeit, Gestaltwandel (Machtpunkte: 15)"]],"sf":[["Biss","Stä+W6."],["Tarnung","Wandelt eine Nagin mit Gestaltwandel in eine menschliche Frau oder eine Schlange, erhöht sich die Dauer auf Tage. Wird sie Erschüttert, Betäubt oder Verwundet, kehrt sie zu ihrer Standardgestalt zurück."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Gift (Tödlich)","Ein von einer Nagin gebissener und Erschütterter oder Verwundeter Charakter muss eine Konstitutionsprobe ablegen oder ist Betäubt, erleidet eine Wunde (zwei bei Kritischem Fehlschlag) und stirbt in 2W6 Runden."],["Regeneration (Schnell)","Natürlicher Heilungswurf jede Runde, außer bei Wunden durch versilberte Gegenstände."],["Wandkrabbler","Kann mit voller Bewegungsweite an senkrechten oder überhängenden Flächen laufen und darf rennen."]]},{"n":"Noppera-bo","k":"Monster","w":0,"s":["HOR"],"p":151,"bk":"sw_hor","d":["Noppera-bō sind Wesen der japanischen Legende. Sie sind gesichtslose Schrecken, die völlig menschlich aussehen, bis auf das erschreckende Fehlen eines Gesichts. Sie sind meist launische Wesen, die Freude daran haben, Menschen mit ihrem ungewöhnlichen Aussehen zu erschrecken. Andere Legenden sagen, die Gesichtslosen seien Monster, die Menschen töten und verzehren wollen. Obwohl ihnen Mund und Nase fehlen, können Noppera-bō normal sehen, sprechen und atmen. Noppera-bō erscheinen oft als schöne Frauen, die am Straßen- oder Wegesrand weinen und, wenn man sie anspricht, ihre glatten Gesichter zeigen und einen schrillen Klageschrei ausstoßen.","Noppera-bō können jede Art Ausrüstung oder Waffen nutzen, die ein normaler Mensch nutzen kann. Ein bewaffneter Noppera-bō nutzt sie defensiv und versucht zu fliehen, wenn er angegriffen wird."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W6, Heimlichkeit W8, Kämpfen W6, Provozieren W8, Schießen W6, Wahrnehmung W8, Überleben W6, Überreden W6","b":"6","pa":"5","ro":"6","x":[["Talente","Erniedrigen, Bedrohlich, Zurechtweisung, Starker Wille"]],"sf":[["Aura des Abscheus","Die Gegenwart eines Noppera-bō ist so unheimlich, dass schon sein Anblick oder seine Nähe Menschen beunruhigt. Jeder Angriff auf einen Noppera-bō erhält –2."],["Gesicht wegwischen","Manche Noppera-bō haben Gesichter und können sich normal in der menschlichen Gesellschaft bewegen. Als Trickser „wischen“ diese Noppera-bō gern mit den Händen oder einem Ärmel ihr Gesicht weg, um Menschen zu überraschen. Diese Aktion erhöht die Furchtprobe unten auf –2. Ein Noppera-bō kann das Gesicht einer bestimmten Person nicht nachahmen."],["Furcht","Wer das Gesicht (oder das Fehlen) eines Noppera-bō sieht, muss eine Furchtprobe ablegen."],["Unverwundbarkeit","Noppera-bō können durch nichtmagische Angriffe Erschüttert, aber nicht Verwundet werden."],["Hinterlistig","Noppera-bō sind Trickser und erhalten +2 auf Tests."]]},{"n":"Okkultist","k":"Humanoide","w":0,"s":["HOR"],"p":151,"bk":"sw_hor","d":["Je nach Setting kann ein Okkultforscher ein runzliger Weiser sein, der alte Wälzer zu Rate zieht, oder ein Oberschüler mit Zugang zu Teilen des Netzes, die andere fürchten. Gemeinsam ist ihnen allen tiefes Wissen über das Okkulte und die Fertigkeiten, mehr Informationen zu finden."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W12"],["Willenskraft","W10"]],"f":"Akademisches Wissen W6, Allgemeinwissen W8, Athletik W6, Heimlichkeit W6, Kämpfen W6, Okkultismus W12, Recherche W10, Wahrnehmung W8, Überreden W6","b":"6","pa":"5","ro":"5","x":[["Handicaps","Schlechte Augen (Leicht)"],["Talente","Beziehungen, Ermittler, Gelehrter (Okkultismus), Gassenwissen"],["Ausrüstung","Notizbuch, Stifte, Brille und eine Sammlung seltener Texte, Wälzer und gelegentlich sogar ein Grimoire"]],"sf":[]},{"n":"Regierungsagent","k":"Humanoide","w":0,"s":["HOR"],"p":151,"bk":"sw_hor","g":"Polizei","d":["Regierungsagenten, die in verschiedenen Rollen und Abteilungen dienen, sind verschwiegen, organisiert und der Mission ihrer Behörde verpflichtet.","Sie sind oft damit betraut, Berichte über übernatürliche Ereignisse zu untersuchen und darauf zu reagieren, und scheinen fast immer mehr zu wissen, als sie zugeben. Diese Behörden sind streng hierarchisch und abgeschottet, daher haben die meisten Agenten nur genug Arbeitswissen, um ihre Aufgaben zu erfüllen. Nur die Höchstrangigen kennen die ganze Wahrheit.","Diese „Men in Black“ tragen meist Anzüge und Sonnenbrillen – auch nachts – und führen eine Schusswaffe."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W8, Athletik W6, Einschüchtern W6, Fahren W6, Hacken W8, Heilen W6, Heimlichkeit W6, Kämpfen W6, Naturwissenschaften W4, Okkultismus W6, Recherche W8, Schießen W8, Wahrnehmung W8, Überleben W4, Überreden W6","b":"6","pa":"5","ro":"6","x":[["Handicaps","Loyal, Schwur (Schwer — die Wahrheit geheim halten)"],["Talente","Aufmerksamkeit, Anführer, Kühler Kopf, Starker Wille"],["Ausrüstung","Glock (Reichweite 12/24/48, Schaden 2W6, FR 1, PB 1), Mobiltelefon, Sonnenbrille, Taschenlampe"]],"sf":[]},{"n":"Polizeileutnant","k":"Humanoide","w":1,"s":["HOR"],"p":152,"bk":"sw_hor","g":"Polizei","d":["Auch wenn meist der Polizeichef die Entscheidungen trifft, sind es diese Beamten, die den Tagesbetrieb der Dienststelle leiten und in Krisen die Einsätze überwachen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W8, Fahren W10, Heimlichkeit W6, Kriegskunst W6, Kämpfen W8, Recherche W8, Schießen W8, Wahrnehmung W8, Überreden W6","b":"6","pa":"6","ro":"7 (2)","x":[["Handicaps","Loyal"],["Talente","Anführer, Ermittler"],["Ausrüstung","Kevlarweste (+2, –4 Schaden durch Schusswaffen), 9-mm-Pistole (Reichweite 12/24/48, Schaden 2W6, PB 1)"]],"sf":[]},{"n":"Streifenpolizisten","k":"Humanoide","w":0,"s":["HOR"],"p":152,"bk":"sw_hor","g":"Polizei","d":["Ob zu Fuß, im Streifenwagen oder auf Fahrrädern, die Streifenpolizisten sind das Fußvolk, das Tag für Tag in den Schützengräben das Verbrechen bekämpft."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W6, Einschüchtern W6, Fahren W8, Heimlichkeit W6, Kämpfen W8, Schießen W8, Wahrnehmung W6, Überreden W6","b":"6","pa":"6","ro":"7 (2)","x":[["Handicaps","Loyal"],["Talente","Ausweichen, Gassenwissen"],["Ausrüstung","Kevlarweste (+2, –4 Schaden durch Schusswaffen), 9-mm-Pistole (Reichweite 12/24/48, Schaden 2W6, PB 1), Schlagstock (Stä+W4)"]],"sf":[]},{"n":"Wachmann","k":"Humanoide","w":0,"s":["HOR"],"p":152,"bk":"sw_hor","g":"Polizei","d":["Auch wenn er kein Gesetzeshüter ist, ist der bescheidene Wachmann oft die erste Verteidigungslinie."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Allgemeinwissen W4, Athletik W6, Einschüchtern W4, Heimlichkeit W4, Kämpfen W6, Wahrnehmung W4, Überreden W6","b":"6","pa":"5","ro":"5","x":[["Handicaps","—"],["Talente","—"],["Ausrüstung","Kabelbinder, Taschenlampe, Walkie-Talkie"]],"sf":[]},{"n":"SWAT-Team","k":"Humanoide","w":0,"s":["HOR"],"p":152,"bk":"sw_hor","g":"Polizei","d":["Die meisten Dienststellen haben eine Gruppe Beamter in Bereitschaft für das Sondereinsatzkommando. Das sind hochausgebildete Beamte, oft ehemalige Soldaten, ausgerüstet für Terroristen oder schwer bewaffnete Kriminelle.","Außerhalb der Neuzeit könnte ein SEK (mit passenden Waffenänderungen natürlich) die Eliteeinheit der Obrigkeit darstellen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W8, Fahren W8, Heimlichkeit W6, Kämpfen W8, Schießen W8, Wahrnehmung W6, Überreden W6","b":"6","pa":"6","ro":"8 (2)","x":[["Handicaps","Loyal"],["Talente","Ausweichen, Meisterschütze, Volles Rohr!"],["Ausrüstung","Kevlarweste (+2, –4 Schaden durch Schusswaffen), 9-mm-Pistole (Reichweite 12/24/48, Schaden 2W6, PB 1), MP (Reichweite 12/24/48, Schaden 2W6, FR 3), Schlagstock (Stä+W4)"]],"sf":[]},{"n":"Tollwütiger Bär","k":"Tiere","w":0,"s":["HOR"],"p":153,"bk":"sw_hor","g":"Tollwütige Tiere","d":[],"a":[["Geschicklichkeit","W6"],["Konstitution","W12"],["Stärke","W12+3"],["Verstand","W6 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W8","b":"8","pa":"6","ro":"12","sf":[["Berserker","Ein tollwütiges Tier ist automatisch Berserker (wie das Talent). Die Werte oben enthalten bereits die Modifikatoren auf Stärke und Robustheit durch Berserker."],["Biss/Klauen","Stä+W6."],["Furchtlos","Immun gegen Furcht und Einschüchtern, außer wenn Wasser im Spiel ist (siehe Schwäche unten)."],["Ansteckung (-2)","Ein von einem Biss Erschütterter oder Verwundeter Charakter muss eine Konstitutionsprobe mit –2 ablegen. Misslingt sie, erkrankt das Opfer an Tollwut. Es erleidet jeden Tag eine Stufe Erschöpfung bis zum Tod. Eine erfolgreiche Heilen-Probe kann die Krankheit behandeln, muss aber binnen 24 Stunden erfolgen, und der Heiler muss Zugang zum Impfstoff haben."],["Größe 2","Diese Kreaturen sind bis zu 2,4 m groß und wiegen über 450 kg."],["Schwäche (Wasser)","Ein seltsames Symptom der Tollwut ist Hydrophobie durch unwillkürlichen Schluckreflex. Die Kreatur ist Abgelenkt, wenn sich ein Gewässer größer als eine Tränke innerhalb von 5“ (10 m) befindet."]]},{"n":"Rake","k":"Monster","w":0,"s":["HOR"],"p":153,"bk":"sw_hor","d":["Rakes sind blasse, haarlose Kreaturen, die in tiefen Höhlen und dunklen Wäldern hausen. Sie sind humanoid, aber unnatürlich dünn, Rippen und Wirbel zeichnen sich unter der Haut ab. Ihre Arme und Beine sind länger als bei einem vergleichbar großen Menschen und mit schwarzen, schmutzigen Klauen besetzt. Ihre Finger und Zehen haben ein zusätzliches Gelenk, was ihnen einen kräftigen Griff verleiht.","Das Gesicht eines Rakes ist nur vage menschlich, mit dunklen, eingesunkenen Augen, flachen Nasen und Mäulern voller gelber Fangzähne. Sie können auf zwei Beinen gehen, fallen aber zum Rennen auf alle Viere. Rakes sind wilde Räuber, die alles töten, was sie finden, und die Körper in ihren Bau schleppen, um sie zu fressen.","Rakes sind auch als Kriecher, Fleischgänger oder (fälschlich) Skinwalker und Wendigos bekannt."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W10"],["Verstand","W8 (A)"],["Willenskraft","W6"]],"f":"Athletik W10, Einschüchtern W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8, Überleben W8","b":"10","pa":"6","ro":"8","sf":[["Biss/Klauen","Stä+W6, PB 2. Rakes haben extrem scharfe Zähne und Klauen."],["Greifende Hände","+2 auf Athletik- und Stärkeproben für Ringen."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Bewegungsweite","Rakes sind unmenschlich schnell. Sie haben Bewegungsweite 10 und einen W8 als Sprintwürfel."],["Widerstandsfähig","Rake-Statisten können eine Wunde einstecken, bevor sie Ausgeschaltet werden."],["Größe 1","Rakes sind groß, aber hager. Sie sind etwa 2,4 m groß, wiegen aber nur 90 kg."],["Heulen","Ein Rake kann ein überirdisches Heulen ausstoßen, das alle Hörer in Schrecken versetzt. Als begrenzte Aktion kann er eine Einschüchtern-Probe in einer Kegelschablone ablegen. Alle Ziele darin sind betroffen und widerstehen einzeln."],["Wandkrabbler","Rakes können senkrechte oder überhängende Flächen mit voller Bewegungsweite erklimmen und dürfen sprinten."],["#","Variante Spezialfähigkeiten"],["Blind","Manche Rakes sind blind, können aber per Echoortung „sehen“ und sind immun gegen sichtbasierte Effekte (Dunkelheit, Unsichtbarkeit usw.)."],["Nachahmen","Der Rake kann Geräusche und Stimmen nachahmen."]]},{"n":"Rokurokubi","k":"Monster","w":0,"s":["HOR"],"p":153,"bk":"sw_hor","d":["Rokurokubi sehen tagsüber aus und verhalten sich wie Menschen. Nachts schläft der Körper, und der Kopf löst sich und rollt oder fliegt auf der Suche nach Blut umher. Manche Rokurokubi haben einen auffälligen Schlitz quer über der Kehle, den sie mit Schals oder hohen Kragen verbergen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W8, Heimlichkeit W10, Kämpfen W6, Provozieren W8, Wahrnehmung W8, Überreden W6","b":"2","pa":"5","ro":"4","sf":[["Biss","Stä+W4, Zerreißen."],["Furcht","Wer die vom Körper getrennte Kreatur sieht, muss eine Furchtprobe ablegen, mit –2, wenn er die Trennung tatsächlich sieht!"],["Flug","Bewegungsweite 6."],["Unverwundbarkeit","Solange der Kopf eines Rokurokubi an seinem Körper sitzt, Erschüttert Schaden irgendwo außer am Kopf die Kreatur nur. Zielen auf den Kopf verursacht normalen Schaden, aber ohne den üblichen +4 Schaden."],["Größe -3 (Sehr klein)","Rokurokubi sind so groß wie ein menschlicher Kopf."],["Schwäche (Körper)","Der Kopf eines Rokurokubi muss vor Sonnenaufgang zu seinem Körper zurückkehren – oder zumindest zu einem Körper. Erkennt das listige Wesen, dass an seinem Körper manipuliert oder er zerstört wurde, kann es sich an jeden kopflosen Leichnam heften, den es findet oder schafft. Wird der Hals des Körpers mit Wachs oder Metall versiegelt, wird der Kopf beim Versuch des Wiederanheftens zerstört."],["#","Variante Spezialfähigkeiten"],["Reichweite 4","Manche Arten von Rokurokubi haben lange, dehnbare Hälse statt abnehmbarer Köpfe. Diese Variante bleibt furchterregend, gilt aber allgemein als harmloser."],["Zaubern","Die gefährlichsten Rokurokubi kennen üble Magie. Sie erhalten das Talent Arkaner Hintergrund (Magie), Zaubern W10, die Mächte Verwirrung, Verkleidung, Illusion, Gedächtnis löschen, Marionette und Schlummer sowie 25 Machtpunkte."]]},{"n":"Teppichunhold","k":"Monster","w":0,"s":["HOR"],"p":154,"bk":"sw_hor","d":["Tierfellteppiche sind nur die Häute toter Tiere, doch einige behalten den Geist der Bestie. Teppichunholde haben weder Fleisch noch Knochen, sind aber dennoch gefährlich für ahnungslose Eindringlinge. Die Version unten ist ein Tigerfellteppich, doch es gibt andere Arten auf den Böden der Jäger, die sie erlegten."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12"],["Stärke","W12"],["Verstand","W6 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W8","b":"4","pa":"7","ro":"9","x":[["Talente","Raserei (Verb.)"]],"sf":[["Biss/Klauen","Stä+W6."],["Tarnung","Ein ruhender Teppichunhold sieht aus wie ein gewöhnlicher Teppich. Bewegt sich ein Gegner neben den Teppich, ohne seine böse Natur zu erkennen, erhält der Teppich Der Überraschungsangriff."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Größe 1","Teppichunholde sind größer als Menschen, wenn auch flach."]]},{"n":"Sasquatch","k":"Monster","w":0,"s":["HOR"],"p":154,"bk":"sw_hor","d":["Fast jeder Kontinent kennt eine Legende von einem riesigen humanoiden Wesen in seinen abgelegensten Regionen. Sasquatch ähneln einer Kreuzung aus Mensch und Affe, sind 2,4 m groß oder mehr, mit breiten Schultern und kräftigen Armen und Beinen. Sie sind in ihrem heimischen Gelände äußerst heimlich und werden von Vorbeikommenden selten gesehen. Sasquatch bleiben gern für sich und sind meist friedlich. Sie vertreiben Eindringlinge oft aus ihrem Revier, indem sie gespenstische Schreie und Heulen ausstoßen, mit großen Ästen gegen Bäume schlagen und Steine werfen.","Manche Sasquatch übernehmen die Rolle eines Beschützers ihres Reichs, helfen sogar verirrten Wanderern und schikanieren jene, die die Natur verwüsten wollen.","In den Vereinigten Staaten heißen sie Sasquatch, Bigfoot, Ohio Grassman und Florida Skunk Ape. Im Himalaya sind sie der Yeti. In Australien heißt der Name Yowie."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+3"],["Verstand","W10 (A)"],["Willenskraft","W10"]],"f":"Athletik W10, Einschüchtern W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8, Überleben W10","b":"8","pa":"6","ro":"10","x":[["Talente","Kräftig, Rohling"],["Ausrüstung","Astkeule (Stä+W8), Stein (Reichweite 4/8/16, Stä+W6)"]],"sf":[["Faust","Stä+W6."],["Waldspuk","Sasquatch können mit ihrem Waldzuhause verschmelzen. Sie erhalten +4 auf Heimlichkeit in bewaldetem Gelände. (Ändere dies für Sasquatch aus anderen Biomen auf den passenden Geländetyp.)"],["Größe 3","Sasquatch sind über 2,7 m groß und wiegen 360 kg."],["#","Variante Spezialfähigkeiten"],["Mystische Kräfte","Manche Sasquatch haben Mystische Kräfte (siehe S. 11). Sie haben die folgenden Mächte: Tierfreund, Eigenschaft steigern (nur auf sich selbst), Verwirrung, Empathie, Umweltschutz, Furcht. Machtpunkte: 15."]]},{"n":"Unheilvolle Vogelscheuche","k":"Konstrukte","w":0,"s":["HOR"],"p":155,"bk":"sw_hor","d":["Kürbis-Jack ist wahrscheinlich die berühmteste üble Vogelscheuche, aber nicht die einzige ihrer Art. Üble Vogelscheuchen werden meist von bösen Geistern erweckt, manchmal aber auch durch vergossenes Blut. Alte Schlachtfelder, die nun landwirtschaftlich genutzt werden, sind gute Kandidaten."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W10, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W6","b":"6","pa":"6","ro":"6","x":[["Talente","Rundumschlag (Verb.)"],["Ausrüstung","Sense (Stä+W10, –1 Parade, erfordert zwei Hände)"]],"sf":[["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Schwäche (Feuer)","Üble Vogelscheuchen erleiden +4 Schaden durch Feuerangriffe und gelten als sehr leicht entflammbares Material."]]},{"n":"Schreiender Schädel","k":"Konstrukte","w":0,"s":["HOR"],"p":155,"bk":"sw_hor","d":["Schreiende Schädel sind menschliche Schädel, denen durch arkane Rituale begrenzter Intellekt verliehen wurde. Sie dienen vor allem als Spione, können sich aber verteidigen, wenn sie angegriffen werden."],"a":[["Geschicklichkeit","W4"],["Konstitution","W6"],["Stärke","W4"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W4, Einschüchtern W8, Heimlichkeit W6, Kämpfen W6, Provozieren W8, Wahrnehmung W10","b":"—","pa":"5","ro":"4","sf":[["Flug","Bewegungsweite 6."],["Headbangen","Stä+W4."],["Schrei","Der Schädel kann ein überirdisches Kreischen ausstoßen, das alle Hörer in Schrecken versetzt. Als begrenzte Aktion kann der schreiende Schädel eine Einschüchtern-Probe in einer Kegelschablone ablegen. Alle Ziele darin sind betroffen und widerstehen einzeln."],["Geteilte Sinne","Der Schöpfer eines schreienden Schädels kann dessen Sinne wie seine eigenen nutzen, ist dabei aber Abgelenkt."],["Größe -3 (Sehr klein)","Schreiende Schädel sind so groß wie ein menschlicher Kopf."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Seetangunhold","k":"Monster","w":0,"s":["HOR"],"p":155,"bk":"sw_hor","d":["Das Meer ist ein geheimnisvoller Ort, dessen Tiefen vom Menschen kaum erforscht sind, mit unbekannten Schrecken unter den Wellen. Seetangunholde können natürliche Kreaturen sein, Ergebnis von Magie oder Nebenprodukte chemischer Verschmutzung. Die schwarzen, schleimigen Gestalten der Unholde enthalten oft verrottendes Meeresleben, und ihre Augen glühen in unheilvollem Gelb."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W10"],["Verstand","W4"],["Willenskraft","W8"]],"f":"Athletik W6, Einschüchtern W6, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W6","b":"4","pa":"6","ro":"6","sf":[["Wasserwesen","Bewegungsweite 8."],["Klauen","Stä+W4 (geformt aus scharfen Fischgräten oder gesplittertem Holz)."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Immunität (Feuer)","Feuerangriffe verursachen ihren schleimigen Körpern keinen Schaden."],["Gestank","Das erste Mal, wenn sich jemand neben einen Seetangunhold bewegt, wird er von Übelkeit übermannt und Abgelenkt."]]},{"n":"Wahnsinniger Serienmörder","k":"Humanoide","w":1,"s":["HOR"],"p":156,"bk":"sw_hor","g":"Serienmörder","d":["Manche Mörder sind nichts als blutdürstige sterbliche Menschen. Derselbe Wahnsinn, der sie zum Töten treibt, verleiht ihnen erstaunliche Stärke und Zähigkeit."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W10, Fahren W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8, Überreden W4","b":"6","pa":"6","ro":"8","x":[["Handicaps","Blutrünstig, Fies, Rachsüchtig (Schwer)"],["Talente","Berserker, Kräftig, Erstschlag, Raserei, Wirklich schwer zu töten, Bedrohlich, Nerven aus Stahl (Verb.), Rundumschlag, Lieblingswaffe"],["Ausrüstung","Unterschiedlich, kann aber eine Markenzeichen-Waffe wie eine Kettensäge (Schaden 2W6+4, Kritischer Fehlschlag trifft den Anwender) oder eine Lieblingsaxt (Stä+W6) umfassen"]],"sf":[["Furchtlos","Immun gegen Furcht und Einschüchtern."]]},{"n":"Übernatürlicher Serienmörder","k":"Humanoide","w":1,"s":["HOR"],"p":156,"bk":"sw_hor","g":"Serienmörder","d":["Die schlimmsten Serienmörder schaffen es irgendwie, aus der Hölle zurückzukehren, um erneut zu töten. Sie erlangen übernatürliche Kräfte entsprechend ihren grauenvollen Taten. Sie existieren nur, um die blutige Schreckensherrschaft fortzusetzen, die mit ihrem sterblichen Leben hätte enden sollen.","Das Beispiel unten tötete Opfer rund um ein Skigebiet mit einer Eispickelaxt und setzt nun seinen Mordzug fort. Siehe Varianten-Spezialfähigkeiten für weitere Ideen für Übernatürliche Serienmörder."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12+2"],["Verstand","W6"],["Willenskraft","W12"]],"f":"Athletik W10, Einschüchtern W12, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W8","b":"6","pa":"7","ro":"11","x":[["Handicaps","Blutrünstig, Fies, Rachsüchtig (Schwer)"],["Talente","Berserker, Kräftig, Erstschlag, Raserei, Wirklich schwer zu töten, Bedrohlich, Nerven aus Stahl (Verb.), Rundumschlag, Lieblingswaffe (Eisaxt)"],["Ausrüstung","Eisaxt (Stä+W6), Skimaske, Skijacke"]],"sf":[["Wetter kontrollieren","Der Mörder kann sich 10 Minuten konzentrieren, um einen Blizzard in einem Radius von zwei Meilen heraufzubeschwören. Das erzeugt im ganzen Gebiet Dämmerlicht und extreme Kälte."],["Furcht","Wer den Mörder sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern, außer wenn Wasser im Spiel ist (siehe Schwächen unten)."],["Immunität (Kälte)","Der Mörder ist immun gegen Kälte und kältebasierte Angriffe."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Wasser)","Als er sterblich war, ertrank der Eismann in einem Whirlpool. Er ist Abgelenkt innerhalb von 5“ (10 m) von Wasser, das tiefer als einen Meter ist. Wird er erneut im Wasser getötet, ist sein Amoklauf für immer beendet."],["#","Variante Spezialfähigkeiten"],["Traummörder","Wie in den Nightmare-on-Elm-Street-Filmen hat der Mörder die einzigartige Fähigkeit, schlafende Opfer in seine Albträume zu ziehen – sogar als Gruppe. Behandle das Traumreich wie die reale Welt, vielleicht mit beliebigen bizarren Regeln (so kann es in einer albtraumhaften Raumstation keine Schwerkraft geben). Der Mörder ist im Traumreich wahrscheinlich weit mächtiger als in der realen Welt und kann vielleicht teleportieren, Kreaturen und andere Bedrohungen erschaffen usw. Wie auch immer die Einzelheiten, der Mörder muss den Willen des Opfers über Bedrohungen „angreifen“ – er kann es nie einfach töten."],["Unverwundbar","„Getötete“ Serienmörder verschwinden einfach für ein paar Nächte und beginnen dann erneut zu morden. Das sollte stets mit einer Schwäche gekoppelt werden, die seinen Hintergrund widerspiegelt."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Zerreißen","Serienmörder mit gezackten Klingen oder anderen seltsamen Waffen können Zerreißen-Schaden verursachen."],["Teleportation","Serienmörder haben die unheimliche Fähigkeit, aus dem Blickfeld zu verschwinden und dann wieder aufzutauchen, wenn man es am wenigsten erwartet. Solange niemand den Mörder ansieht (und er nicht Erschüttert, Betäubt, Verstrickt oder Gebunden ist), kann er verschwinden und erscheinen, wenn es dramatisch passt. Das ist für den Serienmörder eine begrenzte freie Aktion."],["Unaufhaltsam","Erleidet pro schadenverursachendem Angriff maximal eine Wunde (nach Wurf auf Schaden wegstecken), es sei denn, die Aktionskarte des Angreifers ist ein Joker."],["Schwäche (Besonderes)","Der Mörder ist durch etwas gebannt (S. 48), das ihn im Leben tötete oder mit seiner einzigartigen Geschichte verbunden ist. In Freitag der 13. Teil 2 wurde der Mörder gestoppt, als jemand die Kleidung der einzigen Person anzog, die er wirklich fürchtete – seiner toten Mutter!"]]},{"n":"Schattenmörder","k":"Geister","w":0,"s":["HOR"],"p":157,"bk":"sw_hor","d":["Diese schleichenden Schatten lauern in flackerndem Licht oder dunklen Räumen. Der Schatten ist eine menschliche Silhouette mit einem Messer. Die Gestalt ist meist unscharf, doch in manchen Fällen lassen sich mit einer erfolgreichen Wahrnehmungsprobe Einzelheiten des Abbilds einer bestimmten Person erkennen. Die geisterhafte Gestalt ist auf Mord aus. Sie greift den Schatten des Ziels an, als stünde ein echter Mörder hinter der echten Person. Die Trugangriffe fühlen sich für das Opfer nur allzu real an."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W8, Einschüchtern W8, Heimlichkeit W12, Kämpfen W8, Wahrnehmung W8","b":"6","pa":"6","ro":"6","x":[["Handicaps","Stumm"],["Talente","Assassine"],["Ausrüstung","Messer (Stä+W4)"]],"sf":[["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht","Wer einen Schattenmörder sieht, muss eine Furchtprobe ablegen."],["Schattengriff","Schattenmörder greifen Menschen zunächst nicht direkt an, sondern gehen auf den Schatten des Ziels los. Das ist ein Berührungsangriff, der das Ziel bei Erfolg Verstrickt und bei einer Steigerung Gebunden macht. Einmal gepackt, spürt das Ziel die Berührung des Schattenmörders, der es festhält, und kann sich normal zu befreien versuchen."],["Schattenstich","Solange ein Schattenmörder ein Ziel Verstrickt oder Gebunden hält, kann er es mit seinem Messer erstechen. In Stockdunkelheit (–6) kann der Schattenmörder Ziele mit seinem Messer angreifen, ohne vorher packen zu müssen."],["Schwäche (Licht)","Ist eine Lichtquelle weich und flach genug, um Schatten zu minimieren, muss ein Schattenmörder sich in einen schwächer beleuchteten Bereich oder völlige Dunkelheit zurückziehen. Ein Held kann mit einem Athletik-Wurf eine gerichtete Lichtquelle direkt auf einen Schattenmörder richten. Bei Erfolg ist der Schattenmörder Abgelenkt, bei einer Steigerung Betäubt."]]},{"n":"Skelettreitpferd","k":"Untote","w":0,"s":["HOR"],"p":158,"bk":"sw_hor","g":"Skelett-Tiere","d":["Skelettpferde dienen Nekromanten und Dämonen als Reittiere, wenn sie die sterbliche Welt besuchen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W12"],["Verstand","W4 (A)"],["Willenskraft","W4"]],"f":"Athletik W8, Kämpfen W8, Wahrnehmung W6","b":"10","pa":"6","ro":"10","x":[["Talente","Flink"]],"sf":[["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Tritt","Stä+W6."],["Größe 2","Skelettpferde sind größer als ein Mensch, und die Knochen wiegen bis zu 225 kg."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Skelett-T-Rex","k":"Untote","w":1,"s":["HOR"],"p":158,"bk":"sw_hor","g":"Skelett-Tiere","d":["Der „König der Dinosaurier“ war zweifellos ein furchterregendes Wesen, als er die Erde durchstreifte. Als Skelettkreatur ist er noch furchteinflößender."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W12+6"],["Verstand","W4 (A)"],["Willenskraft","W8"]],"f":"Athletik W8, Einschüchtern W12, Kämpfen W8, Wahrnehmung W8","b":"10","pa":"6","ro":"17 (2)","x":[["Talente","Flink"]],"sf":[["Panzerung +2","Fossilisierter Knochen."],["Biss","Stä+W8; 2."],["Furcht (-2)","Wer ein Skelett-T-Rex sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Größe 7 (Groß)","Diese furchterregenden Kreaturen sind 9 m hoch, und die Knochen wiegen über 9 Tonnen."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Skelett","k":"Untote","w":0,"s":["HOR"],"p":158,"bk":"sw_hor","d":["Bei diesen auferstandenen Toten ist die Haut bereits verrottet, was sie etwas schneller macht als ihre fleischbehafteten Zombie-Gegenstücke. Man findet sie oft klappernd in den Legionen übler Nekromanten."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4"],["Willenskraft","W4"]],"f":"Athletik W6, Einschüchtern W6, Kämpfen W6, Schießen W6, Wahrnehmung W4","b":"7","pa":"5","ro":"7","x":[["Ausrüstung","Unterschiedlich"]],"sf":[["Klauen","Stä+W4."],["Furchtlos","Skelette sind immun gegen Furcht und Einschüchtern."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Skelettkrieger","k":"Untote","w":0,"s":["HOR"],"p":158,"bk":"sw_hor","d":["Skelettkrieger sind die wiedererweckten Knochen längst verstorbener Soldaten. Anders als gewöhnliche Skelette behalten diese untoten Truppen mehr ihrer Kampffertigkeiten und sind mit funktionsfähigen, wenn auch etwas alten Waffen ausgerüstet."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4"],["Willenskraft","W4"]],"f":"Athletik W6, Einschüchtern W8, Kämpfen W8, Schießen W6, Wahrnehmung W4","b":"7","pa":"6","ro":"10 (3)","x":[["Ausrüstung","Bronzebrustplatte (+3), Bronzeschwert (Stä+W8)"]],"sf":[["Klauen","Stä+W4."],["Furchtlos","Skelette sind immun gegen Furcht und Einschüchtern."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Häuter","k":"Monster","w":0,"s":["HOR"],"p":159,"bk":"sw_hor","d":["Häuter sind winzige, fleischfressende Humanoide mit einem Faible für Menschenfleisch. Sie leben nur von Haut und lassen den Rest ihrer Mahlzeit zerfetzt und blutig zurück. Sie sind für ihre Größe unglaublich stark und wild und besitzen bösartige tierische Schläue.","Häuter leben in großen Kolonien unter der Erde und wagen sich nur nachts oder bei Stürmen an die Oberfläche. Einzelne Kreaturen erkunden zuerst das Gebiet und kehren dann als Teil einer ausgehungerten Horde von 2W6 Kreaturen zurück, mit weiteren in der Nähe."],"a":[["Geschicklichkeit","W10"],["Konstitution","W6"],["Stärke","W8"],["Verstand","W6 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8","b":"6","pa":"6","ro":"2","x":[["Talente","Ausweichen, Schnell"]],"sf":[["Biss/Klauen","Stä+W4."],["Furcht","Wer einem Häuter begegnet, muss eine Furchtprobe ablegen."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Zerfetzen","Wunden, die die Kreatur verursacht, zählen stets so, als wäre die Goldene Stunde abgelaufen."],["Größe -3 (Sehr klein)","Häuter sind knapp unter 30 cm groß."],["Schwäche (Sonnenlicht)","Häuter sind Abgelenkt, solange sie direktem Sonnenlicht ausgesetzt sind."]]},{"n":"Slender Man","k":"Geister","w":1,"s":["HOR"],"p":159,"bk":"sw_hor","d":["Ein Slender Man ist ein hageres, gesichtsloses Wesen, das seine Opfer langsam und unerbittlich verfolgt. Es bevorzugt verwundbare Beute und jagt daher meist einsame Wanderer, Alte oder Kinder.","Sie ähneln großen, unmenschlich dürren Menschen mit glatten, haarlosen Köpfen. Sie sprechen nie und geben keinen Laut von sich. Sie greifen andere an, die sich zwischen sie und ihre Beute stellen, konzentrieren sich sonst aber ausschließlich auf ihre auserwählten Opfer.","Slender Men genießen den Geschmack von Furcht. Sie lassen sich in den vier Nächten vor dem endgültigen Zuschlagen kurz und im Schatten sehen. Das erfüllt ihr Ziel mit Furcht und macht es zu einem köstlichen Festmahl."],"a":[["Geschicklichkeit","W12"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W8, Heimlichkeit W12, Kämpfen W10, Psionik W10, Wahrnehmung W8","b":"6","pa":"7","ro":"10","x":[["Mächte","Blenden, Verwirrung, Fluch, Dunkelheit, Ablenkung, Furcht, Chaos, Unsichtbarkeit, Aufspüren, Albträume, Trägheit, Betäubung, Teleportation, Wandläufer (Machtpunkte: 20)"]],"sf":[["Aura des Wahnsinns","Die Nähe eines Slender Man, ob man ihn sieht oder nicht, treibt einen Menschen langsam in den Wahnsinn. Wer in eine Große Flächenschablone um einen Slender Man gerät, muss eine Furchtprobe ablegen (auch ohne ihn zu sehen). Bei Misserfolg erhält er eine Leichte Psychose (S. 43), bei Kritischem Fehlschlag eine Schwere Psychose."],["Furcht (-2)","Wer einen Slender Man sieht, muss eine Furchtprobe mit –2 ablegen."],["Furcht auslösen","Jede Nacht, in der sich ein Slender Man seiner Beute zeigt, erhält diese –1 auf alle Furchtproben (bis maximal –4). Das legt sich erst, wenn der Slender Man (oder die Slender Men) getötet wird."],["Unverwundbarkeit","Slender Men können durch nichtmagische Angriffe Erschüttert, aber nicht Verwundet werden."],["Größe 1","Slender Men sind 2,4 m groß und wiegen 135 kg."],["Teleportation","Als begrenzte freie Aktion kann ein Slender Man 24“ (48 m) teleportieren."],["Ranken","Slender Men können vier lange, schwarze Tentakel aus dem Rücken wachsen lassen, mit denen sie angreifen. Sie haben zwei Tentakelaktionen, Reichweite 2 und verursachen Stä+W6 Schaden."],["Zäh","Slender Men haben +2 Robustheit."]]},{"n":"Smogwolke","k":"Monster","w":0,"s":["HOR"],"p":160,"bk":"sw_hor","d":["Smogwolken in dunklen Welten erlangen manchmal boshaftes Bewusstsein. Diese dunstigen Wesen aus verschmutzter Luft können gegen den Wind treiben, ähneln sonst aber schmutzigen, schwarzen Wolken. Manche zeigen gelegentlich kohlschwarze Augen, die aber kaum zu erkennen sind."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W6"],["Verstand","W4"],["Willenskraft","W8"]],"f":"Heimlichkeit W10, Wahrnehmung W6","b":"—","pa":"2","ro":"8","sf":[["Ersticken","Eine Smogwolke füllt eine Große Flächenschablone. Jede Kreatur in der Schablone muss jede Runde eine Konstitutionsprobe ablegen (+2, wenn Mund und Nase bedeckt sind) oder erleidet eine Stufe Erschöpfung."],["Elementar","Kein zusätzlicher Schaden durch Gezielte Angriffe; ignoriert 1 Punkt Wundabzüge; atmet nicht, immun gegen Krankheit und Gift."],["Flug","Bewegungsweite 12."],["Gasform","Smogwolken ignorieren die meisten körperlichen Angriffe. Flächenwaffen und übernatürliche Kräfte wirken normal auf sie. Sie können für 2W6 Runden vertrieben werden, etwa indem man sie in einen Lüftungsschacht saugt oder mit starkem Wind wegbläst."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."]]},{"n":"Speerfinger","k":"Monster","w":1,"s":["HOR"],"p":160,"bk":"sw_hor","d":["Speerfinger sind furchterregende weibliche Oger aus der Cherokee-Legende. Die ursprüngliche Speerfinger hieß U’tlun’ta. Speerfinger haben steinartige Haut, die nahezu undurchdringlich ist. Der Zeigefinger ihrer rechten Hand ist 60 cm lang und endet in einer scharfen steinernen Spitze wie ein Obsidianmesser. Sie kann diesen Finger als Waffe nutzen, um ihre Gegner aufzuschlitzen und zu durchbohren. Speerfinger sind auch Gestaltwandler und können eine scheinbar harmlose Gestalt annehmen, etwa eine alte Frau oder einen vertrauten Verbündeten."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+3"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Einschüchtern W8, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6","b":"8","pa":"6","ro":"15 (4)","x":[["Talente","Kräftig, Rohling"],["Ausrüstung","Felsbrocken (Reichweite 4/8/16, Schaden Stä+W8)"]],"sf":[["Panzerung +4","Felsharte Haut."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Aufspießen","Eine Steigerung auf den Kämpfen-Wurf der Speerfinger spießt ihren Feind auf ihren langen Finger auf und Verstrickt ihn, als wäre er gepackt."],["Gestaltwandel","Eine Speerfinger kann als begrenzte Aktion menschliche Gestalt annehmen. In dieser Gestalt hat sie Größe 0 und kann ihren speerartigen Finger nicht nutzen. Ihre Stärke ist W10 und ihre Robustheit 12 (4). Sie kann diese Gestalt unbegrenzt halten, kehrt aber sofort zu ihrer Standardgestalt zurück, wenn sie Erschüttert, Betäubt oder Verwundet wird. Sie kann nicht freiwillig zur Ogergestalt zurückkehren, solange ein Mensch sie beobachtet."],["Größe 4 (Groß)","Speerfinger ist 4,8 m groß und wiegt 900 kg."],["Speerfinger","Stä+W8, 4."],["Schwäche (Handfläche)","Der einzige Schwachpunkt einer Speerfinger ist die Handfläche ihrer rechten Hand. Gezielte Angriffe auf ihren Schwachpunkt erhalten –6. Bei Erfolg ignorieren sie ihre Panzerung und verursachen +4 Schaden. Wenn sie nicht angreift, hält sie die rechte Hand fest geballt; man muss auf Halten gehen und sie während ihres Angriffs unterbrechen, um eine Chance auf die Schwachstelle zu bekommen."]]},{"n":"Kolossalspinne","k":"Tiere","w":0,"s":["HOR"],"p":160,"bk":"sw_hor","d":["Winzige Spinnen sind schlimm genug, doch Spinnentiere, die größer als Menschen sind, sind der Stoff von Albträumen. Wie ihre kleineren Verwandten haben Kolossalspinnen acht Beine, einen haarigen Körper und tödliche Kieferklauen.","Die Netze, die diese Riesen spinnen, können Menschen und größere Beute verstricken. Die Spinnen werden von den Vibrationen zappelnder Beute angelockt und trinken das Blut gefangener Opfer, bevor sie entkommen können."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W12+6"],["Verstand","W4 (A)"],["Willenskraft","W10"]],"f":"Athletik W10, Heimlichkeit W8, Kämpfen W10, Schießen W8, Wahrnehmung W8","b":"8","pa":"7","ro":"11","x":[["Talente","Flink, Schnell"]],"sf":[["Biss","Stä+W6."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Größe 4 (Groß)","Kolossalspinnen sind bis zu 4,5 m lang und wiegen über eine Tonne."],["Wandkrabbler","Kann mit voller Bewegungsweite an senkrechten oder überhängenden Flächen laufen und darf rennen."],["Netze","Kann Netze verschießen mit einem Schießen-Wurf und Reichweite 3/6/12. Ziele in einer Mittleren Flächenschablone sind Verstrickt, bei einer Steigerung Gebunden (siehe Savage Worlds). Kann durch Ausweichen vermieden werden."],["#","Variante Spezialfähigkeiten"],["","Spinnen gibt es in Hunderten von Arten. Manche graben unter der Erde und lauern der Beute auf, statt Netzfallen zu spinnen. Viele triefen vor Gift, entweder um ihre Beute sofort zu töten oder sie zu lähmen, damit sie später lebendig gefressen werden kann."],["Panzerung +4","Haariger Chitinpanzer."],["Graben (Bewegungsweite 8)","Kann sich durch alles außer massivem Stein graben; kann unter der Erde nur durch besondere Mittel angegriffen werden."],["Lähmung","Wer vom Biss der Spinne Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er für 2W6 Runden gelähmt und zu keiner Aktion fähig – nicht einmal zum Sprechen. (Manche Spinnen können stattdessen Tödliches Gift haben.)"],["Anspringen","Addiere +4 statt +2 auf den Schaden bei einem Rücksichtslosen Angriff."]]},{"n":"Plüschtier-Unhold","k":"Konstrukte","w":0,"s":["HOR"],"p":161,"bk":"sw_hor","d":["Ausgestopfte Tiere sind keine flauschigen Spielzeuge, sondern belebte Tierhäute. Anders als Teppichunholde behalten diese Kreaturen jedoch mehr ihrer ursprünglichen Gestalt und sind beweglicher.","Ausgestopfte Tiere von der Größe eines typischen, 60 cm hohen Teddybären haben das untenstehende Grundprofil. Passe es an deine jeweilige Kreatur (oder Kreaturen) an und füge Spezialfähigkeiten hinzu, die zu ihrer Herkunft passen. Magisch gefertigte haben etwa Kräfte oder sogar Arkanen Widerstand. Ein ausgestopfter Gepard könnte die Fähigkeit Anspringen dieser Kreatur haben, eine ausgestopfte Schlange einen Giftbiss oder Würgefähigkeit. Ein „Champion“-Teddybär in Gladiatorenkleidung könnte weit besseres Kämpfen und ein echtes Schwert haben. Anpassung ist der Schlüssel, ausgestopfte Tiere zu gefährlichen Bedrohungen zu machen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W4"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Athletik W4, Heimlichkeit W4, Kämpfen W4, Wahrnehmung W10","b":"1","pa":"4","ro":"4","sf":[["Biss/Klauen","Stä+W4."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Größe -2 (Klein)","Die meisten sind 60 cm groß."]]},{"n":"Fledermausschwarm","k":"Tiere","w":0,"s":["HOR"],"p":161,"bk":"sw_hor","g":"Schwärme","d":["Kleinere, blutsaugende Fledermäuse bilden riesige Kolonien unter der Erde oder in dunklen Räumen.","Sie jagen meist nur kleine Nagetiere, können aber größere Kreaturen angreifen, wenn sie gestört oder provoziert werden. Der Schwarm besteht aus Hunderten kleinerer Kreaturen."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["S","trengthd 8"],["Verstand","W4 (A)"]],"f":"Wahrnehmung W10","b":"10","pa":"4","ro":"7","sf":[["Biss","Schwärme verursachen jede Runde Hunderte winziger Bisse oder Stiche bei ihren Opfern, treffen automatisch (außer wenn Erschüttert) und verursachen 2W4 Schaden bei allen in der Schablone. Der Schaden wird auf die am schwächsten gepanzerte Stelle angewandt (Opfer in völlig versiegelten Anzügen sind immun)."],["Schwarm","+2 auf Erholung von Erschüttert; Parade +2; Schwärme bedecken die Fläche einer Mittleren Flächenschablone; Hieb- und Stichangriffe verursachen keinen Schaden, Flächenwaffen wirken normal."],["#","Variante Spezialfähigkeiten"],["Wasserwesen","Bewegungsweite 6 für die meisten Fische oder andere schwimmende Kreaturen."],["Biss","Manche Kreaturen, etwa Piranhas, haben bösartige Zähne und verursachen 2W6 oder mehr Schaden."],["Echoortung","Fledermäuse oder Schwärme ähnlicher Kreaturen erleiden keine Beleuchtungsabzüge, selbst in Stockdunkelheit."],["Fressrausch","Sobald Blut in der Luft oder im Wasser ist, wird der Schwarm wahnsinnig. Erhöhe seinen Schadenswürfel um einen Würfeltyp."],["Flug","Das variiert stark, aber Bewegungsweite 24 für die meisten Insektenschwärme oder Vogelschwärme (Schwärme bewegen sich meist langsamer als einzelne Kreaturen)."],["Ansteckung","Wer von einem krankheitsübertragenden Schwarm Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder zieht sich eine Schwächende Krankheit zu (siehe Savage Worlds)."],["Lähmung","Wer von den Bissen dieses Schwarms Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er für 2W6 Runden gelähmt und zu keiner Aktion fähig – nicht einmal zum Sprechen. Als Variante könnten Spinnenbisse stattdessen Tödliches Gift injizieren."],["Zerreißen","Die Bisse des Schwarms sind besonders bösartig oder enthalten womöglich Gerinnungshemmer. Sie verursachen Zerreißen-Schaden."]]},{"n":"Befleckter Musiker","k":"Humanoide","w":1,"s":["HOR"],"p":162,"bk":"sw_hor","d":["Manche Gerüchte über Heavy-Metal-Musiker, die Satan dienen, könnten wahr sein. Diese schwarzherzigen Musiker haben ihre Seelen für flüchtigen Ruhm und Reichtum verkauft."],"a":[["Geschicklichkeit","W6"],["Konstitution","W8"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W8, Darbietung W8, Einschüchtern W10, Heimlichkeit W6, Kämpfen W8, Wahrnehmung W6, Überreden W8","b":"6","pa":"5","ro":"6","x":[["Talente","Charismatisch, Improvisationsgabe"],["Ausrüstung","Gitarre (Stä+W6, Parade –1, zwei Hände)"]],"sf":[["Verderbende Texte","Jedes Mal, wenn jemand die Lieder eines befleckten Musikers hört, muss er eine Willenskraftprobe ablegen (–2 bei Live-Auftritt). Bei Misserfolg erhält der Hörer die Psychose, die der Musiker durch den Klang seiner Musik auslösen will. Eine Ballade des Blutvergießens könnte etwa die Menge in Berserker versetzen."],["Headbangen","Stä+W12. Nur möglich, wenn seine Aktionskarte im Kampf eine Bildkarte ist."],["Besänftigen","Befleckte Musiker sind oft von wütenden Zuhörern umgeben. Zum Selbstschutz spielen sie langsame Lieder, Oden oder Power-Balladen, die Angreifer anderswohin ablenken. Nutzt der Musiker das Manöver Verteidigen, muss jeder, der ihn angreifen will, Willenskraft mit –2 würfeln."]]},{"n":"Vampir, jung","k":"Untote","w":0,"s":["HOR"],"p":162,"bk":"sw_hor","g":"Vampire","d":["Blutsauger der Überlieferung sind in vielen Fantasy-Spielen verbreitet. Dies ist ein relativ junger Vampir ohne alle Kräfte, die ein älteres Wesen entwickeln könnte."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12+1"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W8, Athletik W8, Einschüchtern W8, Heimlichkeit W10, Kämpfen W8, Schießen W6, Wahrnehmung W6, Überreden W8","b":"6","pa":"6","ro":"9","x":[["Talente","Raserei, Kühler Kopf"]],"sf":[["Biss/Klauen","Stä+W4."],["Regeneration (Langsam)","Solange sie gefressen haben, können Vampire jeden Tag einen natürlichen Heilungswurf versuchen."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Heiliges Symbol)","Heilige Symbole wirken als Schutzzeichen gegen Vampire (siehe S. 48)."],["Schwäche (Weihwasser)","Zusätzlich zu den üblichen Effekten (S. 26) ist ein mit Weihwasser besprengter Vampir Erschöpft."],["Schwäche (nur auf Einladung)","Vampire können eine private Behausung nicht ohne Einladung betreten. Öffentliche Bereiche dürfen sie nach Belieben betreten."],["Schwäche (Pflock durchs Herz)","Ein Vampir, der von einem Gezielten Angriff aufs Herz (–4) getroffen wird, muss eine Konstitutionsprobe gegen den Schaden ablegen. Gelingt sie, erleidet er normal Schaden. Misslingt sie, zerfällt er zu Staub."],["Schwäche (Sonnenlicht)","Vampire verbrennen im Sonnenlicht. Sie erleiden 2W4 Schaden pro Runde, bis sie Asche sind. Panzerung schützt normal."]]},{"n":"Vampir, uralt","k":"Untote","w":1,"s":["HOR"],"p":163,"bk":"sw_hor","g":"Vampire","d":["Diese Werte gelten für einen Vampir etwas unterhalb des legendären Dracula, aber weit über jenen Blutsaugern frisch aus dem Grab. Die hier aufgeführten Fähigkeiten sind Standard – die SL möchte vielleicht weitere Talente hinzufügen, passend zum früheren Leben des Vampirs."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12+3"],["Verstand","W10"],["Willenskraft","W10"]],"f":"Allgemeinwissen W10, Athletik W8, Einschüchtern W12, Heimlichkeit W10, Kämpfen W10, Schießen W8, Wahrnehmung W8, Überreden W12","b":"6","pa":"7","ro":"10","x":[["Talente","Raserei (Verb.), Kühler Kopf"]],"sf":[["Biss/Klauen","Stä+W6, 2."],["Gestaltwechsel","Als Aktion kann sich ein Vampir mit einer Verstandsprobe mit –2 in einen Wolf oder eine Fledermaus verwandeln. Die Rückverwandlung in humanoide Gestalt erfordert eine Verstandsprobe."],["Bezaubern","Vampire können die Macht Marionette auf jene anwenden, die sich zu ihnen hingezogen fühlen (Entscheidung der SL), mit Verstand als arkaner Fertigkeit. Sie können die Macht unbegrenzt wirken und aufrechterhalten, aber nur ein Ziel gleichzeitig beeinflussen."],["Kinder der Nacht","Uralte Vampire können Wölfe oder Ratten herbeirufen und kontrollieren. Das erfordert eine Aktion und eine Verstandsprobe mit –2. Bei Erfolg kommen 1W6 Wölfe oder 1W6 Rattenschwärme binnen 1W6+2 Runden aus der Wildnis ringsum."],["Unverwundbarkeit","Vampire können nur durch Enthaupten, Sonnenlicht oder einen Pflock durchs Herz getötet werden (siehe diese Schwächen unten). Durch andere Angriffe können sie Erschüttert, aber nie Verwundet werden."],["Nebel","Uralte Vampire können sich in Nebel verwandeln. Das (oder die Rückkehr zur menschlichen Gestalt) erfordert eine Aktion und eine Verstandsprobe mit –2."],["Regeneration (Langsam)","Solange sie gefressen haben, können Vampire jeden Tag einen natürlichen Heilungswurf versuchen."],["Zeugen","Der Vampir kann einen anderen zum Vampir machen, indem er ihm eine gewisse Menge Blut aussaugt und ihn dann aus seinen eigenen Adern zurücktrinken lässt. Wie schnell sie ins Unleben zurückkehren, liegt bei der SL."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Heiliges Symbol)","Heilige Symbole wirken als Schutzzeichen gegen Vampire (siehe S. 48)."],["Schwäche (Weihwasser)","Zusätzlich zu den üblichen Effekten (S. 26) ist ein mit Weihwasser besprengter Vampir Erschöpft."],["Schwäche (nur auf Einladung)","Vampire können eine private Behausung nicht ohne Einladung betreten. Öffentliche Bereiche dürfen sie nach Belieben betreten."],["Schwäche (Pflock durchs Herz)","Ein Vampir, der von einem Gezielten Angriff aufs Herz (–4) getroffen wird, muss eine Konstitutionsprobe gegen den Gesamtschaden ablegen. Gelingt sie, erleidet er normal Schaden. Misslingt sie, zerfällt er zu Staub."],["Schwäche (Sonnenlicht)","Vampire verbrennen im Sonnenlicht. Sie erleiden 2W4 Schaden pro Runde, bis sie Asche sind. Panzerung schützt normal."]]},{"n":"Jiangshi","k":"Untote","w":0,"s":["HOR"],"p":164,"bk":"sw_hor","g":"Vampire","d":["Die aus China stammenden Jiangshi, „hüpfende Vampire“, sind eine Gattung für sich, anders als traditionelle westliche Vampire. Ihre Haut ist hellgrün, ihre Mäuler voller scharfer Zähne und ihre Nägel lang und hart.","Hüpfende Vampire haben ihren Namen von ihrer ungewöhnlichen Fortbewegung und sind tatsächlich zu normaler Bewegung unfähig – sie hüpfen, weil ihre Knie von der Leichenstarre steif sind. Selbst ihre Arme sind in der Totenstarre erstarrt, voll ausgestreckt und nur leicht beugbar."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12"],["Verstand","W4"],["Willenskraft","W6"]],"f":"Athletik W8, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W8","b":"4","pa":"6","ro":"9","sf":[["Biss/Klauen","Stä+W6."],["Atemspür","Jiangshi können mit ihren toten Augen nicht sehen, sondern spüren den Atem der Lebenden. Ein Charakter, der im Kampf den Atem anhalten will, muss zu Beginn jeder Runde eine Konstitutionsprobe ablegen. Bei Misserfolg kann der Vampir ihn entdecken (und somit in dieser Runde gegen ihn handeln). Die maximale Zahl aufeinanderfolgender Runden, die ein Charakter ohne Atmen aushält, entspricht seinem Konstitutionswürfel. Danach erleidet er jede Runde eine Stufe Erschöpfung bis zum Ausgeschaltet-Sein."],["Weiter Sprung","Jiangshi können die Weite ihrer Hüpfer mit einer Sprint-Aktion verlängern. Sie würfeln dafür einen W4 als Sprintwürfel, ignorieren aber jedes Schwierige Gelände."],["Zeugen","Ein von einem Jiangshi Verwundetes Opfer muss eine Konstitutionsprobe ablegen oder erkrankt an einer tödlichen Blutkrankheit, die es nach 1W4 Tagen tötet und in einen hüpfenden Vampir verwandelt. Das Opfer ist nicht zwangsläufig zu diesem Schicksal verdammt. Die traditionelle Heilung besteht aus Schlangengift und Klebreis, gemischt von einem taoistischen Priester. Du solltest eine zu deinem Setting passende Heilung ersinnen. Wichtig ist, dass das Opfer nicht aufhören darf, sich zu bewegen, bis die 1W4 Tage verstrichen sind, sonst gerinnt sein Blut und alle Hoffnung ist verloren."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Gebet)","Auf Reispapier geschriebene Gebete können am Vampir befestigt werden, um ihn bewegungsunfähig zu machen. Der Angreifer muss einen Gezielten Angriff auf den Kopf (–4) ablegen, um das Pergament anzubringen. Bei Erfolg wird der Vampir durch das Gebet bewegungsunfähig. Ein starker Wind kann das Gebet jedoch leicht lösen."],["Schwäche (Reis)","Auf den Boden gestreuter Klebreis verbrennt die Füße eines Vampirs. Jede Runde, die er auf dem Reis steht, und sei es nur einen Moment, erleidet er 2W10 Schaden."]]},{"n":"Manananggal","k":"Untote","w":0,"s":["HOR"],"p":165,"bk":"sw_hor","g":"Vampire","d":["Eine Cousine des Aswang (siehe S. 104) von den Philippinen, doch anders als dieses Wesen ist die Manananggal eine untote Blutsaugerin. Sie jagt nachts, indem sie fledermausartige Flügel ausbildet und die obere Hälfte ihres Körpers von der unteren trennt. Ihre Eingeweide hängen vom Torso herab, während sie auf der Suche nach Blut umherfliegt.","Tagsüber setzt sie sich wieder an ihre untere Körperhälfte, versteckt ihre Flügel und gibt sich als normaler Mensch aus. Der anerkannte Weg, eine zu vernichten, ist zu verhindern, dass sich ihr Torso bei Sonnenaufgang wieder mit ihren Beinen vereint, meist indem man Salz oder Glas in die Höhlung gießt, an der sich Wirbelsäule und Eingeweide ansetzen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W10, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W8, Überreden W8","b":"6","pa":"7","ro":"8","sf":[["Blutentzug","Gepackte Gegner müssen beim Packen und zu Beginn des Zugs der Kreatur eine Konstitutionsprobe ablegen, solange sie Gebunden oder Festgehalten bleiben. Ein Fehlschlag führt zu Erschöpfung, die zum Tod führen kann. Festgehaltene Opfer mit einem Messer oder einem Verbündeten können versuchen, die Zunge zu durchtrennen (Robustheit 3)."],["Furcht","Wer einer Manananggal begegnet, muss eine Furchtprobe ablegen."],["Flug","Bewegungsweite 8."],["Größe -1","Eine Manananggal ist nur halb so groß wie ein Mensch – in diesem Fall die obere Hälfte."],["Zunge","Stä+W4, Reichweite 2."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Morgendämmerung)","Eine Manananggal muss sich beim ersten Strahl der Morgendämmerung wieder mit ihrer unteren Körperhälfte vereinen oder wird vernichtet. Die untere Körperhälfte kann nicht zerstört werden, doch mehr als ein Pfund Salz oder geschmolzenes Glas in der Höhlung hindert den Torso an der Wiedervereinigung, wenn er zurückkehrt."]]},{"n":"Bauchrednerpuppe","k":"Konstrukte","w":0,"s":["HOR"],"p":169,"bk":"sw_hor","d":["Bauchrednerpuppen mit eigenem Willen waren Thema vieler Horrorfilme. Es sieht aus, als lasse der Bauchredner sie sprechen, doch in Wahrheit ist die Puppe der Boss. Puppen bewegen sich ungern von allein, außer wenn es unbedingt nötig ist, können es aber. In den meisten Fällen lassen sie ihren „Meister“ die Drecksarbeit erledigen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Athletik W6, Einschüchtern W10, Heimlichkeit W6, Kämpfen W6, Provozieren W12, Wahrnehmung W6, Überreden W10","b":"4","pa":"5","ro":"5 (2)","sf":[["Panzerung +2","Hölzerner Körper."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Marionette","Puppen können die Macht Marionette nutzen. Sie nutzen ihre Willenskraft als arkane Fertigkeit und haben 20 Machtpunkte."],["Größe -2 (Klein)","Puppen sind nicht größer als 90 cm."]]},{"n":"Unschuldiges Opfer","k":"Humanoide","w":0,"s":["HOR"],"p":169,"bk":"sw_hor","d":["Die meisten Horrorgeschichten brauchen Opfer. Nutze das Profil unten oder passe es an, um dein eigenes hilfloses Monsterfutter zu erschaffen, und füge Handicaps wie Feige für jene hinzu, die beim ersten Anzeichen von Gefahr davonlaufen, oder Mutig, wenn die Person wahrscheinlich ihren Mann steht."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4"],["Willenskraft","W6"]],"f":"Allgemeinwissen W6, Athletik W4, Heimlichkeit W6, Kämpfen W4, Schießen W4, Wahrnehmung W6, Überreden W4","b":"6","pa":"4","ro":"5","x":[["Ausrüstung","Behelfswaffen (Stä+W4)"]],"sf":[]},{"n":"Kampfdroide","k":"Roboter","w":0,"s":["HOR"],"p":169,"bk":"sw_hor","d":["Kampfdroiden sind zweibeinige Konstrukte, die aber wegen ihres skelettartigen Aussehens (das Furcht einflößen soll) nicht mit Menschen verwechselt werden können.","Ihre einzige Funktion ist, jede Lebensform zu vernichten, die sie als Feind sehen sollen. Sie können alle Standardwaffen nutzen, die der Rasse zur Verfügung stehen, die sie gebaut hat."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W8"],["Willenskraft","W6"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W8, Fahren W6, Heimlichkeit W6, Kämpfen W8, Schießen W10, Wahrnehmung W8, Überreden W4","b":"6","pa":"6","ro":"12 (4)","x":[["Talente","Kräftig, Rohling, Berechnend, Kühler Kopf, Meisterschütze, Volles Rohr!, Ruhige Hände"]],"sf":[["Fortschrittliche Sensoren","Kampfdroiden haben Infrarotsicht und Restlichtsicht und können als begrenzte freie Aktion zwischen beiden wechseln."],["Panzerung +4","Verstärkter Körper."],["Konstrukt","+2 auf Erholung von Angeschlagen; ignoriert 1 Punkt Wundabzüge; atmet nicht und leidet nicht unter Krankheit oder Gift."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Widerstandsfähig","Kann eine zusätzliche Wunde einstecken."]]},{"n":"Wassermonster","k":"Monster","w":0,"s":["HOR"],"p":170,"bk":"sw_hor","d":["Tiefe, dunkle Seen und der weite Ozean beherbergen viele unbekannte Kreaturen. See- und Meeresungeheuer sind riesige, im Wasser lebende Kreaturen, die menschliche Augen selten an der Oberfläche sehen. Meist ist von diesen geheimnisvollen Tieren nur ihr buckliger Rücken zu sehen, der die Wasseroberfläche durchbricht, bevor sie lautlos wieder unter die Wellen gleiten.","Ihr Aussehen variiert stark, von schlangenartigen Aalen bis zu reptilienartigen Ungeheuern mit paddelförmigen Flossen und langen Hälsen. Viele Wassermonster gelten als überlebende Exemplare lange für ausgestorben gehaltener Arten wie Mosasaurier, Plesiosaurier und den berüchtigten Megalodon."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+5"],["Verstand","W6 (A)"],["Willenskraft","W8"]],"f":"Athletik W6, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W6","b":"3","pa":"6","ro":"18 (2)","sf":[["Wasserwesen","Bewegungsweite 16. Manche sind vollständig aquatisch, andere müssen zum Atmen auftauchen. Halb-aquatische Wassermonster können eine Stunde lang den Atem anhalten."],["Panzerung +2","Wassermonster haben 2 Punkte speckige Panzerung."],["Biss","Stä+W8."],["Flossen-/Schwanzschlag","Stä+W6"],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Schiffsbrecher","Ein Wassermonster, das ein Schiff rammt, verursacht dem Schiff Stä+W12 Schaden."],["Größe 9 (Riesig)","Typische Wassermonster sind 15 m lang und wiegen viele Tonnen."],["#","Variante Spezialfähigkeiten"],["Aal/Schlange","Würgen (+2 auf Athletik- und Stärkewürfe zum Packen)."],["Megalodon","Biss: Stä+W10, PB 4."],["Plesiosaurier/Elasmosaurier","Langer Hals (Stä+W6, Reichweite 3)."]]},{"n":"Niederer Wendigo","k":"Monster","w":0,"s":["HOR"],"p":170,"bk":"sw_hor","g":"Wendigos","d":["Diese Version ist ein verbesserter Mensch – vielleicht ein Frühstadium der folgenden Kreatur. Er sieht noch menschlich aus, ist aber meist nackt oder in schmutzige Lumpen gehüllt und hat ein wildes Fletschen im blutverschmierten Gesicht. Viele kauen sich in dem vergeblichen Versuch, ihren Hunger zu stillen, die eigenen Lippen ab."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W6"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Athletik W8, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W6","b":"6","pa":"6","ro":"7","x":[["Talente","Kampfreflexe, Raserei (Verb.)"]],"sf":[["Biss/Klauen","Stä+W4."],["Üble Stärke","Fügt ein Wendigo einem Feind mit seinem Biss eine Wunde zu, steigt seine Stärke und Konstitution für den Rest der Begegnung um einen Würfeltyp (maximal 4). Außerhalb des Kampfes hält jede Steigerung eine Stunde an."]]},{"n":"Wahrer Wendigo","k":"Monster","w":1,"s":["HOR"],"p":170,"bk":"sw_hor","g":"Wendigos","d":["Echte Wendigos sind entweder fortgeschrittenere Formen ihrer geringeren Vettern oder stammen aus wilderem Geschlecht oder wilderen Umständen. Sie existieren meist im tiefsten Winter, wenn die Umstände Menschen in Hunger und Verzweiflung treiben, doch es gibt keinen Grund, warum solche Kreaturen nicht auch in anderen extremen Klimazonen existieren können."],"a":[["Geschicklichkeit","W10"],["Konstitution","W12"],["Stärke","W12+2"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Athletik W12, Einschüchtern W12, Heimlichkeit W8, Kämpfen W12, Wahrnehmung W10, Überleben W10","b":"8","pa":"8","ro":"10","x":[["Talente","Kampfreflexe, Raserei (Verb.)"]],"sf":[["Biss/Klauen","Wendigos haben gezackte Klauen und Zähne. Stä+W8, PB 2."],["Furcht (-2)","Wer einem Wendigo begegnet, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Immunität (Kälte/Hitze)","Wendigos in kalten Klimazonen sind immun gegen Kälte und kältebasierte Angriffe. Dasselbe gilt für solche, die in glühend heißen Gegenden entstanden sind."],["Nachtsicht","Ignoriert Abzüge für Düstere und Dunkle Beleuchtung."],["Größe 2","Wendigos sind über 3 m groß."],["Schwäche (Heißer Talg)","Ein Wendigo wird sofort getötet, wenn man ihm heißen Talg in den Rachen gießt, um sein eisiges Herz zu schmelzen."],["#","Variante Spezialfähigkeiten"],["","Manche Wendigos werden zu Verkörperungen des rauen Klimas, das sie hervorbrachte. Der Winter ist bei Weitem die häufigste Ausprägung dieser verfluchten, magischen Kreaturen."],["Wetter kontrollieren","Ein Wendigo kann sich 10 Minuten konzentrieren, um einen Blizzard in einem Radius von zwei Meilen heraufzubeschwören. Ein Wendigo aus der Wüste beschwört stattdessen einen Sandsturm mit demselben Beleuchtungsabzug, aber extremer Hitze. Siehe S. 42."],["Ansteckung","Wer durch einen Biss oder Klauenangriff Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen. Bei Misserfolg ist er mit einer Tödlichen Krankheit infiziert, die einmal täglich Konstitutionsproben für Wunden erzwingt. Wird das Opfer Ausgeschaltet, erwacht es 1W6 Stunden später als Geringerer Wendigo."],["Magie","Manche Wendigos haben übernatürliche Kräfte. Sie erhalten Zaubern W10 und 20 Machtpunkte. Die genauen Mächte variieren, doch Blenden, Graben, Elementarkontrolle, Illusion und Gedankenlesen sind verbreitet."],["Zerreißen","Die zerfetzten Klauen und Zähne mancher Wendigos verursachen Zerreißen-Schaden."]]},{"n":"Werjaguar","k":"Monster","w":0,"s":["HOR"],"p":171,"bk":"sw_hor","g":"Werwesen","d":["Werjaguare können übernatürliche Kreaturen oder Priester dunkler und blutdürstiger Götter sein, die ihren Anhängern die Fähigkeit zur Gestaltwandlung verleihen."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W12+1"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W10, Heimlichkeit W12, Kämpfen W12, Wahrnehmung W10, Überleben W8","b":"10","pa":"8","ro":"7","x":[["Talente","Flink"]],"sf":[["Biss/Klauen","Stä+W6."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Anspringen","Addiere +4 statt +2 auf den Schaden bei Wildem Angriff."]]},{"n":"Werhai","k":"Monster","w":0,"s":["HOR"],"p":171,"bk":"sw_hor","g":"Werwesen","d":["Werhaie sind eine Mischung aus Mensch und Hai. Dieses Beispiel hat Kopf und Haut eines Hais, Schwimmhände und eine Rückenflosse."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W12+1"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Allgemeinwissen W6, Athletik W10, Heimlichkeit W6, Kämpfen W12, Wahrnehmung W12+2, Überleben W6","b":"6","pa":"8","ro":"8","x":[["Talente","Raserei"]],"sf":[["Wasserwesen","Bewegungsweite 10."],["Biss","Stä+W8, Zerreißen."],["Furcht (-2)","Werhaie lassen allen, die sie sehen, das Blut in den Adern gefrieren."],["Fressrausch","Sobald eine erhebliche Menge Blut im Wasser ist (meist eine Wunde), geraten Werhaie in Blutrausch. Sie verfallen für den Rest des Kampfes in Berserker (wie das Talent)."],["Größe 1","Werhaie sind über 2,1 m groß."]]},{"n":"Werwolf","k":"Tiere","w":0,"s":["HOR"],"p":172,"bk":"sw_hor","g":"Werwesen","d":["Wenn ein Vollmond aufgeht, verlieren mit Lykanthropie Infizierte die Kontrolle und werden zu knurrenden Kreaturen, die auf Mord aus sind. Manche nehmen ihren verfluchten Zustand an und schwelgen in der Zerstörung, die sie anrichten."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W12+2"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Allgemeinwissen W8, Athletik W8, Einschüchtern W10, Heimlichkeit W10, Kämpfen W12+2, Wahrnehmung W12, Überleben W10","b":"8","pa":"9","ro":"8","x":[["Talente","Raserei"]],"sf":[["Biss/Klauen","Stä+W8."],["Furcht (-2)","Werwölfe lassen allen, die sie sehen, das Blut in den Adern gefrieren."],["Größe 1","Werwölfe sind kräftig gebaute Kreaturen."],["#","Variante Spezialfähigkeiten"],["Regeneration (Schnell)","Das Werwesen regeneriert, indem es als begrenzte freie Aktion eine Konstitutionsprobe ablegt. Bei Erfolg heilt es eine Wunde oder hebt Ausgeschaltet auf, bei einer Steigerung heilt es zwei Wunden. Lykanthropen können durch Silber verursachte Wunden nicht regenerieren."],["Ganz verschlucken","Sehr große Werhaie haben die Fähigkeit Ganz Verschlucken."],["Schwäche (Arkanes)","Lykanthropen können magischen Schaden nicht regenerieren."],["Schwäche (Wolfswurz)","Die Blume Wolfswurz wirkt als Schutzzeichen gegen Werwölfe (siehe S. 48)."]]},{"n":"Irrlicht","k":"Geister","w":1,"s":["HOR"],"p":173,"bk":"sw_hor","d":["Irrlichter sind die Geister von Hexen und Nekromanten, die auf dem Scheiterhaufen verbrannt wurden. Sie manifestieren sich als kleine Handvoll flackernder weißer Flammen, die sich seltsamerweise kalt statt heiß anfühlen. Der Legende nach kann ein mutiger Beobachter ein grinsendes Gesicht in einem Irrlicht sehen.","Ein Irrlicht nutzt das schimmernde Licht seiner Gestalt, um sein Opfer an einen abgelegenen Ort zu locken. Dort schwächt es die arme Seele mit einem Feuer, das aus der Hölle selbst zu stammen scheint. Erliegt das Ziel der Hitze, besessen der Geist seinen Leichnam, der sofort in Flammen aufgeht. Diese brennenden Zombies heißen manchmal „Flammende Jacks“, besonders in ländlichen Gegenden. Der Geist nutzt den wiederbelebten Körper, um so viel Chaos wie möglich anzurichten, bevor er von den jenseitigen Flammen der Kreatur verzehrt wird – vorzugsweise bei jenen, die ihm im früheren Leben Unrecht getan haben sollen.","Anfangs sucht ein Irrlicht die Gegend nahe seines Todes heim und sucht Rache an allen, die für jedes Unrecht gegen es im Leben verantwortlich waren. Doch selbst nachdem es sich an allen gerächt hat, die auch nur die geringste Verfehlung begangen haben, hält der Hass und Zorn an, der es ins Untotsein trieb. Schließlich zieht der Geist meist zu einsamen, öden Gegenden, wo sein unnatürlicher Groll auf alles Lebendige ihn ahnungslose Reisende jagen lässt.","Das Licht eines Irrlichts variiert von kaltem Weiß bis zu flammendem Orange. Der Geist kann seine Helligkeit nach Belieben auf die einer bloßen Kerze senken oder auf die einer Fackel steigern."],"a":[["Geschicklichkeit","W8"],["Konstitution","W6"],["Stärke","W4"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Athletik W6, Heimlichkeit W8, Kämpfen W6, Provozieren W6, Wahrnehmung W10, Überleben W8","b":"—","pa":"5","ro":"4","sf":[["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Flammender Jack","Das Irrlicht kann den Körper eines durch seinen Angriff Geistige Erschöpfung (siehe unten) getöteten Opfers wiederbeleben und besitzen. Behandle den Körper als Zombie (siehe S. 176), der jede Runde mit 1W6 Schaden brennt. Er kann andere Gegenstände in Brand setzen und von diesen Flammen Erschüttert und sogar zerstört werden. Die Flammen werden nicht gelöscht, solange das Irrlicht oder der Körper nicht zerstört sind."],["Flug","Bewegungsweite 8."],["Fokus","Der Geist ist an ein bestimmtes Talisman gebunden – meist ein Schmuckstück –, das sich unnatürlich heiß anfühlt (2W6 Schaden bei bloßer Haut). Wird dieser Gegenstand in Wasser getaucht, erleidet das Irrlicht 2W6 Schaden pro Runde, solange er so bleibt. Wird er in Weihwasser getaucht, wird das Irrlicht sofort vernichtet."],["Unverwundbarkeit","Irrlichter sind immun gegen alle nichtmagischen Angriffe, erleiden aber 1W6 Schaden, wenn sie mit mindestens einer Gallone (ca. 4 Litern) Wasser übergossen werden, +2 je weitere Gallone."],["Größe -1","Irrlichter haben einen Durchmesser von etwa 60 bis 90 cm."],["Geistige Erschöpfung","Das einzige Angriffsmittel eines Irrlichts in seiner Anfangsgestalt ist, sein Opfer einer übernatürlichen Hitze auszusetzen, die nur es selbst spüren kann. Das Irrlicht und sein Ziel legen eine Vergleichende Willenskraftprobe ab. Verliert das Opfer, erleidet es eine Stufe Erschöpfung. Ausgeschaltet führt zum Tod und zum Flammenden Jack (siehe oben)."]]},{"n":"Hexe","k":"Humanoide","w":1,"s":["HOR"],"p":173,"bk":"sw_hor","d":["Hexen sind Frauen (Männer sind Hexer), die Magie praktizieren und von Einheimischen oft missverstanden werden. Sie haben das Talent Arkaner Hintergrund (Hexer/Hexe) (S. 68) und können wohlwollend oder harmlos sein. Unten steht eine typische Hexe, wie man sie am Dorfrand oder sogar in einer modernen Welt finden könnte, die ihre Dienste anbietet. Die unten aufgeführten Mächte sind für solche Hexen am häufigsten und sollten für die Kampagne angepasst werden. „Vetteln“ werden oft mit Hexen verwechselt, und manche waren es vielleicht einst, sind aber nun rein böse, unmenschliche Wesen, die Elend und Schmerz bringen wollen. Mehrere Arten von Vetteln findest du ab S. 136."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W6, Athletik W6, Heimlichkeit W8, Kämpfen W4, Okkultismus W8, Recherche W6, Wahrnehmung W6, Zaubern W8, Überreden W6","b":"6","pa":"4","ro":"5","x":[["Talente","Arkaner Hintergrund (Hexe), Die Geisterstunde"],["Mächte","Tierfreund, Eigenschaft steigern/senken, Heilung (Machtpunkte: 10)"]],"sf":[]},{"n":"Wolf","k":"Tiere","w":0,"s":["HOR"],"p":174,"bk":"sw_hor","d":["Wolfsrudel jagen strategisch und treiben ihre Beute in Fallen, Schwieriges Gelände oder Sackgassen. Sie werden stets von einem Alpha-Wildcard angeführt, mit gesteigerter Stärke oder Kämpfen, ein oder zwei Kampftalenten oder beidem."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W8"],["Verstand","W6 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W6, Überleben (tracking) W10","b":"10","pa":"6","ro":"6","x":[["Talente","Aufmerksamkeit, Flink (Sprintwürfel W10)"]],"sf":[["Biss","Stä+W6."],["#","Variante Spezialfähigkeiten"],["Bellen","Unternimmt das Rudel keine andere Aktion, auch keine Bewegung, kann es so heulen, bellen und jaulen, dass seine Feinde in Schrecken geraten. Alle Feinde innerhalb von 12“ (24 m) müssen eine Furchtprobe mit –2 ablegen, wenn vier bis neun Wölfe da sind, oder mit –4 bei zehn oder mehr."],["Heulen","Als begrenzte Aktion kann ein Alphawolf eine Einschüchtern-Probe in einer Kegelschablone ablegen. Alle Ziele darin sind betroffen und widerstehen einzeln."],["Zerreißen","Der Biss besonders bösartiger Wölfe kann Zerreißen-Schaden verursachen."]]},{"n":"Schreckenswolf","k":"Tiere","w":0,"s":["HOR"],"p":174,"bk":"sw_hor","d":["Schreckenswölfe sind große, wilde Wölfe, die manchmal von anderen Kreaturen als Kampfhunde eingesetzt werden. Man findet sie auch in Rudeln in den tiefsten, dunkelsten Wäldern umherstreifen, wo sie jene jagen, die töricht genug sind, ihr Revier zu durchqueren."],"a":[["Geschicklichkeit","W8"],["Konstitution","W10"],["Stärke","W8"],["Verstand","W6 (A)"],["Willenskraft","W6"]],"f":"Athletik W8, Einschüchtern W8, Heimlichkeit W8, Kämpfen W8, Wahrnehmung W6, Überleben (tracking) W10","b":"8","pa":"6","ro":"8","x":[["Talente","Aufmerksamkeit, Flink"]],"sf":[["Biss","Stä+W8."],["Größe 1","Schreckenswölfe in Horrorkampagnen sind oft so groß wie Ponys."]]},{"n":"Implantierer","k":"Außerirdische","w":0,"s":["HOR"],"p":175,"bk":"sw_hor","g":"Xenoform","d":["Eine Art von Xenoform ist darauf spezialisiert, die Eier der Königin in andere Lebensformen einzupflanzen. Sobald die Eier ausgebrütet sind, stirbt das Opfer, und ein neuer Xenoform (welcher Art auch immer der Stock gerade am meisten braucht) schlüpft."],"a":[["Geschicklichkeit","W10"],["Konstitution","W8"],["Stärke","W10"],["Verstand","W8 (A)"],["Willenskraft","W8"]],"f":"Athletik W10, Einschüchtern W8, Heimlichkeit W12, Kämpfen W8, Wahrnehmung W8","b":"6","pa":"6","ro":"5 (2)","x":[["Talente","Ausweichen"]],"sf":[["Panzerung +2","Dicke Platten."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Lähmung","Wer vom Schwanz eines Xenoforms Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er für 2W6 Runden gelähmt und zu keiner Aktion fähig – nicht einmal zum Sprechen."],["Zeugen","Wer von einem packenden Implantierer Gebunden wird, erleidet jeden Zug eine Wunde. Wird er Ausgeschaltet, wird er zum Wirt einer neuen Kreatur. Der Wirt stirbt 1W6 Stunden später, wenn der neue Xenoform schlüpft. Zwischen Einpflanzung und Tod kann der Wirt wiederbelebt werden und normal handeln. Eine Spezialoperation (Heilen –4) kann die Kreatur entfernen, verursacht dem unglücklichen Wirt aber dennoch 1W4 Wunden."],["Größe -3 (Sehr klein)","Ein Implantierer ist nur etwa so groß wie eine Hauskatze."],["Schwanz","Stä+W4."]]},{"n":"Jäger-Krieger","k":"Außerirdische","w":0,"s":["HOR"],"p":175,"bk":"sw_hor","g":"Xenoform","d":["Der Xenoform-Krieger ist ein geschickter Jäger und nutzt komplexe Taktiken, um seine Beute zu trennen und zu besiegen."],"a":[["Geschicklichkeit","W10"],["Konstitution","W8"],["Stärke","W12+1"],["Verstand","W8 (A)"],["Willenskraft","W10"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W12, Kämpfen W8, Wahrnehmung W8","b":"6","pa":"6","ro":"9 (2)","sf":[["Panzerung +2","Dicke Platten."],["Biss/Klauen","Stä+W6."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Lähmung","Wer vom Schwanz eines Xenoforms Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er für 2W6 Runden gelähmt und zu keiner Aktion fähig – nicht einmal zum Sprechen."],["Größe 1","Aufrecht ist der Xenoform 2,1 m groß."],["Schwanz","Stä+W6, Reichweite 1."],["Wandkrabbler","Der Xeno kann sich mit voller Bewegungsweite an senkrechten und mit halber an überhängenden Flächen bewegen."]]},{"n":"Jäger-Königin","k":"Außerirdische","w":1,"s":["HOR"],"p":175,"bk":"sw_hor","g":"Xenoform","d":["Xenoformen werden typischerweise von einer Königin angeführt. Ihre Hauptfunktion ist das Eierlegen, doch tief in ihrem Bau ist sie eine gefräßige Mörderin.","Königinnen haben vier Beine am Brustkorb und zwei am Oberkörper, die zum Greifen oder Angreifen dienen."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12+6"],["Verstand","W10 (A)"],["Willenskraft","W12"]],"f":"Athletik W10, Einschüchtern W12, Heimlichkeit W8, Kämpfen W10, Wahrnehmung W8","b":"6","pa":"7","ro":"18 (4)","sf":[["Panzerung +4","Dicke Platten."],["Biss/Klauen","Stä+W8."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Wärmesicht","Halbiere die Abzüge für Beleuchtung bei Angriffen auf warme Ziele."],["Lähmung","Wer vom Schwanz eines Xenoforms Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder ist Betäubt. Zudem ist er für 2W6 Runden gelähmt und zu keiner Aktion fähig – nicht einmal zum Sprechen."],["Größe 6 (Groß)","Die Königin ist 9 m lang."],["Schwanz","Stä+W8, Reichweite 1."],["#","Variante Spezialfähigkeiten"],["Säureblut","Erleidet die Kreatur Wunden, versprüht sie tödliche Säure. Ziele in einer Kleinen Flächenschablone sind betroffen, wenn der Schaden eine Wunde verursachte, oder in einer Mittleren Flächenschablone bei zwei oder mehr Wunden. Alle Ziele in der Schablone müssen Ausweichen würfeln oder erleiden 3W6 Schaden, PB 4. Betroffene Ziele erleiden nachwirkenden Schaden: 3W4 PB 4 zu Beginn ihres nächsten Zugs. Andere Xenoformen sind gegen diesen Schaden immun."],["Explodieren","Diese üblen Kreaturen sind meist mit Sprengstoff irgendeiner Art gefüllt. Wenn sie Ausgeschaltet werden, explodieren sie mit 3W10 Schaden in einer Großen Flächenschablone. Das kann eine Kettenreaktion auslösen, wenn andere explosive Xenoformen in die Explosion geraten."]]},{"n":"Zombie","k":"Untote","w":0,"s":["HOR"],"p":176,"bk":"sw_hor","g":"Zombies (Horror)","d":["Diese wandelnden Toten sind typische stöhnende Unholde auf der Suche nach frischem Fleisch."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W4"],["Willenskraft","W4"]],"f":"Athletik W4, Einschüchtern W6, Heimlichkeit W6, Kämpfen W6, Wahrnehmung W4","b":"4","pa":"5","ro":"7","sf":[["Biss/Klauen","Stä."],["Furcht","Jeder, der die Kreatur sieht, muss eine Furchtprobe ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Schwäche (Kopf)","Gezielte Angriffe auf den Kopf eines Zombies verursachen den üblichen +4 Schaden."]]},{"n":"Superzombie","k":"Untote","w":1,"s":["HOR"],"p":176,"bk":"sw_hor","g":"Zombies (Horror)","d":["Im Labor gebaut oder aus dunkler Magie geboren, sind „Super“-Zombies weit stärker und zäher als der durchschnittliche wandelnde Tote. Sie sind zudem unerbittliche Jäger, die ihre Beute aufspüren."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W10"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Athletik W8, Einschüchtern W10, Heimlichkeit W4, Kämpfen W8, Wahrnehmung W6","b":"4","pa":"6","ro":"12","x":[["Talente","Schläger, Keine Gnade"]],"sf":[["Biss","Stä+W6."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Schlag","Stä+W6 (durch Rohling)"],["Witterung","Hat ein Super-Zombie die Witterung eines Ziels, verfolgt er es mit einer effektiven Überleben-Fertigkeit von W12."],["Untot","+2 Robustheit; +2 auf Erholung von Erschüttert; kein zusätzlicher Schaden durch Gezielte Angriffe außer auf den Kopf; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Krankheit und Gift."],["#","Variante Spezialfähigkeiten"],["","Hier eine Liste zusätzlicher Spezialfähigkeiten, mit denen du verschiedene Arten wandelnder Toter erschaffen kannst."],["Explodieren","Diese üblen Kreaturen sind meist mit Sprengstoff irgendeiner Art gefüllt. Wenn sie Ausgeschaltet werden, explodieren sie mit 3W10 Schaden in einer Großen Flächenschablone. Das kann eine Kettenreaktion auslösen, wenn andere explosive Zombies in die Explosion geraten."],["Gas","„Gaszombies“ sind Opfer von Industrieunfällen oder Gasangriffen oder absichtlich mit giftigen Dämpfen gefüllt. Wird die Kreatur Verwundet, setzt sie eine Giftgaswolke in einer Mittleren Flächenschablone frei. Wer in die Wolke gerät, muss eine Konstitutionsprobe mit –2 ablegen oder erleidet eine Wunde."],["Ansteckung","Wer durch einen Biss Erschüttert oder Verwundet wird, muss eine Konstitutionsprobe ablegen oder ist mit einer Tödlichen Krankheit infiziert, die einmal pro Stunde Konstitutionsproben für Wunden erzwingt. Führt dies unweigerlich zum Tod, kehrt das Opfer binnen 1W10 Minuten als Zombie zurück."],["Wärmesicht","Mit Technologie erschaffene Zombies könnten Infrarotsicht haben, ebenso Untote aus den Leichen bestimmter Halbmenschen. Halbiere Beleuchtungsabzüge beim Angriff auf warme Ziele."],["Parasitenzombie","Diese Zombies brauchen kein Gehirn zum Funktionieren, da der Leichnam von einem mit der Wirbelsäule verschmolzenen parasitären Außerirdischen belebt wird. Der Zombie kann nur durch einen Gezielten Angriff auf den Parasiten (–4 auf Treffer, insgesamt +6 Schaden) oder einen Flächenangriff verletzt werden."],["Zeugen","Wer von einem Zombie getötet wird, erhebt sich binnen 1W10 Minuten selbst als Zombie."],["Größe -1","Aus Kindern oder kleineren Kreaturen geformte Zombies sind etwa 1,20 m groß. Senke die Robustheit um 1."],["Sporen","Eine Wolke unsichtbarer Sporen umgibt einen Sporenzombie. Jede Runde, die ein Feind neben ihm steht, muss er eine Konstitutionsprobe ablegen (+2, wenn er Nase und Mund bedeckt) oder erleidet eine Stufe Erschöpfung. Ein Charakter, der Ausgeschaltet wird, stirbt, kehrt aber binnen 1W4 Stunden als Sporenzombie zurück."],["Echter Zombie","Dieser Zombie kann nur durch Schaden am Kopf Verwundet werden (ein Gezielter Angriff auf den Kopf oder ein Flächenangriff). Jeder andere Schaden kann nicht mehr als Erschüttert bewirken, wobei Gezielte Angriffe dennoch Gliedmaßen abtrennen können, wenn sie dem Ding mindestens eine Wunde zufügen können."],["#","Variante Schwächen"],["","Manchmal haben Zombies außer ihrem Schädel noch andere Schwächen. Passe deinen Wandler mit diesen verschiedenen Optionen an."],["Hülle","Dieser Zombie ist fast vollständig ausgetrocknet. Wenn er geht, klingt es wie raschelndes Laub. Er erleidet +2 Schaden durch Feuer und gilt als sehr leicht entflammbar."],["Willenlos","Der Verstand dieses Zombies ist W4(A) statt W4. Er kann nicht sprechen (nicht einmal „Hirn!“). Steht etwas zwischen ihm und seiner Mahlzeit, braucht er eine Verstandsprobe, um etwas so Einfaches wie das Drehen einer Türklinke, das Erklimmen einer Leiter, das Umgehen eines offenen Gullys statt hineinzulaufen oder das Meiden eines lodernden Feuers herauszufinden. Sonst schlurft er einfach dumm vorwärts und zerschmettert alles in seinem Weg."],["Schwäche (Fleischbedarf)","Die meisten Zombies müssen Fleisch essen, um ihr Unleben aufrechtzuerhalten. Ein solcher Schrecken muss für jeweils 24 Stunden ohne Fleisch eine Konstitutionsprobe ablegen oder erleidet eine Stufe Erschöpfung. Erreicht er Ausgeschaltet, ist er so weit verfallen, dass er den Körper nicht mehr belebt halten kann."]]},{"n":"Elite-Zombie: Einherjer","k":"Untote","w":0,"s":["HOR"],"p":178,"bk":"sw_hor","g":"Zombies (Horror)","d":["Nicht alle Zombies sind nahezu hirnlose, schlurfende Leichname. Die Einherjar sind eine solche Art. In der nordischen Mythologie waren die Einherjar Odins ewige Krieger, Sterbliche, die sich einen Platz in Walhalla verdient hatten. Nekromanten konnten Odin um den Einsatz der Einherjar bitten, auch wenn sie auf der Erde als Zombies statt als „lebende“ Krieger erscheinen. Sie sind für ihre Stärke und ihren Mut berühmt.","In einem Fantasy-Horror-Spiel könnte ein Kriegsgott ähnliche untote Gefolgsleute haben, die er begünstigten Sterblichen leiht. In einem modernen Spiel sind die alten nordischen Götter vielleicht nicht ganz tot und können sich weiter auf der Erde bemerkbar machen.","Einherjar können sprechen, doch traditionelle sprechen nur Altnordisch. Ein Charakter mit Kenntnis einer skandinavischen Sprache kann eine Allgemeinwissen-Probe (wenn es seine Muttersprache ist) oder Sprachen-Probe ablegen, um mit ihnen zu kommunizieren."],"a":[["Geschicklichkeit","W6 Smarts W6"],["Konstitution","W10"],["Stren","gth W12"],["Willenskraft","W8"]],"f":"Athletik W8, Boote fahren W6, Einschüchtern W8, Heimlichkeit W6, Kämpfen W8, Provozieren W6, Wahrnehmung W6","b":"6","pa":"6 oder 8 (shield)","ro":"10 (1)","x":[["Talente","Berserker, Raserei"],["Ausrüstung","Lederrüstung (+1), Mittlerer Schild (Parade +2), Schwert oder Streitaxt (Stä+W8), Speer (Stä+W6, Parade +1, Reichweite +1)"]],"sf":[["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."]]},{"n":"Zombiedrache","k":"Untote","w":1,"s":["HOR"],"p":178,"bk":"sw_hor","d":["Die unten aufgeführte Bestie basiert auf dem ausgewachsenen Drachen aus dem Savage Worlds Fantasy Companion, ist aber nicht einfach diese Kreatur mit der Fähigkeit Untot. Sie ist ein voll ausgearbeitetes Wesen aus Bosheit und Tod, durch die übelste Nekromantie erweckt. Vielleicht wurde sie erschaffen, um das einsame Schloss eines Schrecklichen Lichs in den fernen Mooren zu bewachen. Oder sie könnte die furchtbare Wiedergeburt eines titanischen Feindes sein, der von einem längst im Nebel der Zeit verlorenen Helden erschlagen wurde. In einer High-Fantasy-Welt könnte der Zombiedrache auch das Reittier eines schrecklichen Vampirs oder Zombieherren sein, der auf die Bevölkerung herabstößt, um sie daran zu erinnern, wer ihr unglückliches Leben beherrscht."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12"],["Stärke","W12+8"],["Verstand","W8"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W10, Einschüchtern W12, Heimlichkeit W8, Kämpfen W10, Wahrnehmung W12, Überreden W10","b":"8","pa":"7","ro":"21 (2)","x":[["Talente","—"]],"sf":[["Panzerung +2","Verrottete, schuppige Haut."],["Biss/Klauen","Stä+W8."],["Aasatem","Der Drache kann grünes Feuer mit 3W6 Schaden speien oder eine Wolke giftigen Gases aus seinen höhlenartigen Eingeweiden ausstoßen. Letzteres Betäubt jeden in der Schablone, der keine Konstitutionsprobe mit –2 (–4 bei Steigerung) besteht."],["Furcht (-4)","Wer einen mächtigen Drachen sieht, muss eine Furchtprobe mit –4 ablegen."],["Flug","Bewegungsweite 18."],["Zäh","Ein zweites Angeschlagen-Ergebnis im Kampf verursacht keine Wunde."],["Größe 9 (Riesig)","Ausgewachsene Drachen sind von der Nase bis zum Schwanz 18 m lang und wiegen über 90 Tonnen."],["Wegschlagen","Ignoriert bis zu 4 Punkte Größenkategorieabzüge, wenn er Kreaturen angreift, die kleiner sind als er selbst."],["Schwanzhieb","Stä+W4. Die Kreatur kann einen freien Angriff gegen bis zu zwei Feinde neben oder hinter ihr ablegen, ohne Abzüge."],["Untot","+2 Robustheit; +2 auf Erholungsproben gegen Angeschlagen; kein zusätzlicher Schaden durch Angriffe auf Angesagte Ziele; ignoriert 1 Punkt Wundabzüge; atmet nicht; immun gegen Gifte und Krankheiten."],["Unaufhaltsam","Drachen erleiden pro Angriff höchstens eine Wunde, egal wie viele Wunden normalerweise verursacht würden (nachdem Würfe zum Schaden wegstecken abgelegt wurden)."]]},{"n":"Zombieherr","k":"Untote","w":1,"s":["HOR"],"p":179,"bk":"sw_hor","d":["Der Zombieherr ist ein intelligenter Zombie, der mit einer einzigen Berührung seiner verrottenden Hände Zombies erschaffen kann. Manche Legenden sagen, Zombieherren seien Praktizierende der dunklen Künste, von ihren Gönnern mit Unleben belohnt. Andere behaupten, sie seien verfluchte Wesen, die den Weg uralter Götter oder übler Dämonenfürsten kreuzten. Obwohl sie nicht so mächtig wie Lichs sind, sind sie fähige Nekromanten mit angeborenem Wissen über ihre Diener."],"a":[["Geschicklichkeit","W8"],["Konstitution","W8"],["Stärke","W10"],["Verstand","W10"],["Willenskraft","W10"]],"f":"Allgemeinwissen W6, Athletik W8, Heimlichkeit W6, Kämpfen W8, Okkultismus W8, Wahrnehmung W8, Zaubern W10","b":"6","pa":"6","ro":"8","x":[["Mächte","Dunkelsicht, Gedankenverbindung, Trägheit/Tempo, Zombie (Machtpunkte: 30)"]],"sf":[["Todesberührung","Zombieherren entziehen den Lebenden um sich mit einer Berührung das Leben. Statt eines normalen Angriffs kann ein Zombieherr einen Berührungsangriff ablegen (siehe Savage Worlds). Jede Steigerung auf seinen Kämpfen-Wurf verursacht seinem Ziel automatisch eine Wunde. Ein Ausgeschaltetes Opfer muss eine letzte Konstitutionsprobe ablegen oder reiht sich 1W4 Runden später als Zombie in die Reihen der Verdammten ein."],["Furcht (-2)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Nekromantie","Alle Zombies, die der Lord mit der Macht Zombie erschafft, sind dauerhaft."],["Zeugen","Wer durch die Todesberührung eines Zombieherren getötet wird, erhebt sich mit 50 % Wahrscheinlichkeit binnen 1W4 Runden als Zombie."]]},{"n":"Die Farbe","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":190,"bk":"sw_hor","d":["Farben sind schillernde, unkörperliche Wesen, die durch die Leere des Weltraums reisen. Trifft man sie auf einem Planeten, geschieht es meist während einer Häutungsphase, in der die Kreatur selbst sich in die Erde gräbt und Energie ihrer wachsenden Gestalt alles Pflanzen- und Tierleben der Umgebung durchdringt.","Tagsüber wirkt alles normal, wenn auch kränklich, obwohl die Chemie des befallenen Lebens verändert ist. Bei Lichtmangel haben die Farbe und alles, was sie infiziert hat, ein seltsames Leuchten, und befallene Pflanzen beugen und wiegen sich. Am Ende des Prozesses taucht die Farbe auf, um allem in der befallenen Region die Lebenskraft zu entziehen, und hinterlässt eine ausgedörrte Landschaft, die fortan kein Leben mehr tragen kann."],"a":[["Geschicklichkeit","W10"],["Konstitution","W6"],["Stärke","W12+2"],["Verstand","W10"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W8, Heimlichkeit W8, Kämpfen W4, Wahrnehmung W6, Überleben W6","b":"—","pa":"4","ro":"10","x":[["Handicaps","Stumm"]],"sf":[["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; erscheint im Dunkeln nur als überirdisches Leuchten (–4 auf Treffer) und ist im Licht völlig unsichtbar (–6 auf Treffer). Magische Gegenstände, Waffen und übernatürliche Kräfte wirken normal auf sie."],["Furcht","Wer das Leuchten einer Farbe sieht, muss eine Furchtprobe ablegen, ob das Leuchten von der Kreatur selbst oder dem von ihr infizierten Leben ausgeht."],["Flug","Bewegungsweite 24."],["Immunität","Eine Farbe hat keine körperliche Form. Sie muss nicht atmen und ist immun gegen Gezielte Angriffe, Krankheit und Gift."],["Ansteckung","Eine Farbe verbringt Monate oder Jahre damit, in einem Gebiet heranzureifen und alles Lebende im Umkreis mehrerer Meilen zu infizieren. In der Gegend geborene Bewohner sind automatisch infiziert, und Einwohner müssen jede Woche eine Konstitutionsprobe ablegen oder werden ebenfalls infiziert. Infizierte müssen eine Willenskraftprobe mit –2 ablegen, um wegzugehen, und teilen nachts das Leuchten der Farbe. So Infizierte erhalten –2 auf Vergleichende Würfe gegen die Farbe und auf die Konstitutionsprobe gegen deren Lebensentzug."],["Lebensentzug","Am Ende der Bewegung der Farbe müssen alle Kreaturen in einer auf sie zentrierten Großen Flächenschablone Konstitution würfeln oder erleiden eine Wunde. Getötete werden zu verschrumpelten, zersetzten Leichen."],["Größe 5 (Groß)","Obwohl unkörperlich, füllt die Kreatur ein Volumen von etwa 6 m Durchmesser."],["Unaufhaltsam","Erleidet pro schadenverursachendem Angriff maximal eine Wunde (nach Wurf auf Schaden wegstecken), es sei denn, die Aktionskarte des Angreifers ist ein Joker."],["Schwäche (Licht)","Die Kreatur ist bei Tageslicht oder jedem anderen hellen Licht Abgelenkt."]]},{"n":"Dunkle Brut","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":190,"bk":"sw_hor","d":["Okkulte Wälzer flüstern von der Schwarzen Ziege der Wälder mit den Tausend Jungen – dies sind die Jungen. Sie entspringen ihrem Körper und werden meist wieder verschlungen, doch ein Teil entkommt und wird zum Stellvertreter ihrer entsetzlichen Mutter.","Die Dunkle Brut sind pechschwarze Massen aus strangartigen Tentakeln, verdreht zur vagen Gestalt eines Baumes. An der Basis winden sich diese Ranken zu Beinen, die denen einer Ziege ähneln. Kleine Mäuler bedecken die oberen Tentakel, und der mittlere Stamm der Brut ist ein einziger sabbernder Schlund. Grüner Eiter sickert aus ihrem Körper.","Versuche, den Älteren Gott zu beschwören oder zu besänftigen, bringen meist stattdessen die Dunkle Brut hervor, die denselben Zweck erfüllt: als Götzenbild der Anbetung oder Zerstörungsmaschine, die auf die Feinde des Kults gerichtet wird. Die Dunkle Brut verschlingt nicht nur, sie gebiert auch zuckende Abscheulichkeiten, berührt von der Macht und dem Wahnsinn ihrer Mutter."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+3"],["Verstand","W6"],["Willenskraft","W10"]],"f":"Allgemeinwissen W4, Athletik W6, Einschüchtern W10, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6, Überleben W8","b":"6","pa":"6","ro":"12","x":[["Handicaps","Stumm"],["Talente","Rohling, Naturbursche"]],"sf":[["Ballistischer Schutz","Verringere den Schaden durch Kugeln um 4."],["Biss","Stä+W8."],["Blutentzug","Jeder strangartige Tentakel ist mit kleinen Mäulern bedeckt, die lebenswichtige Flüssigkeiten aus gepackter Beute beißen und saugen. Jede Runde, die das Opfer Gebunden oder Verstrickt bleibt, muss es Konstitution würfeln oder erleidet eine Stufe Erschöpfung, bis es entkommt oder stirbt. So verlorene Erschöpfung erholt sich einmal pro Tag mit einer reichhaltigen Mahlzeit."],["Furcht","Wer eine Dunkle Brut sieht, muss eine Furchtprobe ablegen."],["Immunität","Immun gegen Säure, Elektrizität, Feuer und Gift."],["Widerstandsfähig","Kann eine zusätzliche Wunde einstecken."],["Zeugen","Jede Kreatur, die getötet wird, während sie Ganz Verschluckt ist, erscheint 1W6 Stunden später als neues Wesen – körperlich verändert und nun völlig im Bann des Älteren Gottes, der die Dunkle Brut gebar. Die ghulische Verhöhnung des Opfers wird von der SL gesteuert."],["Größe 5 (Groß)","Die Dunkle Brut ist über 6 m groß und wiegt fünf Tonnen."],["Ganz verschlucken","Von einer Dunklen Brut gebissene Opfer müssen eine Ausweichen-Probe ablegen oder werden Ganz Verschluckt (S. 101)."],["Tentakel (4)","Vier Tentakelaktionen und Reichweite 5 (10 m). Tentakel verursachen Stä+W4 Schaden."],["Unaufhaltsam","Erleidet pro schadenverursachendem Angriff maximal eine Wunde (nach Wurf auf Schaden wegstecken), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]},{"n":"Dimensionsschlurfer","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":191,"bk":"sw_hor","d":["Diese abscheulichen Kreaturen sind Jäger von einem anderen Ort und einer anderen Zeit, die durch Magie oder üble Unfälle als spektrale Schatten in unsere Welt gezogen werden.","Hier sind sie unkörperlich, haben aber die Macht, unglückliche Opfer zurück in ihr dunkles Reich zu ziehen, um sie zu verschlingen.","Das Wesen selbst ist groß und grob humanoid, mit verlängerten Armen. Es hat einen Chitinpanzer, der aber von herabhängenden Fetzen loser Haut verdeckt wird. Die schlabbrige Haut hat dunkle Schlitze, wo normalerweise Augen wären.","Schlurfer pirschen meist allein durch unsere Welt, doch sobald ein Ziel in ihrer Welt feststeckt, lockt es andere Jäger an, die rasch am Fraß in diesem grauen Reich teilnehmen."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12"],["Stärke","W12+1"],["Verstand","W6"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W10, Heimlichkeit W10, Kämpfen W8, Wahrnehmung W6, Überleben W8, Überreden W6","b":"4","pa":"6","ro":"14 (4)","x":[["Handicaps","Blutrünstig, Stur"],["Talente","Rohling"]],"sf":[["Panzerung +4","Chitinplatten unter der Haut."],["Klauen","Stä+W6."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; magische Gegenstände, Waffen und übernatürliche Kräfte wirken normal auf sie; Dimensionsschlurfer sind stets sichtbar, aber teilweise verblasst und verschleiert (–2 auf Treffer). Anders als normale ätherische Bedrohungen kann ein Dimensionsschlurfer feste Ziele nur beeinflussen, wenn er sie zuvor Ergriffen hat; andere ätherische Ziele kann er stets beeinflussen."]]},{"n":"Fliegender Polyp","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":192,"bk":"sw_hor","d":["Diese uralte Art hat keinen bekannten Namen. Man nennt sie nach ihrem abscheulichen Aussehen: eine sich windende Fleischmasse, verdreht wie ein Stängel. Der Polyp hat vage, wechselnde Massen in seiner Form, amorphe Fortsätze und Öffnungen, die als Tentakel und Münder dienen.","Polypen wurden vor langer Zeit in den Untergrund getrieben, wo manche noch heute in dunklen Tempeln verweilen. Sie sind intelligent, aber völlig fremdartig, verfolgen unergründliche Ziele und verlorene magische Künste. Die Polypen sind bewandert in Elementarmagie, meist auf der Manipulation von Luft basierend."],"a":[["Geschicklichkeit","W4"],["Konstitution","W12"],["Stärke","W12+6"],["Verstand","W10"],["Willenskraft","W10"]],"f":"Allgemeinwissen W4, Athletik W6, Einschüchtern W12, Heimlichkeit W10, Kämpfen W10, Okkultismus W12, Wahrnehmung W6, Zaubern W12, Überreden W6","b":"2","pa":"7","ro":"17","x":[["Handicaps","Verpeilt, Rachsüchtig (Schwer)"],["Talente","Arkaner Hintergrund (Magie), Konter, Keine Gnade, Energieschub"],["Mächte","Arkaner Schutz, Geschoss (Windstoß), Schwall (Windböe), Elementarkontrolle (meist Luft), Verstricken (Luftströmungen), Chaos (Wirbelsturm), Trägheit/Tempo (Luftströmungen) (Machtpunkte: 50)"]],"sf":[["Biss","Stä+W4."],["Ätherisch","Kann durch Objekte hindurchgehen; kann durch nichtmagische Angriffe nicht verletzt werden; kann als begrenzte freie Aktion unsichtbar werden (–6 auf Treffer)."],["Furcht (-2)","Wer die Kreatur sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Flug","Bewegungsweite 10."],["Größe 9 (Riesig)","Polypen werden bis zu 15 m lang."],["Wegschlagen","Ignoriert 4 Punkte Größenabzüge beim Angriff auf Kreaturen, die kleiner sind als sie selbst."],["Tentakel (2)","Zwei Tentakelaktionen und Reichweite 5 (10 m). Tentakel verursachen Stä+W4 Schaden. Gebundene oder Verstrickte Beute kann von den Mäulern in jedem Tentakel gebissen werden."]]},{"n":"Gug","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":192,"bk":"sw_hor","d":["Die Traumlande beherbergen Dutzende bizarrer Kreaturen, doch unter ihnen ist der Gug die schrecklichste. Vor Äonen von den Großen verbannt, leben sie nun tief unter der Erde in einer Stadt zyklopischer Türme und träumen von ihrer Rückkehr zur Größe, wobei sie Träume nutzen, um sich einen Weg zurück in die Welt zu erschleichen.","Gugs überragen Menschen, ihre muskulösen Körper starren vor grobem Fell. Jeder ihrer Arme spaltet sich am Ellbogen in zwei Arme, was ihnen praktisch vier Arme gibt. Ihre bezahnten Mäuler öffnen sich senkrecht und spalten den ganzen Kopf. Falls sie sprechen können, hat es niemand (Lebendes) bezeugt."],"a":[["Geschicklichkeit","W6"],["Konstitution","W10"],["Stärke","W12+3"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Athletik W8, Einschüchtern W6, Heimlichkeit W4, Kämpfen W8, Wahrnehmung W6","b":"6","pa":"6","ro":"15 (2)","x":[["Talente","—"]],"sf":[["Panzerung +2","Grobes Fell."],["Biss/Klauen","Stä+W6."],["Furcht (-2)","Wer einen Gug sieht, muss eine Furchtprobe mit –2 ablegen."],["Mehrere Arme","Gugs dürfen jeden Zug bis zu vier Kämpfen-Angriffe ohne Mehrfachaktionsabzug ausführen."],["Größe 6 (Groß)","Gugs sind etwa 6 m groß und wiegen so viel wie ein Elefant."],["Ganz verschlucken","Von einem Gug gebissene Opfer müssen eine Ausweichen-Probe ablegen oder werden Ganz Verschluckt (S. 101)."],["Wegschlagen","Ignoriert 4 Punkte Größenabzüge beim Angriff auf Kreaturen, die kleiner sind als sie selbst."]]},{"n":"Hund von Tindalos","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":193,"bk":"sw_hor","d":["Die Hunde stammen aus einer anderen Art von Zeit, die sich von unserer unterscheidet und normalerweise nicht aufspürbar ist. Ärger beginnt, wenn jemand durch Magie oder seltsame Wissenschaft in dieses andere Reich zu blicken vermag. Sobald er einen Hund wahrnimmt, sieht der Hund zurück und schleudert sich durch die Zeit, um seinen Beobachter zu verschlingen.","Die Reise dauert meist 1W4 Wochen, und aufgrund der seltsamen Physik muss die Kreatur aus einer spitzwinkligen Ecke von höchstens 120 Grad innerhalb von 12“ (24 m) von ihrer Beute hervortreten. Rauch kündigt die Ankunft der Kreatur an, und sie greift das Ziel und alle bei ihm an.","Hunde sehnen sich danach, ihre Beute zu verschlingen, sind aber nicht unerbittlich. Erleidet einer drei Wunden und erholt sich, bricht er die Jagd ab und versucht, durch eine Ecke zu entkommen. Gelingt ihm das, kehrt er nicht zurück, solange man ihn nicht erneut ausspäht."],"a":[["Geschicklichkeit","W10"],["Konstitution","W10"],["Stärke","W12+1"],["Verstand","W6 (A)"],["Willenskraft","W8"]],"f":"Athletik W10, Heimlichkeit W10, Kämpfen W10, Wahrnehmung W10, Überleben W10","b":"8","pa":"7","ro":"8","x":[["Handicaps","Blutrünstig"],["Talente","Flink, Raserei"]],"sf":[["Blindsinn","Ignoriert Unsichtbarkeit, Illusion und alle Beleuchtungsabzüge."],["Blutentzug","Ein Hund, der einen gepackten Feind Gebunden oder Verstrickt hält, spießt ihn mit seiner langen, hohlen Zunge auf. Jede Runde, die das Opfer aufgespießt bleibt, muss es Konstitution würfeln oder erleidet eine Stufe Erschöpfung, bis es entkommt oder stirbt. So verlorene Erschöpfung erholt sich einmal pro Tag mit einer reichhaltigen Mahlzeit. Wird das Packen gebrochen, wird die Zunge zurückgezogen. Ein Verbündeter kann auch versuchen, die Zunge zu durchtrennen (Robustheit 3), doch das zappelnde Opfer zählt für den Angriff als Unbeteiligter."],["Klauen","Stä+W6."],["Furcht","Wer einen Hund von Tindalos sieht, muss eine Furchtprobe ablegen."],["Gift (Säure)","Ein von einem Klauenangriff Erschüttertes oder Verwundetes Ziel muss eine Konstitutionsprobe ablegen oder erleidet die Wirkung von Tödlichem Gift (Betäubt und eine zusätzliche Wunde, zwei bei Kritischem Fehlschlag, und stirbt in 2W6 Runden)."],["Anspringen","Addiere +4 statt +2 auf den Schaden bei einem Rücksichtslosen Angriff."],["Regeneration (Schnell)","Natürlicher Heilungswurf jede Runde, außer bei Wunden durch Feuer oder Magie. Sie regenerieren nicht, sobald sie Ausgeschaltet sind."],["Größe 1","Hunde sind 1,80 m hoch an der Schulter und wiegen 180 kg."],["Teleportation","Ein Tindalos kann als Teil seiner Bewegung in jeder spitzen Ecke (90 Grad oder mehr) verschwinden. In der nächsten Runde geht Rauch von der Stelle aus, an der er am Ende seines Zugs auftaucht – jede andere spitze Ecke innerhalb einer Meile."],["Unaufhaltsam","Erleidet pro schadenverursachendem Angriff maximal eine Wunde (nach Wurf auf Schaden wegstecken), es sei denn, die Aktionskarte des Angreifers ist ein Joker."],["Sehr widerstandsfähig","Kann zwei zusätzliche Wunden einstecken."]]},{"n":"Mi-Go","k":"Außerirdische","w":0,"s":["HOR"],"p":193,"bk":"sw_hor","d":["Diese schrecklichen Pilzwesen stammen von einem unbekannten Stern, haben aber seit Langem eine Kolonie auf dem Pluto, in den alten Texten „Yuggoth“ genannt. Ihre Körper sind vage insektenförmig, mit acht gegliederten Beinen, die in Scheren enden, einem Paar gummiartiger Flügel und einem gehirnartigen Kopf, der zur Verständigung mit Artgenossen die Farben wechselt. Sie können menschliche Sprache nachahmen, wenn auch mit einem verstörenden Insektensummen.","Mi-Go lassen sich nicht mit gewöhnlichen Mitteln fotografieren und überstehen das kalte Vakuum des Weltraums. Sie sind berüchtigt dafür, sich in die menschliche Zivilisation einzumischen, oft mit menschlichen Mittelsmännern oder Kulten, um ihre finsteren Ziele zu erreichen. Als hervorragende Chirurgen können sie zudem ein menschliches Gehirn entnehmen und unbegrenzt in einem speziellen Metallzylinder am Leben halten, der an Geräte angeschlossen werden kann, mit denen es sehen, hören und mit anderen interagieren kann."],"a":[["Geschicklichkeit","W6"],["Konstitution","W6"],["Stärke","W6"],["Verstand","W8"],["Willenskraft","W8"]],"f":"Allgemeinwissen W4, Athletik W6, Elektronik W6, Heilen W10, Heimlichkeit W8, Kämpfen W6, Naturwissenschaften W8, Okkultismus W8, Psionik W8, Reparieren W6, Wahrnehmung W6, Überreden W6","b":"6","pa":"5","ro":"9 (2)","x":[["Talente","Arkaner Hintergrund (Psionik), Heiler"],["Mächte","Geschoss, Verwirrung, Arkanes aufspüren/verbergen, Umweltschutz, Illusion, Unsichtbarkeit, Licht/Dunkelheit, Gedankenlesen, Gestaltwandel, Sprache sprechen, Betäubung, Teleportation (Machtpunkte: 15)"]],"sf":[["Außerirdische Physiologie","+2 auf Erholung von Erschüttert; immun gegen Gift und Krankheit; halber Schaden durch nichtmagische Angriffe; kein zusätzlicher Schaden durch Gezielte Angriffe."],["Panzerung +2","Chitin-Außenskelett."],["Biss/Klauen","Stä+W4."],["Furcht (-2)","Wer einen Mi-Go sieht, muss eine Furchtprobe mit –2 ablegen."],["Flug","Bewegungsweite 12."],["Schwarmgeist","Mi-Go können telepathisch mit Artgenossen innerhalb von 10“ (20 m) kommunizieren."],["Größe 2","Mi-Go wiegen nur 135 kg, sind aber doppelt so groß wie ein Mensch und haben 6 m Flügelspannweite."]]},{"n":"Shoggoth","k":"Abscheulichkeiten","w":0,"s":["HOR"],"p":194,"bk":"sw_hor","d":["Wenige Kreaturen erregen solches Grauen wie der Shoggoth. Diese obszönen, gallertartigen, chaotischen Massen bilden ständig höhnische Augen, brabbelnde Münder, nässende Pusteln, peitschende Tentakel und kränkliche Arme und resorbieren sie wieder. Sie kriechen – oder rollen – über den Boden, angetrieben von ihren vielen Gliedmaßen. Erspähen sie Beute, kreischen ihre Münder eine Kakophonie von Worten in ihrer uralten Sprache."],"a":[["Geschicklichkeit","W6"],["Konstitution","W12+4"],["Stärke","W12+6"],["Verstand","W6"],["Willenskraft","W6"]],"f":"Athletik W10, Heimlichkeit W4, Kämpfen W10, Wahrnehmung W10","b":"6","pa":"7","ro":"16","x":[["Talente","—"]],"sf":[["Rundumsicht","Shoggothen können in alle Richtungen sehen. Sie ignorieren 1 Punkt Bonus für Gruppenangriff."],["Biss/Klauen","Stä+W4."],["Blob","+2 auf Erholung von Erschüttert; kein zusätzlicher Schaden durch Gezielte Angriffe; keine Wundabzüge; immun gegen Gift und Krankheit."],["Furcht (-2)","Wer einen Shoggoth sieht, muss eine Furchtprobe mit –2 ablegen."],["Unverwundbarkeit","Shoggothen sind immun gegen körperlichen Schaden. Durch Magie können sie wie üblich verletzt werden."],["Nachtsicht","Shoggothen ignorieren Abzüge für Dämmerlicht und Dunkelheit."],["Regeneration (Schnell)","Wurf auf Natürliche Heilung jede Runde, außer bei Wunden durch Feuer oder Magie."],["Größe 6 (Groß)","Shoggothen sind so groß wie Lastwagen und wiegen viele Tonnen."],["Tentakel (2)","Shoggothen können mit ihren Tentakeln für Stä+W6 Schaden zuschlagen."],["Schwäche","Shoggothen können durch Feuer und Elektrizität verletzt werden, einschließlich feuer- oder elektrizitätsbasierter Angriffe."]]},{"n":"Yith, die Große Rasse","k":"Außerirdische","w":0,"s":["HOR"],"p":194,"bk":"sw_hor","d":["Diese bizarren Monster entstanden, als psionische Wesen von einer fernen Welt vor Millionen von Jahren die Körper einer uralten, auf der Erde heimischen Art psionisch übernahmen. Ihre Körper sind kegelförmig, mit vier tentakelartigen Gliedmaßen, die aus der Spitze ihres Körpers wachsen. Zwei dieser Glieder enden in gezackten Scheren – mehr zur Handhabung ihrer seltsamen Technik als zum Kämpfen, aber dazu durchaus fähig. Ein weiteres Glied endet in einem Büschel roter Kegel, während das vierte von einem kugelförmigen Kopf mit mehreren Antennen gekrönt ist.","Obwohl sie furchterregend anzusehen sind, interessiert sich die Große Rasse (auch Yithianer genannt) mehr für wissenschaftliche Studien als dafür, Menschen zu beherrschen. Mit ihrer seltsamen psionischen Technik tauschen sie gern geistig über Äonen hinweg die „Plätze“ mit einem ausgewählten menschlichen Ziel, bewohnen den Körper ihres Subjekts und schicken dessen Geist für eine Weile in den eigenen Körper zurück. Das geschieht zu Forschungszwecken, und der Geist des Subjekts wird danach gelöscht, doch das hindert die Erfahrung nicht daran, noch Jahre später in seine Träume zu sickern.","Als Meister von Geist und seltsamer außerirdischer Technik tragen Yithianer manchmal Ausrüstung, deren Zweck Menschen völlig unergründlich ist. Diese Gegenstände dienen als Ausdrucksform für die psionischen Kräfte des Yithianers.","Ein Yithianer erhält –2 auf die Aktivierung seiner Kräfte, wenn er nicht das richtige Werkzeug hat."],"a":[["Geschicklichkeit","W4"],["Konstitution","W12"],["Stärke","W12+3"],["Verstand","W12"],["Willenskraft","W8"]],"f":"Akademisches Wissen W10, Allgemeinwissen W6, Athletik W4, Heilen W6, Heimlichkeit W4, Kämpfen W4, Naturwissenschaften W12, Okkultismus W10, Psionik W10, Reparieren W8, Schießen W6, Wahrnehmung W10","b":"6","pa":"4","ro":"19 (4)","x":[["Talente","Arkaner Hintergrund (Psionik), McGyver, Mentalist"],["Mächte","Arkaner Schutz, Eigenschaft steigern/senken, Schwall, Ablenkung, Magiebannen, Verstricken, Umweltschutz, Illusion, Gedankenverbindung, Gedankenlesen, Gedächtnis löschen, Marionette, Schlummer, Sprache sprechen (Machtpunkte: 20)"],["Ausrüstung","Blitzgewehr (Reichweite 30/60/120, Schaden 3W6, FR 3, PB 2)"]],"sf":[["Panzerung +4","Schuppige Haut."],["Klauen","Stä+W6."],["Furcht (-2)","Wer einen Yithianer sieht, muss eine Furchtprobe mit –2 ablegen."],["Mehrere Arme","Yithianer dürfen jeden Zug bis zu zwei Kämpfen-Angriffe ohne Mehrfachaktionsabzug ausführen."],["Größe 7 (Groß)","Yithianer überragen Menschen. Ihre kegelförmigen Körper sind über 6 m hoch, und die Gliedmaßen können sich weitere 3 m darüber strecken."]]},{"n":"Der Große Cthulhu","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":195,"bk":"sw_hor","d":["Cthulhu kam von den Sternen, als die Erde jung war. Er beherrschte den Planeten eine Zeit lang und beeinflusste die Vorfahren der Menschheit, bevor er in einen todlosen Schlaf fiel. Irgendwo in den tiefen Ozeanen der Welt träumt er, berührt die Geister seiner Anbeter und lehrt sie dunkle Kräfte. Diese Wesen (manche Menschen, manche ganz sicher nicht) glauben, sie würden belohnt (oder zumindest verschont), wenn der mächtige Cthulhu erwacht.","Cthulhus Gestalt ist vor allem von Statuen bekannt, die Wesen schufen, die älter sind als der Mensch. Er ist vage humanoid, mit grausam bekrallten Händen und Füßen, Flügeln und einem gespenstischen Gewirr aus Tentakeln und Fühlern um den Mund. Die Materie seines ruhenden Körpers hat seltsame Eigenschaften, die der Wissenschaft unbekannt sind."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12+6"],["Stärke","W12+10"],["Verstand","W12+2"],["Willenskraft","W12+4"]],"f":"Allgemeinwissen W12, Athletik W12, Einschüchtern W12+6, Heimlichkeit W4, Kämpfen W12, Psionik W12+2, Wahrnehmung W12, Überreden W8","b":"12","pa":"8","ro":"31 (8)","x":[["Talente","Arkane Resistenz (Verb.), Rohling, Energieschub"],["Mächte","Elementarkontrolle, Illusion, Gedankenlesen und Marionette. Cthulhu kennt alle Mächte – die genannten sind nur seine häufigsten – und nutzt Psionik für arkane Fertigkeitswürfe (Machtpunkte: 100)"]],"sf":[["Wasserwesen","Bewegungsweite 24."],["Panzerung +8","Schuppiger Körper. Schwere Panzerung."],["Klauen","Stä+W8; Schwere Waffe."],["Furcht (-6)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –6 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Flug","Bewegungsweite 24."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Regeneration (Schnell)","Natürlicher Heilungswurf jede Runde, außer bei Wunden durch rituelle Magie, die die SL genehmigt."],["Größe 12 (Gigantisch)","Der Große Cthulhu ist über 30 m groß."],["Ganz verschlucken","Wer von einem Tentakelangriff getroffen wird, muss eine Ausweichen-Probe ablegen oder wird Ganz Verschluckt (S. 101)."],["Telepathie","Cthulhu kann mit Wesen auf der ganzen Erde geistig kommunizieren. Selbst im Schlaf liest er Gedanken auf dem ganzen Planeten und beeinflusst die Träume ausgewählter Individuen."],["Tentakel (4)","Stä+W8, Schwere Waffe. Die vielen Fühler und Tentakel, die von Cthulhus Gesicht herabhängen, reichen nur bis zu seinem Bauch, kommen aber ins Spiel, wenn er sich herabbeugt oder Feinde hoch genug klettern."],["Unaufhaltsam","Erleidet pro schadenverursachendem Angriff maximal eine Wunde (nach Wurf auf Schaden wegstecken), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]},{"n":"Der König in Gelb","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":196,"bk":"sw_hor","d":["Der König ist ein Avatar von „Ihm, der nicht genannt werden darf“, der Künstler und Schriftsteller zu faszinieren pflegt. Diese erschaffen wiederum Theaterstücke oder Werke mit dem König, um andere anzulocken, bevor sie schließlich den Verstand verlieren. Solche Werke zeigen das Gelbe Zeichen, ein Symbol, das sowohl Warnung als auch Köder ist.","Das Wesen selbst wird als menschliche Gestalt in zerlumpten gelben Roben beschrieben, das Gesicht von einer Maske bedeckt. Berichte in den Werken, die den König beschreiben, legen nahe, dass die Roben sein Fleisch sind und er überhaupt keine Maske trägt."],"a":[["Geschicklichkeit","W8"],["Konstitution","W12+4"],["Stärke","W12+2"],["Verstand","W12+2"],["Willenskraft","W12+8"]],"f":"Allgemeinwissen W8, Athletik W8, Einschüchtern W12+4, Heimlichkeit W4, Kämpfen W10, Provozieren W12+2, Wahrnehmung W6, Überreden W10","b":"6","pa":"7","ro":"18","x":[["Talente","Arkane Resistenz (Verb.), Aufwiegler, Rundumschlag (Verb.)"]],"sf":[["Klauen","Stä+W4, Reichweite 2."],["Entziehende Berührung","Jeder Charakter, der den König in Gelb berührt, verliert 1W6 Machtpunkte. Ein Treffer durch Klauen oder den Klingenwirbel zählt als Berührung, wenn das Ziel Erschüttert oder schlimmer ist."],["Verzückung","Jeder Charakter muss jeden Zug entscheiden, ob er riskiert, den König in Gelb anzusehen, oder seine Augen abschirmt. Das Abschirmen der Augen macht den Charakter Abgelenkt, er kann aber sonst normal handeln und angreifen. Wer seinen Zug nicht normal nimmt, muss Ausweichen würfeln oder erleidet das Antlitz des Wahnsinns (siehe unten)."],["Antlitz des Wahnsinns","Wer direkt in das Gesicht des Königs in Gelb blickt, muss eine neue Furchtprobe würfeln. Siehe Verzückung oben, um sich mit dem König einzulassen, ohne sein Gesicht zu sehen."],["Furcht (-2)","Wer auch nur die Silhouette des Königs zum ersten Mal sieht, muss eine Furchtprobe mit –2 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Wahnsinnig","Ein Charakter, der versucht, den Geist des Königs in Gelb durch arkane Kräfte wie Marionette zu beeinflussen, scheitert automatisch, und der Zaubernde senkt dauerhaft seinen Verstand um einen Würfeltyp. Sinkt der Verstand unter W4, erleidet das Opfer einen Psychotischen Schub (siehe die Tabelle Furchteffekte auf S. 43)."],["Klingenwirbel","Als Aktion kann sich der König in Gelb drehen, und die Fetzen seiner Robe schneiden jeden, der zu nah steht. Alle Ziele in einer auf den König zentrierten Mittleren Flächenschablone müssen Ausweichen würfeln oder erleiden 3W6 Schaden, bei Kritischem Fehlschlag 4W6."],["Regeneration (Schnell)","Wurf auf Natürliche Heilung jede Runde, außer bei Wunden durch Feuer oder Magie."],["Robustheit +8","Die Roben des Königs in Gelb sind nicht genau eine Panzerung, bieten aber dennoch Schichten extrem zäher Schutzwirkung."]]},{"n":"Nyarlathotep","k":"Abscheulichkeiten","w":1,"s":["HOR"],"p":197,"bk":"sw_hor","d":["Manchmal Das Kriechende Chaos genannt, ist Nyarlathotep der Adjutant und Bote der Äußeren Götter. Anders als diese Wesen ist er sich der Menschen bewusst und interagiert auf verschiedene Weise direkt mit ihnen: Er lehrt Magie, ermöglicht Anbetung und inszeniert ironische Tode. Er verabscheut Menschen und befasst sich nur zu seinen eigenen dunklen Zwecken mit ihnen.","Nyarlathotep handelt Menschen sein gewaltiges mystisches Wissen oder die Dienste seiner Schergen (beschworene Mythoswesen) aus. Er verachtet die Äußeren Götter, denen er dient, ebenso wie die Menschen, die nach ihnen greifen, und verteilt seine „Gaben“ so, dass sie für beide das größte Chaos verursachen."],"a":[["Geschicklichkeit","W10"],["Konstitution","W12+4"],["Stärke","W12+6"],["Verstand","W12+8"],["Willenskraft","W12+4"]],"f":"Allgemeinwissen W12, Athletik W10, Einschüchtern W12, Heimlichkeit W8, Kämpfen W10, Okkultismus W12, Provozieren W12, Wahrnehmung W12, Zaubern W12+6, Überreden W12","b":"6","pa":"7","ro":"20","x":[["Talente","Arkane Resistenz (Verb.), Kanalisieren, Energieschub"],["Mächte","Geschoss, Verkleidung, Machtpunkte entziehen, Elementarkontrolle, Illusion, Gedankenlesen, Marionette, Gestaltwandel und Verbündeten beschwören. Nyarlathotep kennt alle Mächte und Rituale – die genannten sind nur seine häufigsten – und nutzt Zaubern für arkane Fertigkeitswürfe (Machtpunkte: 100)"]],"sf":[["Handel","Nyarlathotep kann leicht dieselben kleinen Handel eingehen wie Dämonen (siehe den Abschnitt Aufgaben auf S. 83). Er kann auch gewichtigere Geschäfte abschließen, tut das aber nur, wenn das Ergebnis das unvermeidliche und anhaltende Leiden mehrerer Menschen bedeutet."],["Klauen","Stä+W8; Schwere Waffe."],["Furcht (-6)","Jeder, der die Kreatur sieht, muss eine Furchtprobe mit –6 ablegen."],["Furchtlos","Immun gegen Furcht und Einschüchtern."],["Zäh","Ist er bereits Erschüttert, haben weitere Erschüttert-Ergebnisse keine Wirkung."],["Menschliche Tarnung","Nyarlathotep kann menschliche Gestalt annehmen, um besser mit Kultisten und Wissenssuchern zu interagieren. Als Mensch verliert er die +10 Robustheit und zwei Wunden seiner normalen Größe und verursacht keine Furcht mehr. Wird seine menschliche Gestalt getötet, kehrt er in seine monströse Gestalt zurück, erhält die zusätzlichen Wunden und Robustheit zurück und verursacht sofort Furcht."],["Regeneration (Schnell)","Natürlicher Heilungswurf jede Runde, außer bei Wunden durch rituelle Magie, die die SL genehmigt."],["Größe 10 (Riesig)","In seiner monströsen Gestalt ist Nyarlathotep über 18 m groß."],["Unaufhaltsam","Erleidet pro schadenverursachendem Angriff maximal eine Wunde (nach Wurf auf Schaden wegstecken), es sei denn, die Aktionskarte des Angreifers ist ein Joker."]]}]);
Object.assign(SW_BEST.gr.g, {"Tierhybriden": ["Hybriden sind das Ergebnis verrückter Wissenschaftler, die mit Genetik, dunkler Magie oder anderer „Technologie“ herumpfuschen. Die meisten sind halb Mensch, halb Tier, einige jedoch eine Mischung aus zwei Tierarten.", "Ein Hybrid besitzt alle Handicaps, Talente und Spezialfähigkeiten beider Arten. Haben beide Arten gemeinsame Fähigkeiten, etwa Klauen oder Panzerung, wird der höhere Wert verwendet. Hybriden haben stets auch die Spezialfähigkeit Furcht.", "Eigenschaften funktionieren etwas anders. Liegt eine zwei oder mehr Stufen über der anderen, wird sie um eine Stufe gesenkt und für die Kreatur verwendet. Andernfalls gilt die höhere Eigenschaft unverändert. Unterscheidet sich die Bewegungsweite, werden beide Werte addiert und halbiert, abgerundet.", "Beispiel: Ein Alligator hat Willenskraft W6 und ein Löwe Willenskraft W10. Da die Willenskraft des Löwen zwei Stufen höher ist, wird sie um eine Stufe auf W8 gesenkt und für die Bestie verwendet. Die Konstitution unterscheidet sich dagegen nur um eine Stufe (W10 gegenüber W8), also gilt W10."], "Auserwählte Jäger": ["Viele sind berufen, aber die meisten sterben, bevor sie sich beweisen können. Ob ein Auserwählter Jäger ein forsches junges Mädchen auf Vampirjagd ist oder ein harter Kerl mit modernster Technik, hängt von deinem Setting ab. Allen gemeinsam ist die Berufung, einer höheren Macht zu dienen."], "Kultisten": ["Die sterblichen Anbeter wahnsinniger Götter, Dämonen und anderer übernatürlicher Wesen können gerissene Intriganten, tobende Irre, ihrem Meister ergebene Fanatiker oder eine tödliche Mischung aus allem sein."], "Dunkle Götter": ["In jedem Setting folgen empfindungsfähige Völker wahrscheinlich Göttern. Manche sind allmächtige Wesen ohne wahre körperliche Gestalt, die ihren vertrautesten Anhängern besondere Kräfte verleihen können. Andere sind Halbgötter, Heilige oder mächtige Geister.", "Ob es sich um Superaliens, Wesen aus einer anderen Dimension, Dämonenfürsten oder Avatare wahrer Götter handelt, entscheidet die Spielleitung. Viele nutzen ihre Anhänger, um eigene Ziele zu erreichen (etwa auf die Erde beschworen zu werden), und verschlingen sie dann ohne einen Gedanken.", "Nachfolgend einige Beispiele, die dir helfen, eigene bösartige Gottheiten zu erschaffen. Ein so mächtiges Wesen zurückzudrängen, erfordert meist die Störung des Rituals, das es beschworen hat, oder ein noch größeres Ritual, wenn dieses bereits stattgefunden hat.", "Einen dunklen Gott zu erschlagen ist praktisch unmöglich. „Praktisch“ heißt natürlich, dass es einen Weg gibt, doch sowohl das verbotene Wissen als auch das dafür nötige Opfer sollten mindestens doppelt so schwer sein wie die Beschwörung des Wesens."], "Dämonen (Horror)": ["Dämonen und Teufel können je nach Setting Diener der Hölle oder Gefolgsleute böser Götter sein. Unabhängig von ihrer Herkunft sind sie übernatürliche böse Wesen ohne jede positive Eigenschaft, auch wenn manche gute Tugenden vortäuschen, um ahnungslose Beute ins Verderben zu locken.", "Dämonen sprechen viele Sprachen, darunter eine dämonische Zunge, die Sterbliche, die nicht mit den dunklen Künsten zu tun haben, selten sprechen. Ob sie sich herablassen, mit niederen Sterblichen zu reden, ist ihre persönliche Entscheidung."], "Golems (Horror)": ["Golems sind künstliche Kreaturen, geschaffen mit Magie und Pseudowissenschaft. Manche, wie der Lehmgolem von Prag, wurden als Diener erschaffen. Andere sind Versuche, Wächter oder mörderische Automaten zu bauen.", "Wenige vernünftige Männer der Wissenschaft glauben an solche Schöpfungen, und noch weniger haben die Mittel, das Geschick oder den Drang, sich an ihrer Herstellung zu versuchen. Solche Ungeheuer werden häufiger von verrückten Wissenschaftlern, Nekromanten und Verirrten erschaffen. Echte Golems können nicht sprechen."], "Vetteln": ["Obwohl sie oft für Hexen gehalten werden, sind „Vetteln“ keine Menschen – oder nicht mehr. Manche ähneln eher Trollen mit hexenartigen Kräften, andere waren einst Frauen oder sogar echte Hexen, die zu etwas weit Abscheulicherem und Verderbterem wurden.", "Siehe S. 173 für echte Hexen, oft missverstandene Zauberwirkende, die von Einheimischen gefürchtet werden und mit denen diese nur aus schierer Verzweiflung verhandeln. Vetteln sind die gackernden Unholde, die die Einheimischen wirklich fürchten sollten."], "Mumien (Horror)": ["Mumien sind Untote, deren Körper durch Wissenschaft und Zauberei getrocknet und konserviert wurden. Manche sind natürlich konserviert, die meisten aber von Menschenhand geschaffen.", "Natürliche Mumien erlangen beim Erwachen meist einen Anschein der Seele zurück. Bei künstlichen Mumien ist der Geist durch mächtige nekromantische Rituale, die nur wenige Priester kennen, an den Leichnam gebunden. Die meisten stammen aus Ägypten, doch auch die alten mesoamerikanischen und chinesischen Kulturen praktizierten Mumifizierung.", "In beiden Fällen werden schwächere Willen durch ihren ausgetrockneten Zustand wahnsinnig und wütend. Stärkere Willen behalten volles Bewusstsein und Zugriff auf alle Fertigkeiten und Fähigkeiten, die sie im Leben hatten (etwa Zaubern).", "Mumien erwachen, wenn ein bestimmtes Ereignis ausgelöst wird. Das kann das Auftragen von Menschenblut sein, magische Machtworte, das Auftauen des Fleisches einer gefrorenen Mumie oder das Befeuchten des Gewebes eines getrockneten Leichnams. Der genaue Auslöser liegt bei der SL, doch sobald die Mumie sich erhebt, hört sie erst auf, wenn sie tot ist oder ihr Ziel (falls vorhanden) erreicht ist."], "Polizei": ["Dorfpolizisten, Polizeibeamte oder andere Obrigkeiten sind nützliche Verbündete oder heikle Feinde, da der Kampf gegen böse Kultisten, Monster und andere Bedrohungen oft erfordert, das Gesetz selbst in die Hand zu nehmen. Die Welt vor einem dunklen Gott zu retten ist schließlich vor Gericht schwer zu beweisen."], "Tollwütige Tiere": ["Tollwut ist eine Erkrankung des Zentralnervensystems und kann bei jedem warmblütigen Tier auftreten. In der realen Welt findet man sie meist bei kleineren Tieren wie Fledermäusen oder Waschbären, doch in einem Horrorspiel spricht nichts dagegen, dass auch eine größere Kreatur die Krankheit hat.", "Um ein tollwütiges Tier zu erschaffen, füge die Fähigkeiten Berserker, Furchtlos, Infektion und Schwäche (Wasser) hinzu, wie im Beispielwesen unten gezeigt."], "Serienmörder": ["Anders als im echten Leben sind Serienmörder in den meisten Horror-Settings nicht der stille Typ von nebenan. Diese Monster fallen in der Menge auf, oft wegen ihrer seltsamen Kleidung, blutgetränkten Gewänder und charakteristischen Waffen!"], "Skelett-Tiere": ["Die Macht Zombie ist nicht auf Menschen und andere empfindungsfähige Wesen beschränkt – sie wirkt auch auf die Skelettreste von Tieren. Während Menschenskelette nützliche Diener sind, ist ein aus dem örtlichen Museum erweckter Zombie-T-Rex ein tödlicher Gegner."], "Schwärme": ["Manchmal kommen die tödlichsten Feinde in den kleinsten Päckchen. Schwärme aus Ratten, Fledermäusen, Spinnen oder anderem Gewürm bedecken je nach Anzahl der Kreaturen eine Fläche gleich einer Großen, Mittleren oder Kleinen Flächenschablone. Manche teilen sich, wenn sie Verwundet werden – ein Großer wird zu zwei Mittleren, ein Mittlerer zu zwei Kleinen, und ein Kleiner löst sich auf.", "Schwärme verursachen zu Beginn ihres Zugs automatisch ihren aufgeführten Schaden bei allen in ihrer Schablone.", "Schwärme sind meist nicht intelligent genug, um mehr als sich zu bewegen und zu beißen, und sollten keine Mehrfachaktionen ausführen, Tests ablegen usw. Manche Arten von Schwärmen lassen sich durch völliges Eintauchen in Wasser oder eine gefürchtete Umgebung vereiteln."], "Vampire": ["Vampire gibt es in praktisch jeder Kultur. Vom Mrart der australischen Aborigines über das Adze von Ghana und Togo in Afrika bis zu den hüpfenden Vampiren Chinas und dem Mara Skandinaviens plagen Vampire die Menschheit, seit es sie gibt."], "Wendigos": ["So abscheulich es ist, greifen Menschen bei drohendem Hungertod manchmal zu Kannibalismus. Für die meisten ist es eine Frage des Überlebens, die sie nach ihrer Rettung nie wieder versuchen. Für einige wird es jedoch zur Gier. Diese Personen sollen vom Geist des Wendigo besessen sein, eines Kannibalengeistes der amerikanischen Indianer."], "Werwesen": ["Gestaltwandler tauchen in der Mythologie vieler Kulturen auf. Die Südamerikaner glauben an Jaguarmenschen, Werwölfe werden in Europa gefürchtet, und bestimmte Stämme des Südpazifiks glauben, Haimenschen streiften durch die Tiefen.", "Auf den folgenden Seiten stehen mehrere Arten von Gestaltwandlern, die du unverändert nutzen oder für eigene Varianten abwandeln kannst. Wenn nicht anders angegeben, haben alle Werwesen eine Schwäche gegen Silber: • Infektion: Wer von einem Lykanthropen getötet wird, erhebt sich mit 50 % Wahrscheinlichkeit selbst als einer. Das Opfer verwandelt sich bei jedem Vollmond und erlangt erst nach 1W6 Jahren Kontrolle über seinen Zustand. • Infrarotsicht: Halbiere Beleuchtungsabzüge beim Angriff auf warme Ziele. • Regeneration (Langsam): Lykanthropen dürfen jeden Tag einen natürlichen Heilungswurf versuchen. • Schwäche (Silber): –4 Widerstand / +4 Schaden durch Silbereffekte und -waffen."], "Xenoform": ["Der klassische Horror-Xenoform ist humanoid, mit dickem Knochen- oder Chitinpanzer bedeckt und für die Jagd aus nächster Nähe ausgerüstet. Er hat keine erkennbaren Augen, die die Beute ausstechen könnte, aber einen kräftigen, ausfahrbaren Kiefer und scharfe Klauen. Zudem hat er einen Schwanz mit Widerhakenstachel, mit dem er seine Beute festnagelt."], "Zombies (Horror)": ["Zombies, oder die wandelnden Toten, wenn du willst, sind ein Grundpfeiler vieler Horror-Settings. Sie sind großartige Handlanger niederer Stufe. Dieser Abschnitt betrachtet verschiedene Arten von Zombies, die an den dunkelsten Orten auferstehen könnten."]});
